try { console.log("OSIRIS ITER 40 SCRIPT LOADED"); } catch (e) {}

/* =====================================================================
 * iter-40-diag — on-page debug overlay for iPhone Safari (no Mac needed).
 *
 * Activation:
 *   - URL param  ?osirisdebug=1   (sticky for the page-load)
 *   - or run  localStorage.setItem("osiris_debug","1")  then reload
 * Deactivation:
 *   - Tap the ×  (also clears localStorage flag)
 *   - or run  localStorage.removeItem("osiris_debug")  then reload
 *
 * Behaviour:
 *   - Captures every console.log("[OSIRIS …") and "OSIRIS ITER 40 …"
 *     line and pins it to a fixed panel at the top of the page.
 *   - Tap the panel body → selects + copies the full log to clipboard
 *     so it can be pasted into an email/iMessage back to the agent.
 *   - Tap "Share" → opens the iOS share sheet pre-filled with the log
 *     (uses navigator.share when available).
 *   - Zero impact when not activated. No PII; password values are
 *     never captured (the diagnostic emitters log only LENGTHS).
 * ===================================================================== */
(function () {
  try {
    var on = /[?&]osirisdebug=1/.test(location.search) ||
             (function () { try { return localStorage.getItem("osiris_debug") === "1"; } catch (e) { return false; } })();
    if (!on || window.__osirisDebugInstalled) return;
    window.__osirisDebugInstalled = true;
    try { localStorage.setItem("osiris_debug", "1"); } catch (e) {}

    var lines = [];
    var bodyEl;

    function _ts() { return new Date().toTimeString().slice(0, 8); }
    function _fmt(args) {
      var parts = [];
      for (var i = 0; i < args.length; i++) {
        var a = args[i];
        try { parts.push(typeof a === "string" ? a : JSON.stringify(a)); }
        catch (e) { parts.push(String(a)); }
      }
      return parts.join(" ");
    }
    function _redraw() {
      if (bodyEl) bodyEl.textContent = lines.slice(-40).join("\n");
    }
    function _push(line) { lines.push(line); _redraw(); }
    function _allText() { return lines.join("\n"); }

    function _mount() {
      if (document.getElementById("osiris-debug-overlay")) return;
      if (!document.body) { setTimeout(_mount, 50); return; }

      var panel = document.createElement("div");
      panel.id = "osiris-debug-overlay";
      panel.setAttribute("style",
        "position:fixed;top:0;left:0;right:0;max-height:55vh;overflow:auto;" +
        "background:rgba(0,0,0,0.94);color:#9fff9f;font:11px/1.35 ui-monospace,Menlo,monospace;" +
        "padding:6px 8px;z-index:2147483647;border-bottom:2px solid #0f0;" +
        "white-space:pre-wrap;word-break:break-all;-webkit-user-select:text;user-select:text");

      var hdr = document.createElement("div");
      hdr.setAttribute("style", "display:flex;justify-content:space-between;align-items:center;gap:6px;margin-bottom:4px;color:#0ff;font-weight:700");
      var title = document.createElement("span");
      title.textContent = "OSIRIS DEBUG · tap log to copy";
      hdr.appendChild(title);

      var btns = document.createElement("span");
      btns.setAttribute("style", "display:flex;gap:6px");

      function _mkBtn(label, handler) {
        var b = document.createElement("button");
        b.textContent = label;
        b.setAttribute("style", "background:transparent;border:1px solid #0ff;color:#0ff;padding:2px 8px;font:inherit;cursor:pointer;border-radius:4px;-webkit-appearance:none");
        b.onclick = handler;
        return b;
      }

      btns.appendChild(_mkBtn("Share", function (ev) {
        ev.stopPropagation();
        var text = _allText();
        if (navigator.share) {
          navigator.share({ title: "OSIRIS Safari diagnostic", text: text })
            .catch(function () {});
        } else {
          // Fallback: copy + show hint.
          _tryCopy(text, "Copied (share unavailable)");
        }
      }));
      btns.appendChild(_mkBtn("Clear", function (ev) {
        ev.stopPropagation();
        lines.length = 0; _push(_ts() + " (log cleared)");
      }));
      btns.appendChild(_mkBtn("×", function () {
        try { localStorage.removeItem("osiris_debug"); } catch (e) {}
        try { panel.remove(); } catch (e) {}
      }));
      hdr.appendChild(btns);
      panel.appendChild(hdr);

      bodyEl = document.createElement("pre");
      bodyEl.setAttribute("style", "margin:0;color:#9fff9f;font:inherit;white-space:pre-wrap;word-break:break-all");
      bodyEl.onclick = function () { _tryCopy(_allText(), "✓ copied — paste back to chat"); };
      panel.appendChild(bodyEl);

      document.body.appendChild(panel);
      _redraw();
    }

    function _tryCopy(text, hintMsg) {
      var done = false;
      try {
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(text).then(function () { _flashHint(hintMsg); }, function () { _legacyCopy(text, hintMsg); });
          done = true;
        }
      } catch (e) {}
      if (!done) _legacyCopy(text, hintMsg);
    }
    function _legacyCopy(text, hintMsg) {
      try {
        var ta = document.createElement("textarea");
        ta.value = text;
        ta.setAttribute("readonly", "");
        ta.style.cssText = "position:absolute;left:-9999px;top:0";
        document.body.appendChild(ta);
        ta.select(); ta.setSelectionRange(0, text.length);
        document.execCommand("copy");
        ta.remove();
        _flashHint(hintMsg);
      } catch (e) { _flashHint("Copy failed — long-press to select manually"); }
    }
    function _flashHint(msg) {
      try {
        var h = document.createElement("div");
        h.textContent = msg || "✓";
        h.setAttribute("style", "position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);background:#0f0;color:#000;padding:8px 14px;border-radius:6px;font:600 14px ui-monospace,Menlo,monospace;z-index:2147483647");
        document.body.appendChild(h);
        setTimeout(function () { try { h.remove(); } catch (e) {} }, 1400);
      } catch (e) {}
    }

    // Capture matching console.log lines.
    var origLog = console.log ? console.log.bind(console) : function () {};
    console.log = function () {
      try {
        var first = arguments[0];
        if (typeof first === "string" && /^(\[OSIRIS|OSIRIS ITER|\[PRE-FILL)/.test(first)) {
          _push(_ts() + " " + _fmt(arguments));
        }
      } catch (e) {}
      try { origLog.apply(console, arguments); } catch (e) {}
    };

    _push(_ts() + " OSIRIS DEBUG OVERLAY ACTIVE — paste this whole block back");
    _push(_ts() + " UA: " + String(navigator.userAgent || ""));
    _push(_ts() + " URL: " + String(location.href || ""));
    _push(_ts() + " backend: " + (window.OSIRIS_API_URL || "(unset)"));
    try {
      _push(_ts() + " storage: " + JSON.stringify({
        tokenPresent:  !!localStorage.getItem("osiris_messenger_token"),
        tokenLength:   (localStorage.getItem("osiris_messenger_token") || "").length,
        loggedInFlag:  localStorage.getItem("loggedIn"),
        legacyAccountsPresent: !!localStorage.getItem("osiris_accounts")
      }));
    } catch (e) {
      _push(_ts() + " storage: ACCESS BLOCKED (private mode?)");
    }

    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", _mount);
    } else {
      _mount();
    }
  } catch (e) {
    /* never break the page because of the debugger */
  }
})();

/* =====================================================================
 * Radiology image preview + delete — mobile-hardened.
 *
 * Bug history: on iOS Safari, selecting a photo only showed the
 * filename in the file-input control; the preview never appeared.
 * Root causes addressed here:
 *
 *   1. FileReader can silently stall on iOS for HEIC photos or large
 *      images, leaving `onload` unfired. Fix: try `URL.createObjectURL`
 *      first (synchronous, supports HEIC, no async race), keep
 *      FileReader as a fallback.
 *   2. Some global stylesheet may pin `display: none !important` on
 *      the container via a non-`.hidden` selector. Fix: also clear
 *      inline `style.display` and toggle `style.display = "block"`
 *      explicitly when revealing.
 *   3. Calling preview twice would leak the previous object URL. Fix:
 *      revoke the prior URL stored on the preview's `dataset`.
 *   4. If neither strategy works, surface the failure in
 *      `#radiologyResult` so the user knows the upload didn't take —
 *      no more silent "filename only" state.
 *
 * Exact spec the user requested:
 *   - read the uploaded file
 *   - assign it to radiologyImagePreview.src
 *   - reveal radiologyPreviewContainer
 *   - show Delete Image together with the preview (Delete lives INSIDE
 *     the container, so it appears/disappears with it — no separate
 *     show/hide logic needed)
 *   - NOT inject the image into radiologyResult
 *   - NOT rely on the file input control as the image display
 * ===================================================================== */

function previewRadiologyImage() {
  var input     = document.getElementById("radiologyImage");
  var preview   = document.getElementById("radiologyImagePreview");
  var container = document.getElementById("radiologyPreviewContainer");
  var result    = document.getElementById("radiologyResult");

  if (!input || !preview || !container) return;

  var file = (input.files && input.files[0]) || null;
  if (!file) {
    // Nothing selected — make sure we're in the hidden baseline.
    _radiologyResetPreview(preview, container);
    return;
  }

  // Revoke any previous object URL to avoid a memory leak across
  // successive uploads (mobile Safari particularly).
  if (preview.dataset && preview.dataset.objectUrl) {
    try { URL.revokeObjectURL(preview.dataset.objectUrl); } catch (e) {}
    preview.dataset.objectUrl = "";
  }

  // Strategy 1 — URL.createObjectURL (synchronous; HEIC-safe on iOS).
  var usedObjectUrl = false;
  try {
    if (typeof URL !== "undefined" && URL.createObjectURL) {
      var url = URL.createObjectURL(file);
      preview.src = url;
      if (preview.dataset) preview.dataset.objectUrl = url;
      _radiologyRevealContainer(container);
      usedObjectUrl = true;
    }
  } catch (e) { usedObjectUrl = false; }

  if (usedObjectUrl) {
    // Preview uses a blob: URL for speed/HEIC; archive a durable data URL.
    if (typeof OSIRIS_eqrPersistRadiologyUpload === "function") {
      try { OSIRIS_eqrPersistRadiologyUpload(file); } catch (ePersist) {}
    }
    return;
  }

  // Strategy 2 — FileReader fallback for browsers/contexts that don't
  // expose URL.createObjectURL.
  try {
    var reader = new FileReader();
    reader.onload = function (ev) {
      try {
        preview.src = ev.target.result;
        _radiologyRevealContainer(container);
        if (typeof OSIRIS_eqrArchiveRadiologyImage === "function") {
          var meta = (typeof _radiologyReadSelectorsMeta === "function")
            ? _radiologyReadSelectorsMeta() : {};
          meta.fileName = (file && file.name) || "";
          meta.source = "radiology-upload";
          meta.ts = new Date().toISOString();
          OSIRIS_eqrArchiveRadiologyImage(ev.target.result, meta);
        }
        if (typeof window.OSIRIS_eqr2_refresh === "function") {
          try { window.OSIRIS_eqr2_refresh(); } catch (eRef) {}
        }
      } catch (e2) {
        if (result) result.innerHTML = "\u26d4 Unable to display preview. Please try a different image.";
      }
    };
    reader.onerror = function () {
      if (result) result.innerHTML = "\u26d4 Unable to read the selected file. Please try a different image.";
    };
    reader.readAsDataURL(file);
  } catch (e3) {
    if (result) result.innerHTML = "\u26d4 Image preview is not supported in this browser.";
  }
}

function _radiologyRevealContainer(container) {
  if (!container) return;
  container.classList.remove("hidden");
  // Defensive: also clear inline display in case anything pinned it.
  if (container.style && container.style.display === "none") {
    container.style.display = "";
  }
}

function _radiologyResetPreview(preview, container) {
  if (preview) {
    if (preview.dataset && preview.dataset.objectUrl) {
      try { URL.revokeObjectURL(preview.dataset.objectUrl); } catch (e) {}
      preview.dataset.objectUrl = "";
    }
    preview.src = "data:image/gif;base64,R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs=";
  }
  if (container) container.classList.add("hidden");
}

function deleteRadiologyImage() {
  // Clears ONLY the current Radiology upload/preview/result UI.
  // Does NOT remove any study already archived in EQUIREVITAL.
  var input     = document.getElementById("radiologyImage");
  var preview   = document.getElementById("radiologyImagePreview");
  var container = document.getElementById("radiologyPreviewContainer");
  var result    = document.getElementById("radiologyResult");

  if (input) input.value = "";
  _radiologyResetPreview(preview, container);
  // Also clear any result text from a previous analyse run.
  if (result) result.innerHTML = "";
}

if (typeof window !== "undefined") {
  window.previewRadiologyImage = previewRadiologyImage;
  window.deleteRadiologyImage  = deleteRadiologyImage;
}

