    var ctx = (typeof buildDiagnosticContext === "function") ? buildDiagnosticContext() : {};
    var already = OSIRIS_alreadyEnteredKeys(userProfile, ctx);
    if (!already.length) return;
    document.querySelectorAll(".result-output li, .osiris-result-block li, .osiris-test-block li").forEach(function (li) {
      var lc = (li.textContent || "").toLowerCase();
      if (already.some(function (k) { return lc.indexOf(k) !== -1; })) li.style.display = "none";
    });
