  if (!answers || typeof answers !== "object" || typeof document === "undefined") {
    return false;
  }
  var applied = false;
  function escAttr(s) {
    return String(s == null ? "" : s).replace(/\\/g, "\\\\").replace(/"/g, '\\"');
  }
