    var raw = answers[key];
    if (raw == null || raw === "") return;
    var vals = String(raw).split(/,\s*/).map(function (s) {
      return String(s || "").trim();
    }).filter(Boolean);
    if (!vals.length) return;
    var safeKey = escAttr(key);
    var msNodes = document.querySelectorAll(
      'input[type="radio"][data-osiris-multiselect="1"][data-osiris-base="' + safeKey + '"]'
    );
