  { id: "neutrophils", name: "Neutrophils", purpose: "infection pattern" },
  { id: "platelets", name: "Platelets", purpose: "clotting tendency" },
  { id: "ferritin", name: "Ferritin / Iron status", purpose: "iron reserve" }
