let systemFlags = {
  oxygenIssue: false,
  viscosityRisk: false,
  inflammation: false,
  clotRisk: false,
  inflammationMarker: false   // ← DODAJ TO
};

function updateCardioHematologyFlags() {
  const hemoglobin = parseFloat(document.getElementById("hemoglobin")?.value);
  const hematocrit = parseFloat(document.getElementById("hematocrit")?.value);
  const wbc = parseFloat(document.getElementById("wbc")?.value);
  const platelets = parseFloat(document.getElementById("platelets")?.value);

  systemFlags.oxygenIssue = false;
  systemFlags.viscosityRisk = false;
  systemFlags.inflammation = false;
  systemFlags.clotRisk = false;

  if (!isNaN(hemoglobin) && hemoglobin < 12) {
    systemFlags.oxygenIssue = true;
  }

  if (!isNaN(hematocrit) && hematocrit < 36) {
    systemFlags.oxygenIssue = true;
  }

  if (!isNaN(hematocrit) && hematocrit > 50) {
    systemFlags.viscosityRisk = true;
  }

  if (!isNaN(wbc) && wbc > 11) {
    systemFlags.inflammation = true;
  }

  if (!isNaN(platelets) && platelets > 400) {
    systemFlags.clotRisk = true;
  }
}

function updateCardioInflammationFlags() {
  const crp = parseFloat(document.getElementById("crp")?.value);

  systemFlags.inflammationMarker = false;

  if (!isNaN(crp) && crp > 5) {
    systemFlags.inflammationMarker = true;
  }
}

// Track selected conditions for display/storage
const preExistingConditions = [];

// Track selected condition IDs for cluster logic
let selectedConditionIds = [];

// DOM Elements
const dialog = document.getElementById("conditions-dialog");
const openDialogButton = document.getElementById("open-conditions-dialog");
const closeDialogButton = document.getElementById("close-dialog");
const conditionInput = document.getElementById("condition-input");
const autocompleteList = document.getElementById("autocomplete-list");
const selectedConditionsList = document.getElementById("selected-conditions");

// Open dialog
function _osirisSeedPreconditionsFromProfile() {
  // iter-61: idempotent reseeding of preExistingConditions /
  // selectedConditionIds / DOM from userProfile.
  try {
    var stored = (userProfile && userProfile.pre_existing_conditions && userProfile.pre_existing_conditions.selected) || [];
    preExistingConditions.length = 0;
    selectedConditionIds.length  = 0;
    if (!selectedConditionsList) return;
    selectedConditionsList.innerHTML = "";
    stored.forEach(function (label) {
      preExistingConditions.push(label);
      var match = null;
      try {
        Object.values(conditionsData).forEach(function (group) {
          group.forEach(function (c) {
            if (!match && c && c.label === label) { match = c; }
          });
        });
      } catch (e) {}
      var cid = match && match.id;
      if (cid && selectedConditionIds.indexOf(cid) < 0) selectedConditionIds.push(cid);
      var item = document.createElement("div");
      item.classList.add("condition-item");
      if (cid) item.setAttribute("data-condition-id", cid);
      item.innerHTML = '<span>' + (label || "") + '</span>' +
                       '<button class="delete-button">Remove</button>';
      item.querySelector(".delete-button").addEventListener("click", function () {
        var i = preExistingConditions.indexOf(label);
        if (i > -1) preExistingConditions.splice(i, 1);
        if (cid) {
          var j = selectedConditionIds.indexOf(cid);
          if (j > -1) selectedConditionIds.splice(j, 1);
        }
        item.remove();
        userProfile.pre_existing_conditions.selected = preExistingConditions.slice();
        saveUserProfile();
      });
      selectedConditionsList.appendChild(item);
    });
  } catch (e) { /* non-fatal */ }
}
window.OSIRIS_reseedPreconditions = _osirisSeedPreconditionsFromProfile;

openDialogButton.addEventListener("click", () => {
  _osirisSeedPreconditionsFromProfile();
  dialog.classList.add("active");
});

// Close dialog
closeDialogButton.addEventListener("click", () => {
  userProfile.pre_existing_conditions.selected = [...preExistingConditions];
  saveUserProfile();
  dialog.classList.remove("active");
});

// Handle input for autocomplete
conditionInput.addEventListener("input", () => {
  const query = conditionInput.value.toLowerCase().trim();
  autocompleteList.innerHTML = "";

  if (query) {
    const suggestions = [];

    Object.entries(conditionsData).forEach(([category, conditions]) => {
      conditions
        .filter((condition) => condition.label.toLowerCase().includes(query))
        .forEach((condition) => suggestions.push(condition));
    });

    suggestions.sort((a, b) => a.label.localeCompare(b.label));

    suggestions.forEach((condition) => {
      const suggestionItem = document.createElement("li");
      suggestionItem.textContent = condition.label;
      suggestionItem.addEventListener("click", () => selectCondition(condition));
      autocompleteList.appendChild(suggestionItem);
    });
  }
});

// Function to handle selecting a condition
function selectCondition(condition) {
  if (!preExistingConditions.includes(condition.label)) {
    preExistingConditions.push(condition.label);

    if (!selectedConditionIds.includes(condition.id)) {
      selectedConditionIds.push(condition.id);
    }

    const conditionItem = document.createElement("div");
    conditionItem.classList.add("condition-item");
    conditionItem.setAttribute("data-condition-id", condition.id);

    conditionItem.innerHTML = `
      <span>${condition.label}</span>
      <button class="delete-button">Remove</button>
    `;

    conditionItem
      .querySelector(".delete-button")
      .addEventListener("click", () => {
        const labelIndex = preExistingConditions.indexOf(condition.label);
        if (labelIndex > -1) preExistingConditions.splice(labelIndex, 1);

        const idIndex = selectedConditionIds.indexOf(condition.id);
        if (idIndex > -1) selectedConditionIds.splice(idIndex, 1);

        conditionItem.remove();

        userProfile.pre_existing_conditions.selected = [...preExistingConditions];
        saveUserProfile();
      });

    selectedConditionsList.appendChild(conditionItem);
  }

  conditionInput.value = "";
  autocompleteList.innerHTML = "";

  userProfile.pre_existing_conditions.selected = [...preExistingConditions];
  saveUserProfile();
}

function getConditionNotesForPattern(selectedConditionIds, patternName) {
  if (!Array.isArray(selectedConditionIds) || selectedConditionIds.length === 0) {
    return [];
  }

  const notes = [];

  selectedConditionIds.forEach(id => {
    const modifier = conditionModifiers[id];
    if (modifier && modifier.affects.includes(patternName)) {
      notes.push(modifier.note);
    }
  });

  return [...new Set(notes)];
}

