  ev.inflam = ev.crpHigh || ev.esrHigh || ev.hsCrpHigh;
  ev.tshHigh = OSIRIS_systemicFinite(ev.tsh) && ev.tsh > 4.0;
  ev.tshLow = OSIRIS_systemicFinite(ev.tsh) && ev.tsh < 0.4;
  ev.bpHighNum = (OSIRIS_systemicFinite(ev.sys) && ev.sys >= 140) ||
    (OSIRIS_systemicFinite(ev.dia) && ev.dia >= 90);
  ev.bpLowNum = (OSIRIS_systemicFinite(ev.sys) && ev.sys < 90) ||
    (OSIRIS_systemicFinite(ev.dia) && ev.dia < 60);
  ev.tachy = OSIRIS_systemicFinite(ev.pulse) && ev.pulse > 100;
  ev.brady = OSIRIS_systemicFinite(ev.pulse) && ev.pulse < 60;
  ev.spo2Low = OSIRIS_systemicFinite(ev.spo2) && ev.spo2 < 92;
  ev.rrHigh = OSIRIS_systemicFinite(ev.rr) && ev.rr > 20;
