  ev.giBleed = /bleed|blood in stool|tarry|melaena|melena/i.test(localLow);
  ev.neuroSensory = /numb|tingl|paraesth|paresth|neuropath/i.test(localLow);
  ev.filtrationPhrase = /mildly reduced filtration|markedly reduced filtration|severe renal failure range|reduced filtration — chronic kidney|elevated creatinine suggests reduced renal/i
