  ev.filtrationAbnormalPhrase = /markedly reduced filtration|severe renal failure range|reduced filtration — chronic kidney|elevated creatinine suggests reduced renal/i
    .test(both);
  ev.bpHighPhrase = /hypertensive crisis range|stage 2 hypertension reading/i.test(both);
  ev.bpLowPhrase = /low blood pressure reading/i.test(both);
