    egfr: OSIRIS_systemicFinite(ev.egfr), hb: OSIRIS_systemicFinite(ev.hb),
    glucose: OSIRIS_systemicFinite(ev.glucose), hba1c: OSIRIS_systemicFinite(ev.hba1c),
    b12: OSIRIS_systemicFinite(ev.b12), mma: OSIRIS_systemicFinite(ev.mma),
    crp: OSIRIS_systemicFinite(ev.crp), esr: OSIRIS_systemicFinite(ev.esr),
