function OSIRIS_eqrApplyRadiologyMetaToEntry(entry, meta) {
  if (!entry || !meta || typeof meta !== "object") return entry;
  if (meta.radiologyType) entry.radiologyType = meta.radiologyType;
  if (meta.radiologyRegion) entry.radiologyRegion = meta.radiologyRegion;
  if (meta.typeLabel) entry.typeLabel = meta.typeLabel;
  if (meta.regionLabel) entry.regionLabel = meta.regionLabel;
  if (meta.studyDescription) entry.studyDescription = meta.studyDescription;
  if (meta.analyzedAt) entry.analyzedAt = meta.analyzedAt;
  if (meta.fileName && !entry.fileName) entry.fileName = meta.fileName;
  if (meta.source && !entry.source) entry.source = meta.source;
  if (meta.analysis && typeof meta.analysis === "object") entry.analysis = meta.analysis;
  return entry;
}

function OSIRIS_eqrAttachLatestRadiologyAnalysis(analysis, meta) {
  if (window.OSIRIS_eqrDoctorCtx) return null;
  if (!analysis || typeof analysis !== "object") return null;
  if (typeof userProfile !== "object" || !userProfile) return null;
  if (typeof OSIRIS_ensureEquirevitalShape === "function") {
    try { OSIRIS_ensureEquirevitalShape(); } catch (e) {}
  }
  if (!userProfile.equirevital || !Array.isArray(userProfile.equirevital.radiologyImages)) {
    return null;
  }
  var bag = userProfile.equirevital.radiologyImages;
  if (!bag.length) return null;
  var last = bag[bag.length - 1];
  if (!last) return null;
  var ts = (meta && meta.analyzedAt) || analysis.analyzedAt || new Date().toISOString();
  last.analysis = analysis;
  last.analyzedAt = ts;
  if (meta) OSIRIS_eqrApplyRadiologyMetaToEntry(last, meta);
  if (typeof saveUserProfile === "function") {
    try { saveUserProfile(); } catch (e2) {}
  }
  return last;
}

