function OSIRIS_eqrPersistRadiologyUpload(file) {
  if (window.OSIRIS_eqrDoctorCtx) return;
  if (!file) return;
  try {
    var reader = new FileReader();
    reader.onload = function (ev) {
      try {
        var meta = _radiologyReadSelectorsMeta();
        meta.fileName = (file && file.name) || "";
        meta.source = "radiology-upload";
        meta.ts = new Date().toISOString();
        OSIRIS_eqrArchiveRadiologyImage(ev.target.result, meta);
      } catch (e) {}
      if (typeof window.OSIRIS_eqr2_refresh === "function") {
        try { window.OSIRIS_eqr2_refresh(); } catch (e2) {}
      }
    };
    reader.readAsDataURL(file);
  } catch (e3) {}
}

function OSIRIS_eqrBindRadiologyMetaListeners() {
  if (typeof document === "undefined") return;
  function sync() {
    if (window.OSIRIS_eqrDoctorCtx) return;
    try { OSIRIS_eqrUpdateLatestRadiologyStudyMeta(_radiologyReadSelectorsMeta()); } catch (e) {}
    if (typeof window.OSIRIS_eqr2_refresh === "function") {
      try { window.OSIRIS_eqr2_refresh(); } catch (e2) {}
    }
  }
  var typeSel = document.getElementById("radiologyType");
  var regionSel = document.getElementById("radiologyRegion");
  if (typeSel && !typeSel.getAttribute("data-eqr-rad-meta-bound")) {
    typeSel.setAttribute("data-eqr-rad-meta-bound", "1");
    typeSel.addEventListener("change", sync);
  }
  if (regionSel && !regionSel.getAttribute("data-eqr-rad-meta-bound")) {
    regionSel.setAttribute("data-eqr-rad-meta-bound", "1");
    regionSel.addEventListener("change", sync);
  }
}

if (typeof window !== "undefined") {
  window.OSIRIS_eqrListArchivedRadiologyImages = OSIRIS_eqrListArchivedRadiologyImages;
  window.OSIRIS_eqrArchiveRadiologyImage = OSIRIS_eqrArchiveRadiologyImage;
  window.OSIRIS_eqrUpdateLatestRadiologyStudyMeta = OSIRIS_eqrUpdateLatestRadiologyStudyMeta;
  window.OSIRIS_eqrAttachLatestRadiologyAnalysis = OSIRIS_eqrAttachLatestRadiologyAnalysis;
  window.OSIRIS_eqrDeleteArchivedRadiologyImage = OSIRIS_eqrDeleteArchivedRadiologyImage;
  window.OSIRIS_eqrPersistRadiologyUpload = OSIRIS_eqrPersistRadiologyUpload;
  window.OSIRIS_eqrBindRadiologyMetaListeners = OSIRIS_eqrBindRadiologyMetaListeners;
  try {
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", OSIRIS_eqrBindRadiologyMetaListeners);
    } else {
      OSIRIS_eqrBindRadiologyMetaListeners();
    }
  } catch (eBind) {}
}

function OSIRIS_eqrSkipRecentDuplicate(metricKey, n, windowMs) {
  if (typeof metricKey !== "string" || !metricKey) return true;
  if (typeof n !== "number" || !isFinite(n)) return true;
  try {
    var arr = userProfile && userProfile.equirevital &&
              userProfile.equirevital.series &&
              userProfile.equirevital.series[metricKey];
    if (!Array.isArray(arr) || !arr.length) return false;
    var last = arr[arr.length - 1];
    if (!last || last.value !== n) return false;
    var lastTs = Date.parse(last.ts);
    return isFinite(lastTs) && (Date.now() - lastTs) < (windowMs || 2000);
  } catch (e) {
    return false;
  }
}

function OSIRIS_eqrRecordCanonicalSeries(metricKey, value, source, opts) {
  if (typeof EQR_recordSeriesPoint !== "function") return;
  var n = (typeof OSIRIS_eqrParseSeriesValue === "function")
    ? OSIRIS_eqrParseSeriesValue(value)
    : ((typeof value === "number") ? value : parseFloat(value));
  if (!isFinite(n)) return;
  if (typeof OSIRIS_eqrRejectFalseZero === "function" &&
      OSIRIS_eqrRejectFalseZero(metricKey, n)) return;
  if (OSIRIS_eqrSkipRecentDuplicate(metricKey, n, 2000)) return;
  var o = opts && typeof opts === "object" ? opts : {};
  try {
    EQR_recordSeriesPoint(metricKey, n, {
      source: source || "manual",
      ts: o.ts,
      unit: o.unit,
      displayName: o.displayName
    });
  } catch (e) {}
}

function OSIRIS_eqrRecordRenalAnalysed(source, specs, sharedTs) {
  if (!Array.isArray(specs) || typeof EQR_recordSeriesPoint !== "function") return;
  var ts = sharedTs || new Date().toISOString();
  var recorded = 0;
  specs.forEach(function (s) {
    if (!s || !s.key) return;
    var n = (typeof OSIRIS_eqrParseSeriesValue === "function")
      ? OSIRIS_eqrParseSeriesValue(s.val)
      : ((typeof s.val === "number") ? s.val : parseFloat(s.val));
    if (!isFinite(n)) return;
    if (n === 0 && !s.allowZero) return;
    try {
      EQR_recordSeriesPoint(s.key, n, {
        source: source || "renal",
        ts: ts,
        unit: s.unit,
        displayName: s.name
      });
      recorded++;
    } catch (e) {}
  });
  if (recorded && typeof EQR_appendTimeline === "function") {
    try {
      EQR_appendTimeline({
        kind: "section_save",
        category: "renal",
        summary: source || "Renal analysis",
        severity: "INFO",
        payload: { source: source, ts: ts }
      });
    } catch (e2) {}
  }
}

