function _correlateEcgWithCardio(result, ecg, context) {
  if (!ecg || typeof ecg !== "object") return;
  const get   = (typeof getRadioValue === "function") ? getRadioValue : () => "";
  const getIn = (typeof getInputValue === "function") ? getInputValue : () => "";

  const ecgHR  = _ecgNum(ecg.heartRate);
  const pr     = _ecgNum(ecg.prInterval);
  const qrs    = _ecgNum(ecg.qrsDuration);
  const qtc    = OSIRIS_getCanonicalQtcSeconds(ecg);
  const st     = (ecg.stSegment || "").toLowerCase();
  const tWave  = (ecg.tWave || "").toLowerCase();
  const axis   = (ecg.axis || "").toLowerCase();
  const rhythm = (ecg.rhythm || "").toLowerCase();
  const imgQ   = (ecg.image_quality || "").toLowerCase();
  const conf   = (typeof ecg.confidence === "number") ? ecg.confidence : null;

  // -- Provenance + quality caveats --
  if (ecg.source === "image-ai-reviewed" || ecg.imageUsed) {
    result.findings.push(
      "ECG read from uploaded image (AI-assisted, " +
      (ecg.manualReview ? "manually reviewed" : "manual review pending") + ")."
    );
  }
  if (imgQ === "poor" || (conf != null && conf < 0.4)) {
    result.warnings.push("ECG image quality or AI confidence is low — manual verification recommended.");
  }

  // -- Heart-rate cross-check with recorded pulse --
  const pulseHR = parseInt(getIn("cardioHeartRate"));
  if (!isNaN(ecgHR) && !isNaN(pulseHR) && Math.abs(ecgHR - pulseHR) >= 15) {
    result.findings.push(
      "Heart-rate discrepancy: ECG " + ecgHR + " bpm vs. recorded pulse " + pulseHR + " bpm (≥15 bpm apart)."
    );
    result.interpretations.push(
      "Discrepancy between ECG-derived heart rate and recorded pulse may suggest pulse deficit, irregular rhythm, or measurement error — recheck both."
    );
    result.status = _raiseStatus(result.status, "borderline");
  }

  // -- Rhythm --
  if (rhythm) {
    if (rhythm.includes("fibrill") || rhythm.includes("flutter")) {
      result.findings.push("Atrial " + (rhythm.includes("flutter") ? "flutter" : "fibrillation") + " pattern on ECG.");
      result.interpretations.push(
        "Atrial fibrillation/flutter raises thromboembolic risk and warrants rate/rhythm control review and anticoagulation assessment."
      );
      result.suggestedTests.push("Electrolytes (potassium, magnesium).");
      result.suggestedTests.push("TSH (rule out thyroid-driven AFib).");
      result.suggestedTests.push("Echocardiogram.");
      result.nextSteps.push("Consider CHA2DS2-VASc and HAS-BLED scoring for anticoagulation decision.");
      result.status = "abnormal";
    } else if (rhythm.includes("paced")) {
      result.findings.push("Paced rhythm on ECG.");
    } else if (rhythm.includes("irregular")) {
      result.findings.push("Irregular ECG rhythm.");
      result.status = _raiseStatus(result.status, "borderline");
    } else if (rhythm.includes("bradycard")) {
      result.findings.push("Bradycardic rhythm on ECG.");
      result.status = _raiseStatus(result.status, "borderline");
    } else if (rhythm.includes("tachycard")) {
      result.findings.push("Tachycardic rhythm on ECG.");
      result.status = _raiseStatus(result.status, "borderline");
    } else if (rhythm.includes("sinus")) {
      result.findings.push("Sinus rhythm on ECG.");
    }
  }

  // -- PR interval (AV conduction) --
  if (!isNaN(pr)) {
    if (pr > 0.20) {
      result.findings.push("Prolonged PR interval: " + pr.toFixed(2) + " s — first-degree AV block pattern.");
      result.interpretations.push(
        "Prolonged AV conduction can be caused by AV-nodal blocking medications (beta-blockers, calcium-channel blockers, digoxin), high vagal tone, or conduction-system disease."
      );
      result.status = _raiseStatus(result.status, "borderline");
    } else if (pr < 0.12) {
      result.findings.push("Short PR interval: " + pr.toFixed(2) + " s — consider pre-excitation.");
      result.status = _raiseStatus(result.status, "borderline");
    }
  }

  // -- QRS duration (conduction / structural) --
  if (!isNaN(qrs) && qrs > 0.12) {
    result.findings.push("Wide QRS: " + qrs.toFixed(2) + " s — bundle-branch block or ventricular-origin pattern.");
    result.interpretations.push("Wide QRS warrants prior-ECG comparison and consideration of structural heart disease.");
    result.suggestedTests.push("Echocardiogram.");
    result.status = _raiseStatus(result.status, "borderline");
  }

  // -- QTc (Torsades-de-Pointes risk + QT-prolonging drug review) --
  if (!isNaN(qtc)) {
    if (qtc > 0.50) {
      result.findings.push("Markedly prolonged QTc: " + qtc.toFixed(2) + " s — high arrhythmia risk.");
      result.interpretations.push(
        "Severely long QTc significantly raises Torsades-de-Pointes risk; correct electrolytes (K, Mg, Ca) and review QT-prolonging medications urgently."
      );
      result.suggestedTests.push("Magnesium, potassium, calcium.");
      result.medicationNotes.push("Review QT-prolonging drugs (macrolides, fluoroquinolones, antipsychotics, methadone, ondansetron, citalopram, amiodarone, sotalol).");
      result.status = "abnormal";
    } else if (qtc > 0.46) {
      result.findings.push("Prolonged QTc: " + qtc.toFixed(2) + " s.");
      result.interpretations.push("Prolonged QTc raises arrhythmia risk; correlate with electrolytes and any QT-prolonging medications.");
      result.suggestedTests.push("Magnesium, potassium, calcium.");
      result.medicationNotes.push("Review QT-prolonging drugs.");
      result.status = _raiseStatus(result.status, "borderline");
    }
  }

  // -- ST segment (ischaemia / injury pattern) --
  const chestPainFreq = get("chestPainFrequency");
  if (st === "elevated") {
    result.findings.push("ST elevation on ECG.");
    result.interpretations.push(
      "ST elevation may indicate acute coronary injury, pericarditis, or early repolarisation — clinical correlation and troponin are essential."
    );
    result.suggestedTests.push("High-sensitivity troponin (now and repeat).");
    result.suggestedTests.push("Repeat ECG.");
    if (chestPainFreq && chestPainFreq !== "Never" && chestPainFreq !== "") {
      result.nextSteps.push("ST elevation with reported chest pain — treat as possible STEMI; urgent in-person evaluation.");
    } else {
      result.nextSteps.push("ST elevation — urgent clinical correlation, even if currently asymptomatic.");
    }
    result.status = "abnormal";
  } else if (st === "depressed") {
    result.findings.push("ST depression on ECG.");
    result.interpretations.push(
      "ST depression can reflect subendocardial ischaemia, strain, hypokalaemia, or digoxin effect."
    );
    result.suggestedTests.push("High-sensitivity troponin.");
    result.suggestedTests.push("Electrolytes (potassium, magnesium).");
    result.status = _raiseStatus(result.status, "abnormal");
  }

  // -- T wave --
  if (tWave === "peaked") {
    result.findings.push("Peaked T waves on ECG.");
    result.interpretations.push("Peaked T waves can suggest hyperkalaemia; correlate with serum potassium urgently.");
    result.suggestedTests.push("Serum potassium.");
    result.status = _raiseStatus(result.status, "abnormal");
  } else if (tWave === "flattened") {
    result.findings.push("Flattened T waves on ECG.");
    result.interpretations.push("Flattened T waves can suggest hypokalaemia or non-specific repolarisation change.");
    result.suggestedTests.push("Serum potassium, magnesium.");
    result.status = _raiseStatus(result.status, "borderline");
  } else if (tWave === "inverted") {
    result.findings.push("T-wave inversion on ECG.");
    result.interpretations.push("T-wave inversion can reflect ischaemia, strain, or prior infarction — correlate with symptoms, troponin, and prior ECGs.");
    result.suggestedTests.push("High-sensitivity troponin.");
    result.status = _raiseStatus(result.status, "borderline");
  }

  // -- Axis --
  if (axis === "left") {
    result.findings.push("Left axis deviation on ECG.");
  } else if (axis === "right") {
    result.findings.push("Right axis deviation on ECG.");
    result.interpretations.push("Right axis deviation can occur with right-sided strain (pulmonary disease, pulmonary embolism) or left posterior fascicular block.");
  } else if (axis === "extreme") {
    result.findings.push("Extreme axis deviation on ECG.");
    result.status = _raiseStatus(result.status, "borderline");
  }

  // -- AI-flagged abnormalities --
  if (Array.isArray(ecg.abnormalities) && ecg.abnormalities.length) {
    ecg.abnormalities.forEach((a) => {
      const s = String(a || "").trim();
      if (s) result.findings.push("ECG abnormality flagged: " + s + ".");
    });
  }

  // -- Electrolyte cross-correlation (uses values already entered in renal/baseline panels) --
  const k = _ecgNum(getIn("baselinePotassium")) || _ecgNum(getIn("renal-potassium"));
  if (!isNaN(k)) {
    if (tWave === "peaked" && k > 5.2) {
      result.interpretations.push("Peaked T-waves consistent with reported serum potassium " + k + " mmol/L (hyperkalaemia pattern).");
      result.status = _raiseStatus(result.status, "abnormal");
    }
    if ((tWave === "flattened" || st === "depressed") && k < 3.5) {
      result.interpretations.push("Flattened T-waves / ST depression consistent with reported serum potassium " + k + " mmol/L (hypokalaemia pattern).");
    }
  }

  // -- Plain-language ECG summary surfaces in interpretations --
  if (ecg.plain_language_summary) {
    result.interpretations.push("ECG summary (AI-assisted): " +
      OSIRIS_formatQtcDisplayText(ecg.plain_language_summary));
  }
}

/* Varicose veins are context for the cardiovascular assessment.
   Selection alone does not diagnose chronic venous insufficiency,
   deep vein thrombosis, or peripheral arterial disease, and it does
   not create a systemic-contribution relationship. */
function OSIRIS_varicoseVeinsSelected(context) {
  try {
    if (typeof selectedConditionIds !== "undefined" &&
        Array.isArray(selectedConditionIds) &&
        selectedConditionIds.indexOf("varicose_veins") !== -1) return true;
  } catch (eSel) {}
  var bags = [];
  try {
    var sel = (typeof userProfile !== "undefined" && userProfile &&
      userProfile.pre_existing_conditions &&
      userProfile.pre_existing_conditions.selected) || [];
    if (Array.isArray(sel)) bags = bags.concat(sel);
  } catch (eBag) {}
  if (context && Array.isArray(context.preconditions)) bags = bags.concat(context.preconditions);
  for (var i = 0; i < bags.length; i++) {
    var item = bags[i];
    var text = String(item && item.label ? item.label : item || "").toLowerCase();
    if (text.indexOf("varicose") !== -1) return true;
  }
  return false;
}

function OSIRIS_legSwellingRecorded(value) {
  return String(value || "").split(",").some(function (part) {
    return part.trim() === "Legs";
  });
}

function OSIRIS_varicoseVeinAssessment(selected, signals) {
  if (!selected) return null;
  signals = signals || {};
  var text = String(signals.text || "").toLowerCase();
  var supports = [];
  if (signals.legSwelling || /swelling present:\s*legs\b/.test(text)) supports.push("leg swelling");
  if (/leg heaviness|heavy legs|heaviness of the legs|heaviness in the legs/.test(text)) supports.push("leg heaviness");
  if (/\baching\b/.test(text) && /leg|ankle|calf/.test(text)) supports.push("aching");
  if (/haemosiderin|hemosiderin|lipodermatosclerosis|venous eczema|gaiter area/.test(text)) supports.push("venous skin changes");
  if (/venous ulcer|leg ulcer|ankle ulcer/.test(text)) supports.push("venous ulceration");
  if (signals.legPainAtRest) supports.push("leg pain at rest");
  var interpretation = supports.length
    ? "With " + supports.join(", ") + " also recorded, varicose veins can be associated with chronic venous insufficiency or venous reflux. These findings do not establish chronic venous insufficiency, deep vein thrombosis, or peripheral arterial disease."
    : "This selection alone does not establish chronic venous insufficiency, venous reflux, deep vein thrombosis, or peripheral arterial disease.";
  return {
    finding: "Varicose veins are recorded as a pre-existing condition.",
    interpretation: interpretation,
    step: supports.length
      ? "Venous duplex ultrasound is a possible confirmatory investigation for venous reflux. It does not diagnose deep vein thrombosis or peripheral arterial disease, and it does not replace ankle-brachial assessment when leg pain occurs while walking."
      : "",
    test: supports.length ? "Venous duplex ultrasound." : "",
    supports: supports
  };
}

/* ---------- CARDIO → cardiovascularStress ---------- */
function interpretCardio(context) {
  const result = {
    category: "cardio",
    status: "normal",
    findings: [],
    interpretations: [],
    nextSteps: [],
    suggestedTests: [],
    medicationNotes: [],
    warnings: [],
    missing: []
  };

  const get = (typeof getRadioValue === "function") ? getRadioValue : () => "";
  const getIn = (typeof getInputValue === "function") ? getInputValue : () => "";

  // ECG → Cardio bridge: pull the latest ECG DOM values into the profile so
  // this analysis (and any downstream Global Diagnostics layer) reads from a
  // single source of truth.
  let ecgProfile = null;
  try { ecgProfile = _syncEcgInputsToProfile(); }
  catch (e) { ecgProfile = null; }

  const highBP          = get('highBP');
  const bpMedication    = get('bpMedication');
  const systolic        = (typeof OSIRIS_readBloodPressureComponent === "function")
    ? OSIRIS_readBloodPressureComponent("systolic")
    : parseInt(getIn('cardioBloodPressureSystolic'), 10);
  const diastolic       = (typeof OSIRIS_readBloodPressureComponent === "function")
    ? OSIRIS_readBloodPressureComponent("diastolic")
    : parseInt(getIn('cardioBloodPressureDiastolic'), 10);
  const heartRate       = parseInt(getIn('cardioHeartRate'));
  const chestPainFreq   = get('chestPainFrequency');
  const chestPainRad    = get('chestPainRadiate');
  const sobFreq         = get('breathFrequency');
  const sobWhen         = get('breathActivity');
  const palpitations    = get('palpitationsFrequency');
  const palpitationsWhen= get('palpitationsActivity');
  const edemaLocation   = get('swellingLocation');
  const irregularHB     = get('irregularHeartbeatFrequency');
  const faintingFreq    = get('faintingFrequency');
  const legPainWhen     = get('legPainActivity');

  if (highBP === "Yes") {
    result.findings.push("History of high blood pressure reported.");

    if (bpMedication === "No") {
      result.findings.push("Not currently controlled with medication.");
      result.nextSteps.push(
        "Check repeated blood pressure readings, kidney function, electrolytes, glucose/HbA1c, lipid profile and TSH because uncontrolled hypertension can be driven by renal load, metabolic strain, thyroid activity or vascular resistance."
      );
      result.status = _raiseStatus(result.status, "borderline");
    }
  }

  if (!isNaN(systolic) && !isNaN(diastolic)) {
    if (systolic >= 180 || diastolic >= 120) {
      result.findings.push(`Hypertensive crisis range: ${systolic}/${diastolic} mmHg.`);
      result.nextSteps.push(
        "Repeat blood pressure immediately, check resting ECG, oxygen saturation, kidney function, electrolytes, neurological symptoms and chest pain because this pressure range can create immediate organ strain."
      );
      result.suggestedTests.push("Repeated blood pressure measurement.");
      result.suggestedTests.push("Resting ECG.");
      result.suggestedTests.push("Oxygen saturation.");
      result.suggestedTests.push("Kidney function.");
      result.suggestedTests.push("Electrolytes.");
      result.status = "abnormal";

    } else if (systolic >= 140 || diastolic >= 90) {
      result.findings.push(`Stage 2 hypertension reading: ${systolic}/${diastolic} mmHg.`);
      result.nextSteps.push(
        "Repeat blood pressure on different days to confirm sustained hypertension pattern. Check kidney function, electrolytes, glucose/HbA1c, lipid profile, TSH, hematocrit and RBC because persistent high pressure can be driven by vascular resistance, renal load, metabolic strain, thyroid activity or blood viscosity."
      );
      result.suggestedTests.push("Repeated blood pressure trend.");
      result.suggestedTests.push("Kidney function.");
      result.suggestedTests.push("Electrolytes.");
      result.suggestedTests.push("Glucose / HbA1c.");
      result.suggestedTests.push("Lipid profile.");
      result.suggestedTests.push("TSH.");
      result.suggestedTests.push("Hematocrit / RBC.");
      result.status = _raiseStatus(result.status, "abnormal");

    } else if (systolic >= 130 || diastolic >= 80) {
      result.findings.push(`Stage 1 hypertension reading: ${systolic}/${diastolic} mmHg.`);
      result.nextSteps.push(
        "Repeat blood pressure on different days to confirm whether this is a sustained pattern or a single elevated reading. Check glucose/HbA1c, lipid profile, kidney function and TSH if elevation repeats."
      );
      result.suggestedTests.push("Repeated blood pressure trend.");
      result.suggestedTests.push("Glucose / HbA1c if repeated elevation appears.");
      result.suggestedTests.push("Lipid profile if repeated elevation appears.");
      result.suggestedTests.push("Kidney function if repeated elevation appears.");
      result.suggestedTests.push("TSH if repeated elevation appears.");
      result.status = _raiseStatus(result.status, "borderline");

    } else if (systolic < 90 || diastolic < 60) {
      result.findings.push(`Low blood pressure reading: ${systolic}/${diastolic} mmHg.`);
      result.nextSteps.push(
        "Repeat blood pressure and check hydration, electrolytes, glucose, hemoglobin and hematocrit because repeated low pressure can reflect volume depletion, metabolic instability or reduced oxygen transport."
      );
      result.suggestedTests.push("Repeated blood pressure measurement.");
      result.suggestedTests.push("Hydration status.");
      result.suggestedTests.push("Electrolytes.");
      result.suggestedTests.push("Glucose.");
      result.suggestedTests.push("Hemoglobin / hematocrit.");
      result.status = _raiseStatus(result.status, "borderline");
    }
  } else {
    result.missing.push("Enter systolic and diastolic blood pressure.");
  }

  
  
  

  if (!isNaN(heartRate)) {
    if (heartRate > 100) {
      result.findings.push(`Tachycardia: ${heartRate} bpm.`);
      result.interpretations.push("Elevated heart rate suggests increased cardiovascular demand.");
      result.suggestedTests.push("Resting ECG.");
      result.status = _raiseStatus(result.status, "borderline");
    } else if (heartRate < 50) {
      result.findings.push(`Marked bradycardia: ${heartRate} bpm.`);
      result.status = _raiseStatus(result.status, "borderline");
    } else if (heartRate < 60) {
      result.findings.push(`Bradycardia: ${heartRate} bpm.`);
    }
  } else {
    result.missing.push("Enter heart rate.");
  }

  if (chestPainFreq && chestPainFreq !== "Never") {
    result.findings.push(`Chest pain reported: ${chestPainFreq}.`);
    if (chestPainRad === "Yes") {
      result.findings.push("Pain radiates to other body parts.");
      result.interpretations.push("Radiating chest pain may reflect ischemic pattern.");
      result.nextSteps.push("Check resting ECG, oxygen saturation, blood pressure trend, troponin if chest pain or pressure is present, electrolytes and kidney function because chest tightness at rest with possible breathlessness can reflect rhythm disturbance, cardiac strain, oxygenation problem or pressure overload.");
      result.status = "abnormal";
    } else {
      result.status = _raiseStatus(result.status, "borderline");
    }
    result.suggestedTests.push("Resting ECG.");
  }

  if (sobFreq && sobFreq !== "Never") {
    result.findings.push(`Shortness of breath: ${sobFreq}.`);
    if (sobWhen === "At Rest") {
      result.interpretations.push("Check oxygen saturation, resting ECG, blood pressure trend, hemoglobin, hematocrit and lung signs because shortness of breath at rest can come from reduced oxygen delivery, cardiac load or impaired lung exchange.");
      result.status = "abnormal";
    } else {
      result.status = _raiseStatus(result.status, "borderline");
    }
  }

  
  if (palpitations && palpitations !== "Rarely" && palpitations !== "") {
  result.findings.push(`Palpitations: ${palpitations}.`);

  if (palpitationsWhen === "At Rest") {
    result.nextSteps.push(
      "Check resting ECG and Holter monitor (portable ECG for 24–48h continuous recording) because palpitations at rest may be caused by intermittent rhythm disturbances that are not always visible on a single ECG."
    );

    result.suggestedTests.push("Resting ECG.");
    result.suggestedTests.push("Holter monitor (portable ECG for 24–48h continuous recording).");

    result.status = _raiseStatus(result.status, "borderline");
  }
}
  
  if (edemaLocation) {
  result.findings.push(`Swelling present: ${edemaLocation}.`);

  if (edemaLocation === "Legs") {
    result.nextSteps.push(
      "Check kidney function (creatinine, eGFR), electrolytes, albumin, blood pressure, and assess for shortness of breath or weight gain because leg swelling can result from fluid retention, impaired venous return or cardiac load."
    );

    result.suggestedTests.push("Kidney function (creatinine, eGFR).");
    result.suggestedTests.push("Electrolytes.");
    result.suggestedTests.push("Albumin.");

    result.status = _raiseStatus(result.status, "borderline");
  }
}
  
  

  if (irregularHB && irregularHB !== "Rarely" && irregularHB !== "") {
    result.findings.push(`Irregular heartbeat: ${irregularHB}.`);
    result.suggestedTests.push("ECG and rhythm monitoring.");
    result.status = _raiseStatus(result.status, "borderline");
  }

  if (faintingFreq && faintingFreq !== "Never") {
    result.findings.push(`Fainting episodes: ${faintingFreq}.`);
    result.nextSteps.push(
  "Check resting ECG, blood pressure lying and standing, glucose, electrolytes, hemoglobin, hematocrit and neurological status because fainting episodes can result from rhythm disturbance, sudden blood pressure drop, reduced oxygen delivery or metabolic instability."
);
    result.status = "abnormal";
  }

if (legPainWhen === "While Walking") {
  result.findings.push("Leg pain while walking (claudication pattern).");

  result.nextSteps.push(
    "Check ankle-brachial index (ABI), peripheral pulses, lipid profile, glucose/HbA1c and blood pressure because leg pain during walking can reflect reduced arterial blood flow due to vessel narrowing (peripheral artery disease)."
  );

  result.suggestedTests.push("Ankle-brachial index (ABI).");
  result.status = _raiseStatus(result.status, "borderline");
}

  var varicoseVeinNote = OSIRIS_varicoseVeinAssessment(OSIRIS_varicoseVeinsSelected(context), {
    legSwelling: OSIRIS_legSwellingRecorded(edemaLocation),
    legPainAtRest: legPainWhen === "At Rest",
    text: (result.findings || []).concat(result.interpretations || []).join("\n")
  });
  if (varicoseVeinNote) {
    result.findings.push(varicoseVeinNote.finding);
    result.interpretations.push(varicoseVeinNote.interpretation);
    if (varicoseVeinNote.step) result.nextSteps.push(varicoseVeinNote.step);
    if (varicoseVeinNote.test) result.suggestedTests.push(varicoseVeinNote.test);
  }

  // Integrate ECG (image-AI + manual review) into the cardio picture.
  try { _correlateEcgWithCardio(result, ecgProfile, context); }
  catch (e) { /* never let ECG correlation break the rest of cardio */ }

  _contributeCluster(["cardiovascularStress"], result.status, result.findings.length);
  _applyMedImpact(result, "cardio", context && context.medicationImpact);
  return result;
}

function OSIRIS_classifyEgfr(value) {
  var n = parseFloat(value);
  if (!isFinite(n) || n <= 0) return null;
  if (n < 15) return {
    status: "abnormal",
    text: "Severe renal failure range — urgent nephrology evaluation required."
  };
  if (n < 30) return {
    status: "abnormal",
    text: "Markedly reduced filtration — advanced kidney impairment."
  };
  if (n < 60) return {
    status: "abnormal",
    text: "Reduced filtration — chronic kidney disease pattern likely."
  };
  if (n < 90) return {
    status: "borderline",
    text: "Mildly reduced filtration — monitor kidney function, blood pressure, and creatinine."
  };
  return { status: "normal", text: "Filtration appears preserved." };
}

/* ---------- RENAL_DIAGNOSTICS → fluidImbalance + detoxLoad ---------- */
function interpretRenalDiagnostics(context) {
  const result = {
    category: "renal_diagnostics",
    status: "normal",
    findings: [],
    interpretations: [],
    nextSteps: [],
    suggestedTests: [],
    medicationNotes: [],
    warnings: [],
    missing: []
  };

  const get = (typeof getRadioValue === "function") ? getRadioValue : () => "";
  const getIn = (typeof getInputValue === "function") ? getInputValue : () => "";

  const age          = parseInt(context && context.patient && context.patient.age);
  const creatinine   = parseFloat(getIn('renal-creatinine'));
  const sodium       = parseFloat(getIn('renal-sodium'));
  const potassium    = parseFloat(getIn('renal-potassium'));
  const bicarbonate  = parseFloat(getIn('renal-bicarbonate'));
  const urinePH      = parseFloat(getIn('renal-ph'));
  const specGravity  = parseFloat(getIn('renal-specific-gravity'));
  const urineGlucose = parseFloat(getIn('renal-glucose'));
  const urineProtein = parseFloat(getIn('renal-urinary-protein'));
  var egfr = parseFloat(context && context.labs && context.labs.egfr);
  if (isNaN(egfr) && typeof OSIRIS_getKnownMetric === "function") {
    egfr = parseFloat(OSIRIS_getKnownMetric("egfr"));
  }

  if (isNaN(creatinine)) result.missing.push("Enter serum creatinine.");
  if (isNaN(sodium))     result.missing.push("Enter serum sodium.");
  if (isNaN(potassium))  result.missing.push("Enter serum potassium.");

  // fluidImbalance signals
  if (!isNaN(sodium)) {
    if (sodium < 135) {
      result.findings.push(`Low sodium: ${sodium} mmol/L.`);
      result.nextSteps.push(
  "Check fluid intake, sodium intake, kidney function and medications because low sodium may result from excess water dilution or sodium loss, which can affect neurological and cardiovascular stability."
);
      result.status = _raiseStatus(result.status, "borderline");
    } else if (sodium > 145) {
      result.findings.push(`High sodium: ${sodium} mmol/L.`);
      result.nextSteps.push(
  "Assess hydration and fluid balance — including fluid intake, urine output, blood pressure/pulse and, where clinically appropriate, blood or urine tests for signs of dehydration or fluid imbalance — together with kidney function and electrolytes, because high sodium usually reflects reduced body water (dehydration), leading to increased blood concentration and potential cardiovascular and neurological stress."
);
      result.status = _raiseStatus(result.status, "borderline");
    }
  }

  if (!isNaN(specGravity)) {
    if (specGravity > 1.030) {
      result.findings.push(`High urine specific gravity: ${specGravity}.`);
      result.interpretations.push("Concentrated urine — likely dehydration or fluid imbalance.");
      result.status = _raiseStatus(result.status, "borderline");
    } else if (specGravity < 1.005) {
      result.findings.push(`Low urine specific gravity: ${specGravity}.`);
      result.interpretations.push("Dilute urine — may reflect excess fluid load or impaired concentration.");
      result.status = _raiseStatus(result.status, "borderline");
    }
  }

  // detoxLoad signals
  if (!isNaN(egfr)) {
    var egfrClass = OSIRIS_classifyEgfr(egfr);
    result.findings.push(`eGFR: ${egfr.toFixed(2)} mL/min/1.73m².`);
    if (egfrClass) {
      result.interpretations.push(egfrClass.text);
      result.status = _raiseStatus(result.status, egfrClass.status);
    }
  }

  if (!isNaN(creatinine)) {
    if (creatinine > 1.3) {
      result.findings.push(`Elevated creatinine: ${creatinine} mg/dL.`);
      result.interpretations.push("Elevated creatinine suggests reduced renal filtration and higher detox load.");
      result.suggestedTests.push(isNaN(egfr)
        ? "Glomerular Filtration Rate (eGFR) and Blood Urea Nitrogen (BUN)."
        : "Blood Urea Nitrogen (BUN).");
      result.status = _raiseStatus(result.status, creatinine > 2 ? "abnormal" : "borderline");
    }
  }

  if (!isNaN(urineProtein) && urineProtein > 0.15) {
    result.findings.push(`Proteinuria detected: ${urineProtein} g/L.`);
    result.interpretations.push("Protein in urine suggests glomerular stress and increased filtration load.");
    result.suggestedTests.push("Urine albumin-to-creatinine ratio.");
    result.status = _raiseStatus(result.status, "borderline");
  }

  if (!isNaN(urineGlucose) && urineGlucose > 0) {
    result.findings.push(`Glucose in urine: ${urineGlucose}.`);
    result.interpretations.push("Glucosuria may reflect hyperglycemia or tubular dysfunction.");
    result.suggestedTests.push("Fasting glucose and HbA1c.");
    result.status = _raiseStatus(result.status, "borderline");
  }

  if (!isNaN(potassium)) {
    if (potassium < 3.5 || potassium > 5.2) {
      result.findings.push(`Potassium out of range: ${potassium} mmol/L.`);
      result.interpretations.push("Electrolyte imbalance — monitor cardiac and renal status.");
      result.status = _raiseStatus(result.status, potassium < 3.0 || potassium > 5.8 ? "abnormal" : "borderline");
    }
  }

  if (!isNaN(bicarbonate) && (bicarbonate < 22 || bicarbonate > 29)) {
    result.findings.push(`Bicarbonate out of range: ${bicarbonate} mmol/L.`);
    result.interpretations.push("Acid-base imbalance may reflect renal or metabolic disturbance.");
    result.status = _raiseStatus(result.status, "borderline");
  }

  if (!isNaN(urinePH) && (urinePH < 4.5 || urinePH > 8)) {
    result.findings.push(`Urine pH outside normal range: ${urinePH}.`);
    result.status = _raiseStatus(result.status, "borderline");
  }

  if (!isNaN(age) && age >= 60 && !isNaN(creatinine) && creatinine > 1.0) {
    result.nextSteps.push(
      "Repeat creatinine and assess hydration and fluid balance — including fluid intake, urine output, blood pressure/pulse and, where clinically appropriate, blood or urine tests for signs of dehydration or fluid imbalance."
    );
  }

  _contributeCluster(["fluidImbalance","detoxLoad"], result.status, result.findings.length);
  _applyMedImpact(result, "renal_diagnostics", context && context.medicationImpact);
  return result;
}

/* ---------- ENDOCRINE ---------- */
function interpretEndocrine(context) {
  const result = {
    category: "endocrine",
    status: "normal",
    findings: [],
    interpretations: [],
    nextSteps: [],
    suggestedTests: [],
    medicationNotes: [],
    warnings: [],
    missing: []
  };

  const get = (typeof getRadioValue === "function") ? getRadioValue : () => "";
  const getIn = (typeof getInputValue === "function") ? getInputValue : () => "";
  const pushUnique = (arr, msg) => {
    if (!msg) return;
    if (arr.indexOf(msg) === -1) arr.push(msg);
  };
  const yes = (v) => {
    const s = String(v == null ? "" : v).trim().toLowerCase();
    return s === "yes" || s === "y";
  };
  const suggest = (label, because) => {
    if (!label) return;
    const line = because
      ? (label + " — because " + because)
      : label;
    pushUnique(result.suggestedTests, line);
  };

  // —— Canonical live Endocrine DOM (index.html) ——
  // Fatigue radios: name="fatigueFrequency__2" (resolved via getRadioValue base)
  const fatigue       = get("fatigueFrequency");
  const mood          = get("moodChanges");
  const concentration = get("concentration");
  const thirst        = get("thirstIncrease");          // yes|no
  const hunger        = get("endocrineHungerIncrease"); // yes|no
  const hairChanges   = get("endocrineHairChanges");    // yes|no
  const menstrual     = get("endocrineMenstrualIrregularities"); // Yes|No
  const skinChanges   = get("skinChanges");             // Yes|No
  const tempSens      = get("tempSensitivity");         // cold|hot|neutral
  const tempDiscomfort= get("tempDiscomfort");          // Yes|No
  const autoimmuneHx  = get("autoimmuneHistory");       // yes|no
  const autoimmuneSx  = get("autoimmuneSymptoms");      // yes|no
  const hormoneChange = get("hormoneChange");           // Yes|No

  const tsh      = parseFloat(getIn("endocrineThyroidStimulatingHormone"));
  const t4       = parseFloat(getIn("endocrineThyroxine"));
  const t3       = parseFloat(getIn("endocrineTriiodothyronine"));
  const tpoAb    = parseFloat(getIn("endocrineThyroidPeroxidaseAntibody"));
  const tgAb     = parseFloat(getIn("endocrineThyroglobulinAntibody"));
  const cortisol = parseFloat(getIn("endocrineMorningCortisol"));
  const acthStim = parseFloat(getIn("endocrineAdrenocorticotropicHormoneStimulationTestResult"));
  const estrogen = parseFloat(getIn("endocrineEstrogen"));
  const testost  = parseFloat(getIn("endocrineTestosterone"));
  const progest  = parseFloat(getIn("endocrineProgesterone"));
  const bbt      = parseFloat(getIn("basalBodyTemp"));
  const aldo     = parseFloat(getIn("endocrineAldosterone"));
  const vaso     = parseFloat(getIn("endocrineVasopressin"));
  const leptin   = parseFloat(getIn("endocrineLeptinLevel"));
  const ghrelin  = parseFloat(getIn("endocrineGhrelinLevel"));
  const ferritin = parseFloat(getIn("endocrineFerritinLevel"));
  const hairThy  = parseFloat(getIn("endocrineThyroidLevel"));
  const cycleVar = parseFloat(getIn("endocrineCycleLengthVariability"));
  const periodDur= parseFloat(getIn("endocrinePeriodDuration"));
  const periodPain = parseFloat(getIn("endocrinePeriodPain"));

  const hasTsh = !isNaN(tsh);
  const hasT4  = !isNaN(t4);
  const hasT3  = !isNaN(t3);
  const t4Low  = hasT4 && t4 < 9.0;
  const t4High = hasT4 && t4 > 25.0;
  const t3Low  = hasT3 && t3 < 3.5;
  const t3High = hasT3 && t3 > 6.5;
  const tshHigh = hasTsh && tsh > 4.0;
  const tshLow  = hasTsh && tsh < 0.4;
  const coldIntol = tempSens === "cold";
  const heatIntol = tempSens === "hot";
  const hypoSx = [];
  const hyperSx = [];

  // —— Fatigue ——
  if (fatigue === "Frequently") {
    pushUnique(result.findings, "Fatigue frequency: Frequently.");
    hypoSx.push("frequent fatigue");
    result.status = _raiseStatus(result.status, "borderline");
  } else if (fatigue === "Occasionally") {
    pushUnique(result.findings, "Fatigue frequency: Occasionally.");
  } else if (fatigue === "Rarely") {
    pushUnique(result.findings, "Fatigue frequency: Rarely.");
  }

  // —— Temperature / BBT ——
  if (tempSens === "cold") {
    pushUnique(result.findings, "Temperature sensitivity: unusually cold.");
    hypoSx.push("cold intolerance");
    result.status = _raiseStatus(result.status, "borderline");
  } else if (tempSens === "hot") {
    pushUnique(result.findings, "Temperature sensitivity: unusually hot.");
    hyperSx.push("heat intolerance");
    result.status = _raiseStatus(result.status, "borderline");
  } else if (tempSens === "neutral") {
    pushUnique(result.findings, "Temperature sensitivity: feels normal.");
  }

  if (yes(tempDiscomfort)) {
    pushUnique(result.findings, "Temperature-related discomfort reported (e.g. sweating or shivering).");
    result.status = _raiseStatus(result.status, "borderline");
  } else if (String(tempDiscomfort || "").toLowerCase() === "no") {
    pushUnique(result.findings, "No temperature-related discomfort reported.");
  }

  if (!isNaN(bbt)) {
    pushUnique(result.findings, "Basal body temperature: " + bbt + " °C.");
    if (bbt < 36.1) {
      hypoSx.push("low basal body temperature");
      result.status = _raiseStatus(result.status, "borderline");
    } else if (bbt >= 37.2) {
      hyperSx.push("elevated basal body temperature");
      result.status = _raiseStatus(result.status, "borderline");
    } else if (bbt > 36.8) {
      result.status = _raiseStatus(result.status, "borderline");
    }
  }

  // —— Thyroid labs ——
  if (hasTsh) {
    pushUnique(result.findings, "TSH: " + tsh + " mIU/L.");
    if (tshHigh) result.status = _raiseStatus(result.status, "abnormal");
    else if (tshLow) result.status = _raiseStatus(result.status, "abnormal");
  } else {
    pushUnique(result.missing, "Enter Thyroid-Stimulating Hormone (TSH) to evaluate thyroid function.");
  }
  if (hasT4) {
    pushUnique(result.findings, "Thyroxine (T4): " + t4 + " pmol/L.");
    if (t4Low || t4High) result.status = _raiseStatus(result.status, "borderline");
  }
  if (hasT3) {
    pushUnique(result.findings, "Triiodothyronine (T3): " + t3 + " pmol/L.");
    if (t3Low || t3High) result.status = _raiseStatus(result.status, "borderline");
  }

  // —— Thyroid autoimmunity ——
  if (yes(autoimmuneHx)) {
    pushUnique(result.findings, "Personal or family history of autoimmune conditions reported.");
  }
  if (yes(autoimmuneSx)) {
    pushUnique(result.findings, "Symptoms compatible with thyroid autoimmunity reported (neck-base swelling, fatigue, or unintentional weight change).");
    result.status = _raiseStatus(result.status, "borderline");
  }
  if (!isNaN(tpoAb)) {
    pushUnique(result.findings, "Thyroid peroxidase antibody (TPOAb): " + tpoAb + " IU/mL.");
    if (tpoAb > 35) result.status = _raiseStatus(result.status, "borderline");
  }
  if (!isNaN(tgAb)) {
    pushUnique(result.findings, "Thyroglobulin antibody (TgAb): " + tgAb + " IU/mL.");
    if (tgAb > 40) result.status = _raiseStatus(result.status, "borderline");
  }

  // —— Adrenal ——
  if (!isNaN(cortisol)) {
    pushUnique(result.findings, "Morning cortisol: " + cortisol + " µg/dL.");
    if (cortisol < 5 || cortisol > 25) result.status = _raiseStatus(result.status, cortisol < 5 ? "abnormal" : "borderline");
  }
  if (!isNaN(acthStim)) {
    pushUnique(result.findings, "ACTH stimulation test result: " + acthStim + " µg/dL.");
    if (acthStim < 18) result.status = _raiseStatus(result.status, "borderline");
  }

  // —— Sex hormones (when entered) ——
  if (yes(hormoneChange)) {
    pushUnique(result.findings, "Recent changes in muscle strength, body shape, or skin health reported.");
    result.status = _raiseStatus(result.status, "borderline");
  }
  if (!isNaN(estrogen)) pushUnique(result.findings, "Estrogen: " + estrogen + " pg/mL.");
  if (!isNaN(testost))  pushUnique(result.findings, "Testosterone: " + testost + " ng/dL.");
  if (!isNaN(progest))  pushUnique(result.findings, "Progesterone: " + progest + " ng/mL.");

  // —— Thirst / fluid hormones ——
  if (yes(thirst)) {
    pushUnique(result.findings, "Increased thirst reported.");
    hyperSx.push("increased thirst");
    result.status = _raiseStatus(result.status, "borderline");
  } else if (String(thirst || "").toLowerCase() === "no") {
    pushUnique(result.findings, "No increase in thirst reported.");
  }
  if (!isNaN(aldo)) {
    pushUnique(result.findings, "Aldosterone: " + aldo + " pmol/L.");
    if (aldo < 100 || aldo > 200) result.status = _raiseStatus(result.status, "borderline");
  }
  if (!isNaN(vaso)) {
    pushUnique(result.findings, "Vasopressin (ADH): " + vaso + " pg/mL.");
    if (vaso < 2 || vaso > 6) result.status = _raiseStatus(result.status, "borderline");
  }

  // —— Hunger / leptin / ghrelin ——
  if (yes(hunger)) {
    pushUnique(result.findings, "Increased hunger or frequent cravings reported.");
    result.status = _raiseStatus(result.status, "borderline");
  } else if (String(hunger || "").toLowerCase() === "no") {
    pushUnique(result.findings, "No increase in hunger reported.");
  }
  if (!isNaN(leptin))  pushUnique(result.findings, "Leptin: " + leptin + " ng/mL.");
  if (!isNaN(ghrelin)) pushUnique(result.findings, "Ghrelin: " + ghrelin + " pg/mL.");

  // —— Skin / hair / ferritin ——
  if (yes(skinChanges)) {
    pushUnique(result.findings, "Changes in skin texture reported.");
    hypoSx.push("skin texture changes");
    result.status = _raiseStatus(result.status, "borderline");
  }
  if (yes(hairChanges)) {
    pushUnique(result.findings, "Hair changes reported (thinning, loss, or texture change).");
    hypoSx.push("hair changes");
    result.status = _raiseStatus(result.status, "borderline");
  }
  if (!isNaN(ferritin)) {
    pushUnique(result.findings, "Ferritin: " + ferritin + " ng/mL.");
    if (ferritin < 30) result.status = _raiseStatus(result.status, "borderline");
  }
  if (!isNaN(hairThy)) {
    pushUnique(result.findings, "Hair-panel thyroid hormone (T3/T4) level: " + hairThy + " pmol/L.");
  }

  // —— Menstrual ——
  if (yes(menstrual)) {
    pushUnique(result.findings, "Menstrual irregularities reported.");
    result.status = _raiseStatus(result.status, "borderline");
  }
  if (!isNaN(cycleVar)) {
    pushUnique(result.findings, "Cycle length variability: " + cycleVar + " days.");
    if (cycleVar >= 7) result.status = _raiseStatus(result.status, "borderline");
  }
  if (!isNaN(periodDur)) {
    pushUnique(result.findings, "Period duration: " + periodDur + " days.");
  }
  if (!isNaN(periodPain)) {
    pushUnique(result.findings, "Menstrual pain severity: " + periodPain + "/10.");
    if (periodPain >= 7) result.status = _raiseStatus(result.status, "borderline");
  }

  // —— Mood / concentration (Yes/No in Endocrine UI) ——
  if (yes(mood)) {
    pushUnique(result.findings, "Mood changes reported.");
    hypoSx.push("mood changes");
    result.status = _raiseStatus(result.status, "borderline");
  }
  if (yes(concentration)) {
    pushUnique(result.findings, "Difficulty concentrating reported.");
    hypoSx.push("difficulty concentrating");
    result.status = _raiseStatus(result.status, "borderline");
  }

  // ========== INTEGRATED INTERPRETATIONS ==========
  if (tshHigh) {
    if (t4Low || t3Low) {
      pushUnique(result.interpretations,
        "Elevated TSH with low free thyroid hormone supports an overt primary hypothyroid pattern rather than an isolated TSH shift.");
    } else if (hasT4 && !t4Low && hasT3 && !t3Low) {
      pushUnique(result.interpretations,
        "Elevated TSH with currently in-range T4/T3 is consistent with a subclinical hypothyroid pattern; correlate with symptoms and autoimmunity.");
    } else if (hasT4 || hasT3) {
      pushUnique(result.interpretations,
        "Elevated TSH with incomplete free-hormone coverage — available T4/T3 should be interpreted together with symptoms before concluding overt vs subclinical hypothyroidism.");
    } else {
      pushUnique(result.interpretations,
        "Elevated TSH suggests a primary hypothyroid pattern; free T4/T3 are needed to distinguish subclinical from overt hypothyroidism.");
    }
    if (hypoSx.length) {
      pushUnique(result.interpretations,
        "Symptom context supporting a hypothyroid-leaning pattern: " + hypoSx.join(", ") + ".");
    }
    if ((!isNaN(tpoAb) && tpoAb > 35) || (!isNaN(tgAb) && tgAb > 40) || yes(autoimmuneHx) || yes(autoimmuneSx)) {
      pushUnique(result.interpretations,
        "Autoimmune signals (antibodies and/or autoimmune history/symptoms) raise the likelihood of autoimmune thyroiditis contributing to the TSH elevation.");
    }
    if (!isNaN(bbt) && bbt < 36.1) {
      pushUnique(result.interpretations,
        "Low basal body temperature alongside elevated TSH further supports reduced metabolic thyroid effect.");
    }
  } else if (tshLow) {
    if (t4High || t3High) {
      pushUnique(result.interpretations,
        "Suppressed TSH with elevated free thyroid hormone supports a hyperthyroid pattern.");
    } else if (hasT4 && !t4High && hasT3 && !t3High) {
      pushUnique(result.interpretations,
        "Suppressed TSH with in-range free hormones may reflect subclinical hyperthyroidism, exogenous thyroid hormone, or non-thyroidal influence — correlate clinically.");
    } else {
      pushUnique(result.interpretations,
        "Suppressed TSH suggests a hyperthyroid or central/exogenous pattern; free T4/T3 clarify the mechanism.");
    }
    if (hyperSx.length) {
      pushUnique(result.interpretations,
        "Symptom context supporting a hyperthyroid-leaning pattern: " + hyperSx.join(", ") + ".");
    }
  } else if (hasTsh && !tshHigh && !tshLow && (t4Low || t4High || t3Low || t3High)) {
    pushUnique(result.interpretations,
      "TSH is within the usual reference band while free T4 and/or T3 are outside range — consider conversion issues, binding changes, assay timing, or non-thyroidal illness.");
  }

  if ((!isNaN(tpoAb) && tpoAb > 35) || (!isNaN(tgAb) && tgAb > 40)) {
    pushUnique(result.interpretations,
      "Elevated thyroid antibodies indicate autoimmune thyroid activity; longitudinal TSH/free-hormone monitoring is clinically relevant even when current TSH is near normal.");
  }

  if (!isNaN(cortisol) && cortisol < 5) {
    pushUnique(result.interpretations,
      "Low morning cortisol may suggest adrenal insufficiency or blunted HPA-axis output" +
      (fatigue === "Frequently" ? ", especially with frequent fatigue" : "") + ".");
    if (!isNaN(acthStim) && acthStim < 18) {
      pushUnique(result.interpretations,
        "ACTH stimulation response below the usual adequacy threshold strengthens concern for adrenal insufficiency.");
    }
  } else if (!isNaN(cortisol) && cortisol > 25) {
    pushUnique(result.interpretations,
      "High morning cortisol can reflect stress physiology, exogenous glucocorticoid effect, or Cushing-spectrum states — interpret with clinical context.");
  }

  if (yes(thirst) && yes(hunger)) {
    pushUnique(result.interpretations,
      "Combined increased thirst and hunger can suggest glucose dysregulation or other metabolic endocrine strain.");
  } else if (yes(thirst) && (!isNaN(aldo) || !isNaN(vaso))) {
    if (!isNaN(aldo) && aldo < 100 && !isNaN(vaso) && vaso < 2) {
      pushUnique(result.interpretations,
        "Increased thirst with low aldosterone and vasopressin may reflect central or adrenal fluid-regulation underactivity.");
    } else if ((!isNaN(aldo) && aldo > 200) || (!isNaN(vaso) && vaso > 6)) {
      pushUnique(result.interpretations,
        "Increased thirst with elevated aldosterone and/or vasopressin may reflect volume depletion or compensatory fluid-hormone activation.");
    }
  }

  if (yes(hunger) && (!isNaN(leptin) || !isNaN(ghrelin))) {
    pushUnique(result.interpretations,
      "Hunger symptoms with available leptin/ghrelin values should be interpreted as appetite-axis context rather than a standalone diagnosis.");
  }

  if (!isNaN(ferritin) && ferritin < 30) {
    pushUnique(result.interpretations,
      "Low ferritin can drive fatigue and hair changes and may amplify an endocrine symptom picture even when thyroid labs are only mildly abnormal.");
  }

  if (yes(menstrual) || (!isNaN(cycleVar) && cycleVar >= 7) || (!isNaN(periodPain) && periodPain >= 7)) {
    const thyroidLink = (tshHigh || tshLow || (!isNaN(tpoAb) && tpoAb > 35))
      ? " Thyroid dysfunction or autoimmunity can contribute to cycle irregularity."
      : "";
    pushUnique(result.interpretations,
      "Menstrual irregularity and/or significant dysmenorrhoea can reflect sex-hormone imbalance, thyroid influence, or metabolic strain." + thyroidLink);
  }

  if (yes(mood) || yes(concentration)) {
    pushUnique(result.interpretations,
      "Mood and/or concentration changes can accompany thyroid, adrenal, or sex-hormone imbalance and should be correlated with the laboratory pattern above.");
  }

  if (coldIntol && tshHigh) {
    pushUnique(result.interpretations,
      "Cold intolerance together with elevated TSH is a coherent hypothyroid-leaning clinical combination.");
  }
  if (heatIntol && tshLow) {
    pushUnique(result.interpretations,
      "Heat intolerance together with suppressed TSH is a coherent hyperthyroid-leaning clinical combination.");
  }

  // ========== NEXT STEPS (analytical layer) ==========
  if (tshHigh) {
    pushUnique(result.nextSteps,
      "Correlate elevated TSH with free T4/T3, autoimmune antibodies, and hypothyroid-leaning symptoms (cold intolerance, fatigue, hair/skin changes) before deciding on replacement or watchful waiting.");
    if (!hasT4 || !hasT3) {
      pushUnique(result.nextSteps,
        "Complete free T4 and free T3 if not already available to classify subclinical versus overt hypothyroidism.");
    }
  }
  if (tshLow) {
    pushUnique(result.nextSteps,
      "Correlate suppressed TSH with free T4/T3 and hyperthyroid-leaning symptoms; review exogenous thyroid hormone or other medications if applicable.");
  }
  if ((!isNaN(tpoAb) && tpoAb > 35) || (!isNaN(tgAb) && tgAb > 40) || yes(autoimmuneSx)) {
    pushUnique(result.nextSteps,
      "Plan serial thyroid function follow-up when autoimmune thyroid markers or symptoms are present.");
  }
  if (!isNaN(cortisol) && cortisol < 5) {
    pushUnique(result.nextSteps,
      "Arrange clinician review of low morning cortisol; ensure an ACTH stimulation pathway is completed if not already done.");
  }
  if (yes(thirst) && yes(hunger)) {
    pushUnique(result.nextSteps,
      "Review glucose status (fasting glucose / HbA1c) in light of combined thirst and hunger.");
  }
  if (!isNaN(ferritin) && ferritin < 30 && (yes(hairChanges) || fatigue === "Frequently")) {
    pushUnique(result.nextSteps,
      "Address low iron stores in parallel with endocrine evaluation when fatigue or hair changes are present.");
  }
  if (yes(menstrual) || (!isNaN(cycleVar) && cycleVar >= 7)) {
    pushUnique(result.nextSteps,
      "Document cycle length, bleeding pattern and pain, and correlate with thyroid and sex-hormone results.");
  }
  if (tempSens === "cold" || tempSens === "hot" || (!isNaN(bbt) && (bbt < 36.1 || bbt >= 37.2))) {
    pushUnique(result.nextSteps,
      "Track temperature sensitivity and basal body temperature alongside thyroid and adrenal markers rather than in isolation.");
  }

  // ========== SUGGESTED TESTS (accessible layer; with reasons) ==========
  // Reason text must not name already-entered known-metric tokens (e.g. TSH),
  // or prune drops the whole line even when the suggested test is still missing.
  if (tshHigh) {
    if (!hasT4) {
      suggest("Free T4",
        "an elevated pituitary thyroid signal needs free circulating T4 to distinguish subclinical from overt hypothyroidism.");
    }
    if (!hasT3) {
      suggest("Free T3",
        "completing the free-hormone panel clarifies peripheral hormone availability when the pituitary thyroid signal is high.");
    }
    if (isNaN(tpoAb)) {
      suggest("Thyroid peroxidase antibody (TPOAb)",
        "autoimmune thyroiditis is a common driver of a rising pituitary thyroid signal.");
    }
  }
  if (tshLow) {
    if (!hasT4) suggest("Free T4", "a suppressed pituitary thyroid signal requires free circulating T4 to assess hyperthyroid activity.");
    if (!hasT3) suggest("Free T3", "T3 excess can drive hyperthyroid symptoms when the pituitary thyroid signal is low.");
  }
  if ((yes(autoimmuneHx) || yes(autoimmuneSx)) && isNaN(tpoAb)) {
    suggest("Thyroid peroxidase antibody (TPOAb)",
      "autoimmune history or symptoms are reported without a TPOAb value.");
  }
  if ((yes(autoimmuneHx) || yes(autoimmuneSx)) && isNaN(tgAb)) {
    suggest("Thyroglobulin antibody (TgAb)",
      "complements TPOAb when autoimmune thyroid disease is being considered.");
  }
  if (!isNaN(cortisol) && cortisol < 5 && isNaN(acthStim)) {
    suggest("ACTH stimulation test",
      "morning adrenal output is low and stimulation testing clarifies adrenal reserve.");
  }
  if (isNaN(cortisol) && (fatigue === "Frequently" || coldIntol)) {
    suggest("Morning cortisol",
      "frequent fatigue or cold intolerance can reflect adrenal as well as thyroid strain.");
  }
  if ((yes(thirst) && yes(hunger))) {
    suggest("Fasting glucose",
      "combined thirst and hunger warrant glucose assessment.");
    suggest("HbA1c",
      "provides a longer-term glucose exposure measure alongside a fasting sample.");
  }
  if ((yes(hairChanges) || fatigue === "Frequently") && isNaN(ferritin)) {
    suggest("Ferritin",
      "low iron stores commonly contribute to fatigue and hair changes.");
  }
  if (!isNaN(ferritin) && ferritin < 30) {
    suggest("Iron studies and full blood count (CBC)",
      "iron stores are low and broader iron/haematology context guides management.");
  }
  if (yes(menstrual) && isNaN(estrogen) && isNaN(progest)) {
    suggest("Clinician-directed sex-hormone panel (estrogen / progesterone as appropriate)",
      "menstrual irregularity is reported without sex-hormone values in this section.");
  }
  if (!hasTsh && (coldIntol || heatIntol || yes(hairChanges) || fatigue === "Frequently")) {
    suggest("Thyroid-Stimulating Hormone (TSH)",
      "temperature, fatigue or hair symptoms are present without a pituitary thyroid-signal value.");
  }
  if (!result.suggestedTests.length &&
      (result.findings.length || result.status !== "normal")) {
    if (!hasT4 && (tshHigh || tshLow || hypoSx.length || hyperSx.length)) {
      suggest("Free T4",
        "the current endocrine pattern still needs free circulating T4 to classify overt versus subclinical thyroid disease.");
    }
    if (!hasT3 && (tshHigh || tshLow || hypoSx.length || hyperSx.length)) {
      suggest("Free T3",
        "the current endocrine pattern still needs free circulating T3 to complete the peripheral hormone picture.");
    }
    if (isNaN(tpoAb) && (hypoSx.length || yes(autoimmuneHx) || yes(autoimmuneSx) || tshHigh)) {
      suggest("Thyroid peroxidase antibody (TPOAb)",
        "the current thyroid-leaning pattern has no autoimmune antibody result in this section.");
    }
    if (isNaN(cortisol) && (fatigue === "Frequently" || hypoSx.length)) {
      suggest("Morning cortisol",
        "fatigue or hypothyroid-leaning symptoms can reflect adrenal as well as thyroid strain.");
    }
  }

  _contributeCluster(["neuroendocrineStrain"], result.status, result.findings.length);
  try {
    var fjoin = ((result.findings || []).join(" ") + " " + (result.interpretations || []).join(" ")).toLowerCase();
    if (fjoin.indexOf("glucose") !== -1 || fjoin.indexOf("hba1c") !== -1 ||
        (fjoin.indexOf("thirst") !== -1 && fjoin.indexOf("hunger") !== -1)) {
      _contributeCluster(["metabolicSlowdown"], result.status, result.findings.length);
      result._clusterKeys = ["neuroendocrineStrain", "metabolicSlowdown"];
    }
  } catch (eMetCluster) {}
  _applyMedImpact(result, "endocrine", context && context.medicationImpact);
  return result;
}

/* ---------- NEURAL ---------- */
function interpretNeural(context) {
  const result = {
    category: "neural",
    status: "normal",
    findings: [],
    interpretations: [],
    nextSteps: [],
    suggestedTests: [],
    medicationNotes: [],
    warnings: [],
    missing: []
  };

  const get = (typeof getRadioValue === "function") ? getRadioValue : () => "";
  const active = (v) => !!(v && v !== "Never" && v !== "No" && String(v).trim() !== "");
  const freqHigh = (v) => v === "Frequently" || v === "Constantly" || v === "Often" ||
    v === "Multiple times a day" || v === "Once a day";
  const pushUnique = (arr, msg) => {
    if (!msg) return;
    if (arr.indexOf(msg) === -1) arr.push(msg);
  };

  // —— Core symptom frequencies / descriptors (live Neural questionnaire) ——
  const headacheFreq   = get("headacheFrequency");
  const dizzinessFreq  = get("dizzinessFrequency"); // also resolves dizzinessFrequency__2
  const dizzinessType  = get("dizzinessType");
  const dizzinessMove  = get("dizzinessMovement");
  const dizzinessDur   = get("dizzinessDuration");
  const dizzinessOcc   = get("dizzinessOccurrence");
  const dizzinessOnset = get("dizzinessOnset");
  const dizzinessTiming= get("dizzinessTiming");
  const numbnessFreq   = get("numbnessFrequency");
  const numbnessLoc    = get("numbnessLocation"); // multiselect → "Fingers, Toes"
  const numbnessDur    = get("numbnessDuration");
  const numbnessTrig   = get("numbnessTrigger");
  const numbnessExtra  = get("numbnessAdditionalSymptoms");
  const tremorFreq     = get("tremorsFrequency");
  const tremorLoc      = get("tremorsLocation");
  const tremorWhen     = get("tremorsTiming");
  const tremorDur      = get("tremorsDuration");
  const tremorExtra    = get("tremorsAdditionalSymptoms");
  const seizureFreq    = get("seizuresFrequency");
  const seizureType    = get("seizuresType");
  const seizureDur     = get("seizuresDuration");
  const seizureTrig    = get("seizuresTriggers");
  const seizureExtra   = get("seizuresAdditionalSymptoms");
  const memoryFreq     = get("memoryLossFrequency");
  const memoryType     = get("memoryLossType");
  const memoryOnset    = get("memoryLossOnset");
  const memoryTrig     = get("memoryLossTriggers");
  const memoryExtra    = get("memoryLossAdditionalSymptoms");
  const memoryRecall   = get("memoryRecall");
  const memoryRecog    = get("memoryRecognition");
  const shortTermMem   = get("shortTermMemory");
  const longTermMem    = get("longTermMemory");
  const memoryNames    = get("memoryNamesDates");
  const speechDiff     = get("speechDifficulty");
  const speechType     = get("speechType");
  const speechOnset    = get("speechOnset");
  const speechFreq     = get("speechFrequency");
  const speechSev      = get("speechSeverity");
  const speechExtra    = get("speechAdditionalSymptoms");
  const muscleWeak     = get("muscleWeakness");
  const muscleArea     = get("muscleWeaknessArea");
  const muscleFreq     = get("muscleWeaknessFrequency");
  const muscleOnset    = get("muscleWeaknessOnset");
  const muscleSev      = get("muscleWeaknessSeverity");
  const visionChange   = get("visionChanges");
  const visionType     = get("visionType");
  const balanceFalls   = get("balanceFalls");
  const balanceOneFoot = get("balanceTestOneFoot");
  const balanceTandem  = get("balanceTestTandemWalk");
  const balanceStairs  = get("balanceStairs");
  const lightSound     = get("sensitivityLightSound");
  const sensitivityType= get("sensitivityType");
  const sensitivityFreq= get("sensitivityFrequency");
  const sensitivitySev = get("sensitivitySeverity");

  let symptomDomains = 0;

  // —— Headache ——
  if (active(headacheFreq)) {
    symptomDomains++;
    result.findings.push(`Headaches: ${headacheFreq}.`);
    if (freqHigh(headacheFreq)) {
      pushUnique(result.interpretations,
        "Frequent headaches may reflect vascular, muscular tension, migraine-spectrum, or neurological strain and deserve structured tracking.");
      pushUnique(result.nextSteps, "Keep a 2-week headache diary (time, trigger, intensity, associated symptoms).");
      result.status = _raiseStatus(result.status, "borderline");
    } else {
      pushUnique(result.interpretations,
        `Headaches reported as ${headacheFreq.toLowerCase()} — interpret alongside dizziness, vision change, and seizure history if present.`);
      result.status = _raiseStatus(result.status, "borderline");
    }
  }

  // —— Dizziness ——
  if (active(dizzinessFreq)) {
    symptomDomains++;
    result.findings.push(`Dizziness: ${dizzinessFreq}.`);
    if (dizzinessType) result.findings.push(`Dizziness quality: ${dizzinessType}.`);
    if (dizzinessTiming) result.findings.push(`Dizziness context: ${dizzinessTiming}.`);
    if (dizzinessDur) result.findings.push(`Dizziness duration: ${dizzinessDur}.`);
    if (dizzinessOcc) result.findings.push(`Dizziness occurrence: ${dizzinessOcc}.`);
    if (dizzinessOnset) result.findings.push(`Dizziness onset: ${dizzinessOnset}.`);
    if (dizzinessMove) result.findings.push(`Related to sudden movement: ${dizzinessMove}.`);

    const dtype = String(dizzinessType || "").toLowerCase();
    if (dtype.indexOf("spinning") !== -1 || dtype.indexOf("vertigo") !== -1) {
      pushUnique(result.interpretations,
        "Vertigo-type (spinning) dizziness may reflect vestibular involvement; correlate with head movement and balance findings.");
      pushUnique(result.suggestedTests, "Orthostatic vitals and focused vestibular / neurological exam.");
      result.status = _raiseStatus(result.status, "borderline");
    } else if (dtype.indexOf("balance") !== -1) {
      pushUnique(result.interpretations,
        "Dizziness described as loss of balance raises concern for vestibular, cerebellar, or proprioceptive contribution.");
      result.status = _raiseStatus(result.status, "borderline");
    } else if (dtype.indexOf("faint") !== -1 ||
               String(dizzinessTiming || "").toLowerCase().indexOf("standing") !== -1) {
      pushUnique(result.interpretations,
        "Lightheaded or faint-feeling dizziness, especially on standing, may reflect blood-pressure or autonomic factors.");
      pushUnique(result.suggestedTests, "Lying/standing blood pressure and pulse.");
      result.status = _raiseStatus(result.status, "borderline");
    } else {
      pushUnique(result.interpretations,
        "Lightheaded dizziness may reflect blood pressure, dehydration, medication effect, or autonomic factors.");
      result.status = _raiseStatus(result.status, "borderline");
    }
    if (freqHigh(dizzinessFreq) || freqHigh(dizzinessOcc)) {
      result.status = _raiseStatus(result.status, "abnormal");
      pushUnique(result.nextSteps, "Review hydration, recent medication changes, and orthostatic symptoms with a clinician.");
    }
  }

  // —— Numbness / tingling + location ——
  if (active(numbnessFreq)) {
    symptomDomains++;
    result.findings.push(`Numbness/tingling: ${numbnessFreq}.`);
    if (numbnessLoc) result.findings.push(`Numbness location: ${numbnessLoc}.`);
    if (numbnessDur) result.findings.push(`Numbness episode length: ${numbnessDur}.`);
    if (numbnessTrig) result.findings.push(`Numbness triggers: ${numbnessTrig}.`);
    if (numbnessExtra && numbnessExtra !== "None") {
      result.findings.push(`With numbness: ${numbnessExtra}.`);
    }

    const loc = String(numbnessLoc || "").toLowerCase();
    const distal =
      loc.indexOf("finger") !== -1 || loc.indexOf("toe") !== -1 ||
      loc.indexOf("hand") !== -1 || loc.indexOf("feet") !== -1 || loc.indexOf("foot") !== -1;
    const multiDistal =
      (loc.indexOf("finger") !== -1 || loc.indexOf("hand") !== -1) &&
      (loc.indexOf("toe") !== -1 || loc.indexOf("feet") !== -1 || loc.indexOf("foot") !== -1);
    const prolonged = numbnessDur === "Several hours" || numbnessDur === "All day";

    if (multiDistal) {
      pushUnique(result.interpretations,
        `Numbness/tingling involving both distal upper and lower sites (${numbnessLoc}) suggests a length-dependent or multisite sensory pattern rather than a single local pressure point; clinical mapping is warranted.`);
      pushUnique(result.suggestedTests, "Neurological exam with sensory distribution mapping; B12; fasting glucose / HbA1c if not recent.");
      result.status = _raiseStatus(result.status, prolonged || freqHigh(numbnessFreq) ? "abnormal" : "borderline");
    } else if (distal && numbnessLoc) {
      pushUnique(result.interpretations,
        `Numbness/tingling localised to ${numbnessLoc} is consistent with a distal sensory pattern; consider positional compression, peripheral nerve irritation, or systemic sensory involvement depending on persistence and spread.`);
      result.status = _raiseStatus(result.status, "borderline");
    } else if (numbnessLoc) {
      pushUnique(result.interpretations,
        `Numbness/tingling reported in ${numbnessLoc} — distribution should guide whether the pattern looks focal, distal, or more generalised.`);
      result.status = _raiseStatus(result.status, "borderline");
    } else {
      pushUnique(result.interpretations,
        "Numbness/tingling is reported without a clear mapped distribution; recording exact sites improves neurological interpretation.");
      result.status = _raiseStatus(result.status, "borderline");
    }

    if (prolonged || freqHigh(numbnessFreq)) {
      pushUnique(result.interpretations,
        "Longer-lasting or frequent sensory symptoms increase the need to exclude progressive peripheral or central sensory involvement.");
      pushUnique(result.suggestedTests, "Neurological exam and B12 level.");
      result.status = _raiseStatus(result.status, "abnormal");
    }
    if (String(numbnessExtra || "").toLowerCase().indexOf("weakness") !== -1) {
      pushUnique(result.interpretations,
        "Sensory symptoms accompanied by weakness raise the stakes for combined sensorimotor involvement and should not be dismissed as positional tingling alone.");
      result.status = _raiseStatus(result.status, "abnormal");
    }
  }

  // —— Tremor ——
  if (active(tremorFreq)) {
    symptomDomains++;
    result.findings.push(`Tremor: ${tremorFreq}.`);
    if (tremorLoc) result.findings.push(`Tremor location: ${tremorLoc}.`);
    if (tremorWhen) result.findings.push(`Tremor timing: ${tremorWhen}.`);
    if (tremorDur) result.findings.push(`Tremor duration: ${tremorDur}.`);
    if (tremorExtra && tremorExtra !== "None") {
      result.findings.push(`With tremor: ${tremorExtra}.`);
    }

    const tw = String(tremorWhen || "").toLowerCase();
    if (tw.indexOf("at rest") !== -1) {
      pushUnique(result.interpretations,
        "Rest-predominant tremor pattern warrants neurological evaluation to characterise phenomenology and associated features.");
      result.status = _raiseStatus(result.status, "abnormal");
    } else if (tw.indexOf("movement") !== -1) {
      pushUnique(result.interpretations,
        "Action/movement-related tremor may reflect enhanced physiological, medication-related, or neurological tremor patterns; correlate with caffeine, anxiety, and medication list.");
      result.status = _raiseStatus(result.status, "borderline");
    } else {
      pushUnique(result.interpretations,
        "Tremor is reported; timing (rest vs action) and distribution help separate enhanced physiological tremor from a primary neurological tremor pattern.");
      result.status = _raiseStatus(result.status, "borderline");
    }
    if (freqHigh(tremorFreq)) {
      result.status = _raiseStatus(result.status, "abnormal");
      pushUnique(result.nextSteps, "Document tremor timing (rest/action), body parts involved, and functional impact for clinical review.");
    }
  }

  // —— Seizure activity (frequency + type + context) ——
  if (active(seizureFreq)) {
    symptomDomains++;
    result.findings.push(`Seizure activity reported: ${seizureFreq}.`);
    if (seizureType) result.findings.push(`Seizure type (patient-reported): ${seizureType}.`);
    if (seizureDur) result.findings.push(`Seizure duration: ${seizureDur}.`);
    if (seizureTrig) result.findings.push(`Reported seizure triggers: ${seizureTrig}.`);
    if (seizureExtra && seizureExtra !== "None") {
      result.findings.push(`Associated seizure features: ${seizureExtra}.`);
    }

    const st = String(seizureType || "");
    const hasGen = /generalized/i.test(st);
    const hasFocal = /focal/i.test(st) || /part of the brain/i.test(st);
    if (hasGen && hasFocal) {
      pushUnique(result.interpretations,
        `Patient-reported seizure activity (${seizureFreq}) includes both generalised and focal descriptors. Mixed phenomenology increases urgency for specialist characterisation; questionnaire labels are not a confirmed electroclinical diagnosis.`);
    } else if (hasGen) {
      pushUnique(result.interpretations,
        `Patient-reported generalised seizure-type activity occurring ${String(seizureFreq).toLowerCase()} requires neurological assessment; do not rely on self-classification alone.`);
    } else if (hasFocal) {
      pushUnique(result.interpretations,
        `Patient-reported focal / partial seizure-type activity occurring ${String(seizureFreq).toLowerCase()} requires neurological assessment with attention to lateralising features and post-event state.`);
    } else {
      pushUnique(result.interpretations,
        `Seizure activity reported as ${seizureFreq.toLowerCase()} requires neurological assessment even when type is uncertain.`);
    }

    if (freqHigh(seizureFreq)) {
      pushUnique(result.interpretations,
        "Frequent seizure reports are a high-priority neurological red flag and should prompt timely specialist review rather than watchful waiting.");
      result.status = "abnormal";
    } else {
      result.status = _raiseStatus(result.status, "abnormal");
    }
    if (seizureDur === "More than 5 minutes") {
      pushUnique(result.interpretations,
        "Reported events lasting more than 5 minutes are especially concerning and need urgent clinical safety planning.");
      pushUnique(result.warnings, "Prolonged seizure-like events require urgent medical pathways if they recur.");
    }
    if (seizureTrig) {
      pushUnique(result.interpretations,
        `Reported triggers (${seizureTrig}) should be recorded for counselling (sleep, stress, lights) while specialist assessment proceeds.`);
    }
    pushUnique(result.nextSteps, "Seek neurological consultation for seizure characterisation and safety advice.");
    pushUnique(result.suggestedTests, "Neurological consultation; clinician-directed EEG / neuroimaging as indicated.");
  }

  // —— Memory / cognition ——
  if (active(memoryFreq)) {
    symptomDomains++;
    result.findings.push(`Memory symptoms: ${memoryFreq}.`);
    if (memoryType) result.findings.push(`Memory domain: ${memoryType}.`);
    if (memoryOnset) result.findings.push(`Memory onset: ${memoryOnset}.`);
    if (memoryTrig) result.findings.push(`Memory triggers: ${memoryTrig}.`);
    if (memoryExtra && memoryExtra !== "None") {
      result.findings.push(`Additional cognitive symptoms: ${memoryExtra}.`);
    }
    pushUnique(result.interpretations,
      "Subjective memory change should be interpreted with sleep, mood, medication, and metabolic context; progressive or sudden decline needs clinical cognitive assessment.");
    result.status = _raiseStatus(result.status, freqHigh(memoryFreq) ? "abnormal" : "borderline");
    if (freqHigh(memoryFreq) || memoryOnset === "Suddenly") {
      pushUnique(result.nextSteps, "Arrange clinical cognitive review; note onset pattern and functional impact.");
      pushUnique(result.suggestedTests, "Basic cognitive screen; B12; metabolic panel as clinically appropriate.");
    }
  }
  if (memoryRecall === "Poor" || memoryRecog === "Poor" || shortTermMem === "Poor" || longTermMem === "Poor") {
    if (!active(memoryFreq)) symptomDomains++;
    result.findings.push("Self-rated memory performance includes Poor in one or more domains.");
    pushUnique(result.interpretations,
      "Poor self-rated recall/recognition supports further cognitive enquiry even when daily frequency answers are limited.");
    result.status = _raiseStatus(result.status, "borderline");
  }
  if (memoryNames === "Yes" || memoryNames === "Sometimes") {
    result.findings.push(`Difficulty remembering names/dates: ${memoryNames}.`);
  }

  // —— Speech ——
  if (speechDiff === "Yes") {
    symptomDomains++;
    result.findings.push("Speech difficulty: Yes.");
    if (speechType) result.findings.push(`Speech pattern: ${speechType}.`);
    if (speechOnset) result.findings.push(`Speech onset: ${speechOnset}.`);
    if (speechFreq) result.findings.push(`Speech frequency: ${speechFreq}.`);
    if (speechSev) result.findings.push(`Speech severity: ${speechSev}.`);
    if (speechExtra && speechExtra !== "None") {
      result.findings.push(`With speech change: ${speechExtra}.`);
    }
    if (speechOnset === "Suddenly") {
      pushUnique(result.interpretations,
        "Sudden speech difficulty is a neurological red flag and needs urgent clinical assessment, especially with facial weakness or swallowing change.");
      result.status = "abnormal";
      pushUnique(result.nextSteps, "Urgent clinical assessment for sudden speech change.");
    } else {
      pushUnique(result.interpretations,
        "Speech difficulty warrants neurological or speech-language characterisation according to onset, severity, and associated cranial features.");
      result.status = _raiseStatus(result.status, speechSev === "Severe" || freqHigh(speechFreq) ? "abnormal" : "borderline");
    }
    if (String(speechExtra || "").toLowerCase().indexOf("facial") !== -1 ||
        String(speechExtra || "").toLowerCase().indexOf("swallow") !== -1) {
      pushUnique(result.interpretations,
        "Speech change with facial weakness or swallowing difficulty increases concern for central or bulbar involvement.");
      result.status = "abnormal";
    }
  }

  // —— Muscle weakness ——
  if (muscleWeak === "Yes") {
    symptomDomains++;
    result.findings.push("Muscle weakness: Yes.");
    if (muscleArea) result.findings.push(`Weakness distribution: ${muscleArea}.`);
    if (muscleFreq) result.findings.push(`Weakness frequency: ${muscleFreq}.`);
    if (muscleOnset) result.findings.push(`Weakness onset: ${muscleOnset}.`);
    if (muscleSev) result.findings.push(`Weakness severity: ${muscleSev}.`);
    if (muscleOnset === "Suddenly") {
      pushUnique(result.interpretations,
        "Sudden muscle weakness is a high-priority neurological symptom and needs prompt clinical assessment.");
      result.status = "abnormal";
      pushUnique(result.nextSteps, "Prompt clinical assessment for sudden weakness.");
    } else {
      pushUnique(result.interpretations,
        "Muscle weakness should be mapped by distribution (focal vs generalised) and related to sensory and tremor findings where present.");
      result.status = _raiseStatus(result.status, muscleSev === "Severe" || freqHigh(muscleFreq) ? "abnormal" : "borderline");
    }
  }

  // —— Vision ——
  if (visionChange === "Yes") {
    symptomDomains++;
    result.findings.push("Vision changes: Yes.");
    if (visionType) result.findings.push(`Vision symptoms: ${visionType}.`);
    pushUnique(result.interpretations,
      "New vision change alongside other neurological symptoms should be reviewed clinically; transient visual loss or double vision is particularly important.");
    result.status = _raiseStatus(result.status, "borderline");
  }

  // —— Balance / falls ——
  if (balanceFalls === "Yes" || balanceOneFoot === "No" || balanceTandem === "No" ||
      balanceStairs === "Yes" || balanceStairs === "Sometimes") {
    symptomDomains++;
    if (balanceFalls === "Yes") result.findings.push("Falls reported: Yes.");
    if (balanceOneFoot === "No") result.findings.push("Unable to stand on one foot (self-report).");
    if (balanceTandem === "No") result.findings.push("Unable to tandem walk (self-report).");
    if (balanceStairs === "Yes" || balanceStairs === "Sometimes") {
      result.findings.push(`Stair balance difficulty: ${balanceStairs}.`);
    }
    pushUnique(result.interpretations,
      "Balance limitation or falls increase fall-risk and may reflect vestibular, sensory, cerebellar, or orthostatic contributors when paired with dizziness or numbness.");
    result.status = _raiseStatus(result.status, balanceFalls === "Yes" ? "abnormal" : "borderline");
    pushUnique(result.nextSteps, "Fall-risk review: footwear, lighting, orthostatic vitals, and medication sedating effects.");
  }

  if (lightSound === "Yes") {
    symptomDomains++;
    result.findings.push("Light/sound sensitivity: Yes.");
    if (sensitivityType) result.findings.push(`Sensitivity type: ${sensitivityType}.`);
    if (sensitivityFreq) result.findings.push(`Sensitivity frequency: ${sensitivityFreq}.`);
    if (sensitivitySev) result.findings.push(`Sensitivity severity: ${sensitivitySev}.`);
    pushUnique(result.interpretations,
      "Photophobia/phonophobia can accompany migraine-spectrum headache patterns; interpret with headache frequency and nausea if present.");
    if (active(headacheFreq)) {
      pushUnique(result.interpretations,
        "Light/sound sensitivity together with headaches supports considering a migraine-associated pattern pending clinical confirmation.");
    }
    result.status = _raiseStatus(result.status, freqHigh(sensitivityFreq) || sensitivitySev === "Severe" ? "abnormal" : "borderline");
  }

  // —— Combination / pattern logic (existing answers only) ——
  if (active(seizureFreq) && (active(headacheFreq) || active(dizzinessFreq) || visionChange === "Yes")) {
    pushUnique(result.interpretations,
      "Seizure reports coexisting with headache, dizziness, or vision change form a broader neurological symptom cluster that should be presented together at specialist review.");
  }
  if (active(numbnessFreq) && muscleWeak === "Yes") {
    pushUnique(result.interpretations,
      "Combined sensory and motor symptoms suggest a sensorimotor pattern; distribution (distal vs proximal, unilateral vs bilateral) should be clarified clinically.");
    result.status = _raiseStatus(result.status, "abnormal");
  }
  if (active(tremorFreq) && (muscleWeak === "Yes" || active(numbnessFreq))) {
    pushUnique(result.interpretations,
      "Tremor together with weakness or sensory change is more informative than tremor alone and supports formal neurological examination.");
  }
  if (active(headacheFreq) && active(dizzinessFreq)) {
    pushUnique(result.interpretations,
      "Headache with dizziness can reflect migraine-associated, vestibular, vascular, or orthostatic pathways; associated vision change or prolonged symptoms raise the need for clinical review.");
  }
  if (active(dizzinessFreq) && (balanceFalls === "Yes" || balanceOneFoot === "No" || balanceTandem === "No")) {
    pushUnique(result.interpretations,
      "Dizziness with objective balance difficulty or falls is a higher-risk combination than isolated lightheadedness.");
    result.status = _raiseStatus(result.status, "abnormal");
  }
  if (speechDiff === "Yes" && (muscleWeak === "Yes" || visionChange === "Yes" || active(numbnessFreq))) {
    pushUnique(result.interpretations,
      "Speech change with additional neurological deficits (weakness, vision, or sensory symptoms) increases urgency for medical assessment.");
    result.status = "abnormal";
  }
  if (symptomDomains >= 3) {
    pushUnique(result.interpretations,
      "Multiple concurrent neurological symptom domains are present; an integrated neurological assessment is more appropriate than evaluating each symptom in isolation.");
    pushUnique(result.nextSteps, "Seek neurological consultation for multi-domain symptom review.");
    result.status = _raiseStatus(result.status, "abnormal");
  }

  // —— Default next steps when abnormal but none yet ——
  if (result.status === "abnormal" && !result.nextSteps.length) {
    pushUnique(result.nextSteps, "Seek neurological consultation.");
  }
  if (result.status !== "normal" && !result.suggestedTests.length) {
    pushUnique(result.suggestedTests, "Clinical neurological examination.");
  }

  if (!result.findings.length) {
    result.missing.push("No neural symptoms reported.");
  }

  _contributeCluster(["neurologicalLoad"], result.status, result.findings.length);
  _applyMedImpact(result, "neural", context && context.medicationImpact);
  return result;
}

/* ---------- GASTROINTESTINAL ---------- */
function interpretGastrointestinal(context) {
  const result = {
    category: "gastrointestinal",
    status: "normal",
    findings: [],
    interpretations: [],
    nextSteps: [],
    suggestedTests: [],
    medicationNotes: [],
    warnings: [],
    missing: []
  };

  const get = (typeof getRadioValue === "function") ? getRadioValue : () => "";
  const ms = (typeof getMultiSelectOptions === "function")
    ? getMultiSelectOptions
    : () => [];
  const hasOpt = (base, opt) =>
    (typeof OSIRIS_hasOption === "function" && OSIRIS_hasOption(base, opt));
  const pushUnique = (arr, msg) => {
    if (!msg) return;
    if (arr.indexOf(msg) === -1) arr.push(msg);
  };
  const isActiveFreq = (v) => {
    const s = String(v == null ? "" : v).trim();
    return !!(s && s !== "Rarely" && s !== "Never" && s !== "No Change");
  };
  const yes = (v) => {
    const s = String(v == null ? "" : v).trim().toLowerCase();
    return s === "yes" || s === "y";
  };
  const joinList = (arr) => (arr && arr.length) ? arr.join(", ") : "";

  // Prefer GI-panel heartburn group (__2) when present so Upper Respiratory
  // Never/Rarely answers do not mask the Gastrointestinal questionnaire.
  const abdPainFreq   = get("abdominalPainFrequency");
  const abdPainType   = get("abdominalPainType");
  const abdPainLoc    = get("abdominalPainLocation");
  const abdPainTrig   = get("abdominalPainTriggers");
  const abdPainDur    = get("abdominalPainDuration");
  const abdPainSev    = get("abdominalPainSeverity");
  const abdPainAssoc  = ms("abdominalPainAssociatedSymptoms");
  const abdPainRelief = ms("abdominalPainRelief");

  const heartburnFreq  = get("heartburnFrequency__2") || get("heartburnFrequency");
  const heartburnAfter = get("heartburnAfterEating");
  const heartburnTime  = get("heartburnTime");
  const heartburnSev   = get("heartburnSeverity");
  const heartburnTrig  = ms("heartburnTriggers");
  const heartburnAssoc = ms("heartburnAssociatedSymptoms");

  const nauseaFreq   = get("nauseaFrequency");
  const vomiting     = get("vomitingFrequency");
  const nauseaTrig   = ms("nauseaTriggers");
  const nauseaTime   = get("nauseaTime");
  const nauseaSev    = get("nauseaSeverity");
  const nauseaDur    = get("nauseaDuration");
  const nauseaAssoc  = ms("nauseaAssociatedSymptoms");
  const nauseaRelief = ms("nauseaRelief");

  const diarrheaFreq  = get("diarrheaFrequency");
  const bloodStoolDi  = get("diarrheaBlood");
  const diarrheaCons  = get("diarrheaConsistency");
  const diarrheaDur   = get("diarrheaDuration");
  const diarrheaTrig  = ms("diarrheaTriggers");
  const diarrheaAssoc = ms("diarrheaAssociatedSymptoms");

  const constipFreq  = get("constipationFrequency");
  const constipStrain= get("constipationStrain");
  const stoolCons    = get("constipationConsistency") || get("diarrheaConsistency");
  const constipDur   = get("constipationDuration");
  const constipTrig  = ms("constipationTriggers");
  const constipAssoc = ms("constipationAssociatedSymptoms");
  const bowelFreq    = get("constipationBowelFrequency");

  const bloatingFreq = get("bloatingFrequency");
  const bloatingTrig = ms("bloatingTriggers");
  const bloatingTime = get("bloatingTime");

  const appetiteChange = get("appetiteChange");
  const appetiteDur    = get("appetiteDuration");

  const bloodInStool   = get("bloodInStool");
  const bloodColor     = get("bloodStoolColor");
  const bloodFreq      = get("bloodStoolFrequency");

  const indigestionFreq = get("indigestionFrequency");
  const indigestionTrig = ms("indigestionTriggers");

  const swallowingDiff = get("swallowingDifficulty");
  const swallowingType = get("swallowingType");
  const swallowingFreq = get("swallowingFrequency");

  const hasPain = isActiveFreq(abdPainFreq);
  const hasNausea = isActiveFreq(nauseaFreq);
  const hasVomiting = yes(vomiting);
  const hasDiarrhea = isActiveFreq(diarrheaFreq);
  const hasConstipation = isActiveFreq(constipFreq);
  const hasHeartburn = isActiveFreq(heartburnFreq);
  const hasBloating = isActiveFreq(bloatingFreq);
  const hasIndigestion = isActiveFreq(indigestionFreq);
  const hasBlood =
    yes(bloodInStool) || yes(bloodStoolDi) ||
    (bloodColor && String(bloodColor).trim() !== "");
  const hasSwallow = yes(swallowingDiff);
  const appetiteDown = appetiteChange === "Decreased";
  const appetiteUp = appetiteChange === "Increased";

  // ---------- Findings (what is present) ----------
  if (hasPain) {
    pushUnique(result.findings, "Abdominal pain: " + abdPainFreq + ".");
    if (abdPainType) pushUnique(result.findings, "Pain type: " + abdPainType + ".");
    if (abdPainLoc) pushUnique(result.findings, "Pain location: " + abdPainLoc + ".");
    if (abdPainTrig) pushUnique(result.findings, "Pain trigger: " + abdPainTrig + ".");
    if (abdPainDur) pushUnique(result.findings, "Pain duration: " + abdPainDur + ".");
    if (abdPainSev) pushUnique(result.findings, "Pain severity: " + abdPainSev + ".");
    if (abdPainAssoc.length && !hasOpt("abdominalPainAssociatedSymptoms", "None")) {
      pushUnique(result.findings, "Pain-associated symptoms: " + joinList(abdPainAssoc) + ".");
    }
    if (abdPainRelief.length) {
      pushUnique(result.findings, "Pain relief reported: " + joinList(abdPainRelief) + ".");
    }
    result.status = _raiseStatus(result.status,
      (abdPainSev === "Severe" || abdPainFreq === "Constantly") ? "abnormal" : "borderline");
  }

  if (hasHeartburn) {
    pushUnique(result.findings, "Heartburn: " + heartburnFreq + ".");
    if (yes(heartburnAfter)) pushUnique(result.findings, "Heartburn after eating: Yes.");
    if (heartburnTime) pushUnique(result.findings, "Heartburn timing: " + heartburnTime + ".");
    if (heartburnSev) pushUnique(result.findings, "Heartburn severity: " + heartburnSev + ".");
    if (heartburnTrig.length && !hasOpt("heartburnTriggers", "No Triggers")) {
      pushUnique(result.findings, "Heartburn triggers: " + joinList(heartburnTrig) + ".");
    }
    if (heartburnAssoc.length) {
      pushUnique(result.findings, "Heartburn-associated symptoms: " + joinList(heartburnAssoc) + ".");
    }
    result.status = _raiseStatus(result.status,
      (heartburnFreq === "Frequently" || heartburnFreq === "Constantly" || heartburnSev === "Severe")
        ? "abnormal" : "borderline");
  }

  if (hasNausea) {
    pushUnique(result.findings, "Nausea: " + nauseaFreq + ".");
    if (nauseaTrig.length && !hasOpt("nauseaTriggers", "No specific triggers")) {
      pushUnique(result.findings, "Nausea triggers: " + joinList(nauseaTrig) + ".");
    }
    if (nauseaTime) pushUnique(result.findings, "Nausea timing: " + nauseaTime + ".");
    if (nauseaSev) pushUnique(result.findings, "Nausea severity: " + nauseaSev + ".");
    if (nauseaDur) pushUnique(result.findings, "Nausea duration: " + nauseaDur + ".");
    if (nauseaAssoc.length && !hasOpt("nauseaAssociatedSymptoms", "None")) {
      pushUnique(result.findings, "Nausea-associated symptoms: " + joinList(nauseaAssoc) + ".");
    }
    if (nauseaRelief.length) {
      pushUnique(result.findings, "Nausea relief reported: " + joinList(nauseaRelief) + ".");
    }
    result.status = _raiseStatus(result.status,
      (nauseaFreq === "Frequently" || nauseaFreq === "Constantly" || nauseaSev === "Severe")
        ? "abnormal" : "borderline");
  }

  if (hasVomiting) {
    pushUnique(result.findings, "Recent vomiting reported: Yes.");
    result.status = _raiseStatus(result.status, "borderline");
  } else if (String(vomiting || "").trim().toLowerCase() === "no") {
    pushUnique(result.findings, "Recent vomiting: No.");
  }

  if (hasDiarrhea) {
    pushUnique(result.findings, "Diarrhea: " + diarrheaFreq + ".");
    if (diarrheaCons) pushUnique(result.findings, "Diarrhea stool consistency: " + diarrheaCons + ".");
    if (diarrheaDur) pushUnique(result.findings, "Diarrhea duration: " + diarrheaDur + ".");
    if (diarrheaTrig.length && !hasOpt("diarrheaTriggers", "No Triggers")) {
      pushUnique(result.findings, "Diarrhea triggers: " + joinList(diarrheaTrig) + ".");
    }
    if (diarrheaAssoc.length && !hasOpt("diarrheaAssociatedSymptoms", "None")) {
      pushUnique(result.findings, "Diarrhea-associated symptoms: " + joinList(diarrheaAssoc) + ".");
    }
    if (yes(bloodStoolDi)) {
      pushUnique(result.findings, "Blood with diarrhea reported.");
      result.status = "abnormal";
    } else {
      result.status = _raiseStatus(result.status,
        (diarrheaFreq === "Frequently" || diarrheaFreq === "Constantly") ? "abnormal" : "borderline");
    }
  }

  if (hasConstipation) {
    pushUnique(result.findings, "Constipation: " + constipFreq + ".");
    if (yes(constipStrain)) pushUnique(result.findings, "Straining with bowel movements: Yes.");
    if (stoolCons && stoolCons !== "Normal") {
      pushUnique(result.findings, "Constipation stool consistency: " + stoolCons + ".");
    }
    if (constipDur) pushUnique(result.findings, "Constipation duration: " + constipDur + ".");
    if (bowelFreq) pushUnique(result.findings, "Bowel frequency: " + bowelFreq + ".");
    if (constipTrig.length && !hasOpt("constipationTriggers", "No Triggers")) {
      pushUnique(result.findings, "Constipation triggers: " + joinList(constipTrig) + ".");
    }
    if (constipAssoc.length && !hasOpt("constipationAssociatedSymptoms", "None")) {
      pushUnique(result.findings, "Constipation-associated symptoms: " + joinList(constipAssoc) + ".");
    }
    result.status = _raiseStatus(result.status,
      (constipFreq === "Frequently" || constipFreq === "Constantly" ||
       bowelFreq === "Once a Week or Less") ? "abnormal" : "borderline");
  } else if (stoolCons && (stoolCons === "Hard" || stoolCons === "Watery" || stoolCons === "Loose" || stoolCons === "Mucous-like")) {
    pushUnique(result.findings, "Stool consistency: " + stoolCons + ".");
  }

  if (hasBloating) {
    pushUnique(result.findings, "Bloating: " + bloatingFreq + ".");
    if (bloatingTrig.length) pushUnique(result.findings, "Bloating triggers: " + joinList(bloatingTrig) + ".");
    if (bloatingTime) pushUnique(result.findings, "Bloating timing: " + bloatingTime + ".");
    result.status = _raiseStatus(result.status, "borderline");
  }

  if (appetiteDown || appetiteUp) {
    pushUnique(result.findings, "Appetite change: " + appetiteChange + ".");
    if (appetiteDur) pushUnique(result.findings, "Appetite duration: " + appetiteDur + ".");
    result.status = _raiseStatus(result.status,
      (appetiteDown && (appetiteDur === "Ongoing" || appetiteDur === "Several weeks"))
        ? "abnormal" : "borderline");
  }

  if (hasIndigestion) {
    pushUnique(result.findings, "Indigestion: " + indigestionFreq + ".");
    if (indigestionTrig.length) {
      pushUnique(result.findings, "Indigestion triggers: " + joinList(indigestionTrig) + ".");
    }
    result.status = _raiseStatus(result.status, "borderline");
  }

  if (hasBlood) {
    pushUnique(result.findings, "Blood in stool reported.");
    if (bloodColor) pushUnique(result.findings, "Blood colour: " + bloodColor + ".");
    if (bloodFreq) pushUnique(result.findings, "Blood in stool frequency: " + bloodFreq + ".");
    result.status = "abnormal";
  }

  if (hasSwallow) {
    pushUnique(result.findings, "Difficulty swallowing reported.");
    if (swallowingType) pushUnique(result.findings, "Swallowing difficulty type: " + swallowingType + ".");
    if (swallowingFreq) pushUnique(result.findings, "Swallowing symptom frequency: " + swallowingFreq + ".");
    result.status = _raiseStatus(result.status, "abnormal");
  }

  // ---------- Mechanism flags (only from existing answers) ----------
  const giRefluxPattern =
    hasHeartburn ||
    yes(heartburnAfter) ||
    hasOpt("heartburnAssociatedSymptoms", "Acid Taste in Mouth") ||
    hasIndigestion ||
    hasOpt("abdominalPainLocation", "Upper abdomen") ||
    hasOpt("nauseaTriggers", "After eating") ||
    hasOpt("abdominalPainTriggers", "After eating") ||
    hasOpt("bloatingTriggers", "After Eating") ||
    hasOpt("indigestionTriggers", "Spicy Foods") ||
    hasOpt("indigestionTriggers", "Fatty Foods") ||
    hasOpt("heartburnTriggers", "Spicy Foods") ||
    hasOpt("heartburnTriggers", "Fatty Foods");

  const inflammatoryInfectiousPattern =
    hasDiarrhea ||
    diarrheaCons === "Mucous-like" ||
    hasOpt("diarrheaAssociatedSymptoms", "Fever") ||
    hasOpt("diarrheaAssociatedSymptoms", "Abdominal Cramps") ||
    hasOpt("abdominalPainAssociatedSymptoms", "Diarrhea") ||
    hasOpt("nauseaAssociatedSymptoms", "Diarrhea") ||
    yes(bloodStoolDi) ||
    (hasVomiting && hasDiarrhea);

  const obstructionPattern =
    (hasConstipation && (yes(constipStrain) ||
      stoolCons === "Hard" || stoolCons === "Lumpy" || stoolCons === "Pebble-like" ||
      bowelFreq === "Twice a week" || bowelFreq === "Once a Week or Less")) ||
    (hasSwallow && (swallowingType === "Solids" || swallowingType === "Both")) ||
    (hasVomiting && hasConstipation) ||
    (hasVomiting && hasBloating && hasConstipation) ||
    (hasPain && hasOpt("abdominalPainRelief", "No relief") && abdPainSev === "Severe");

  const medicationToxicPattern =
    hasOpt("nauseaTriggers", "Medications") ||
    hasOpt("diarrheaTriggers", "Medications") ||
    hasOpt("constipationTriggers", "Medications");

  const neurologicalPattern =
    hasOpt("nauseaTriggers", "Motion Sickness or Travel") ||
    hasOpt("nauseaAssociatedSymptoms", "Headache") ||
    hasOpt("nauseaAssociatedSymptoms", "Dizziness") ||
    (hasNausea && nauseaTime === "Morning" && !giRefluxPattern && !inflammatoryInfectiousPattern);

  const metabolicSystemicPattern =
    (appetiteDown && (appetiteDur === "Ongoing" || appetiteDur === "Several weeks" || appetiteDur === "A week")) ||
    (hasVomiting && appetiteDown) ||
    (hasVomiting && hasOpt("constipationAssociatedSymptoms", "Loss of Appetite"));

  const stressFunctionalPattern =
    hasOpt("abdominalPainTriggers", "Stress") ||
    hasOpt("diarrheaTriggers", "Stress") ||
    hasOpt("constipationTriggers", "Stress") ||
    hasOpt("bloatingTriggers", "Stress");

  // ---------- Interpretations ----------
  if (hasVomiting) {
    pushUnique(result.interpretations,
      "Vomiting is present; the questionnaire pattern is used to weigh plausible mechanisms rather than treating vomiting as an isolated consequence.");

    const supported = [];
    if (giRefluxPattern) supported.push("gastrointestinal / reflux–dyspepsia pathway");
    if (inflammatoryInfectiousPattern) supported.push("inflammatory / infectious bowel pattern");
    if (obstructionPattern) supported.push("obstruction-type / delayed transit pattern");
    if (medicationToxicPattern) supported.push("medication-associated pathway");
    if (neurologicalPattern) supported.push("neurological / vestibular–migraine-adjacent pathway");
    if (metabolicSystemicPattern) supported.push("metabolic / systemic appetite-loss pathway");
    if (stressFunctionalPattern) supported.push("stress-linked functional gut pathway");

    if (supported.length) {
      pushUnique(result.interpretations,
        "Findings that matter together for vomiting: supported mechanism direction(s) from current answers — " +
        supported.join("; ") + ".");
    } else {
      pushUnique(result.interpretations,
        "Vomiting is reported, but accompanying GI answers are limited, so a single mechanism cannot be prioritised yet.");
    }

    if (giRefluxPattern && hasVomiting) {
      const bits = [];
      if (hasHeartburn || yes(heartburnAfter)) bits.push("heartburn / post-meal reflux signals");
      if (hasOpt("nauseaTriggers", "After eating") || hasOpt("abdominalPainTriggers", "After eating")) {
        bits.push("symptoms triggered after eating");
      }
      if (hasOpt("abdominalPainLocation", "Upper abdomen")) bits.push("upper-abdominal pain location");
      if (hasIndigestion) bits.push("indigestion");
      pushUnique(result.interpretations,
        "Gastrointestinal explanation for vomiting is supported by " + bits.join(", ") +
        ". This pattern fits gastric irritation, reflux-related dyspepsia, or meal-triggered upper-gut intolerance better than an isolated systemic effect.");
    }

    if (inflammatoryInfectiousPattern && hasVomiting) {
      const bits = [];
      if (hasDiarrhea) bits.push("diarrhea (" + diarrheaFreq + ")");
      if (diarrheaCons === "Mucous-like") bits.push("mucous-like stool");
      if (hasOpt("diarrheaAssociatedSymptoms", "Fever")) bits.push("fever with diarrhea");
      if (hasOpt("diarrheaAssociatedSymptoms", "Abdominal Cramps")) bits.push("abdominal cramps with diarrhea");
      if (yes(bloodStoolDi) || yes(bloodInStool)) bits.push("blood in stool");
      pushUnique(result.interpretations,
        "Inflammatory / infectious explanation is supported by " + bits.join(", ") +
        ". Vomiting with this bowel pattern often reflects luminal inflammation, infection, or inflammatory diarrhea rather than reflux alone.");
    }

    if (obstructionPattern && hasVomiting) {
      const bits = [];
      if (hasConstipation) bits.push("constipation (" + constipFreq + ")");
      if (yes(constipStrain)) bits.push("straining");
      if (stoolCons === "Hard" || stoolCons === "Lumpy" || stoolCons === "Pebble-like") {
        bits.push("hard / incomplete stool consistency (" + stoolCons + ")");
      }
      if (bowelFreq === "Twice a week" || bowelFreq === "Once a Week or Less") {
        bits.push("infrequent bowel frequency (" + bowelFreq + ")");
      }
      if (hasSwallow && (swallowingType === "Solids" || swallowingType === "Both")) {
        bits.push("swallowing difficulty with solids");
      }
      if (hasBloating) bits.push("bloating");
      pushUnique(result.interpretations,
        "Obstruction-type / transit-delay explanation is supported by " + bits.join(", ") +
        ". Vomiting in this setting can reflect impaired forward transit or mechanical resistance rather than simple gastritis.");
    }

    if (medicationToxicPattern && hasVomiting) {
      pushUnique(result.interpretations,
        "Medication-associated explanation is supported because medications were selected as a trigger for nausea and/or bowel change. Vomiting may be drug-related or toxic-effect related until timing with doses is clarified.");
    }

    if (neurologicalPattern && hasVomiting) {
      const bits = [];
      if (hasOpt("nauseaTriggers", "Motion Sickness or Travel")) bits.push("motion / travel trigger");
      if (hasOpt("nauseaAssociatedSymptoms", "Headache")) bits.push("headache with nausea");
      if (hasOpt("nauseaAssociatedSymptoms", "Dizziness")) bits.push("dizziness with nausea");
      if (nauseaTime === "Morning") bits.push("morning-predominant nausea");
      pushUnique(result.interpretations,
        "Neurological explanation is supported by " + bits.join(", ") +
        ". This leans toward vestibular, migraine-spectrum, or centrally triggered nausea/vomiting when primary gut inflammatory signals are weaker.");
    }

    if (metabolicSystemicPattern && hasVomiting) {
      pushUnique(result.interpretations,
        "Metabolic / systemic contribution is supported by decreased appetite" +
        (appetiteDur ? (" (" + appetiteDur + ")") : "") +
        " alongside vomiting. This keeps metabolic strain, systemic illness, or broader inflammatory load in the differential when local gut triggers are incomplete.");
    }

    if (stressFunctionalPattern && hasVomiting) {
      pushUnique(result.interpretations,
        "Stress-linked functional gut contribution is supported by stress selected as a symptom trigger. This remains an adjunct explanation and does not exclude organic mechanisms when inflammatory, obstructive, or reflux signals are also present.");
    }

    // Alternatives that remain under-supported
    const weak = [];
    if (!giRefluxPattern) weak.push("isolated reflux/dyspepsia");
    if (!inflammatoryInfectiousPattern) weak.push("clear inflammatory/infectious bowel disease pattern");
    if (!obstructionPattern) weak.push("obstruction-type transit failure");
    if (!medicationToxicPattern) weak.push("medication-triggered mechanism");
    if (!neurologicalPattern) weak.push("neurological / vestibular mechanism");
    if (!metabolicSystemicPattern) weak.push("appetite-loss metabolic/systemic pattern");
    if (weak.length && supported.length) {
      pushUnique(result.interpretations,
        "Alternative explanations with weaker support from current answers: " + weak.join("; ") + ".");
    }

    // Consequence — secondary, not the main interpretation
    pushUnique(result.interpretations,
      "Persistent vomiting can disturb fluid and electrolyte balance; treat this as a consequence to monitor, not as the primary explanation for why vomiting is occurring.");
  } else {
    // Non-vomiting GI interpretation depth when other patterns exist
    if (hasHeartburn && yes(heartburnAfter)) {
      pushUnique(result.interpretations,
        "Post-meal heartburn pattern is consistent with reflux-related (GERD-spectrum) upper gastrointestinal irritation.");
    }
    if (inflammatoryInfectiousPattern && hasDiarrhea) {
      pushUnique(result.interpretations,
        "Diarrhea with inflammatory-leaning features (cramps, fever, mucus, and/or blood when reported) supports an inflammatory or infectious bowel process.");
    }
    if (hasBlood) {
      pushUnique(result.interpretations,
        "Blood in stool requires prompt evaluation to distinguish lower-gut sources from possible upper-gut bleeding based on colour and associated symptoms.");
    }
    if (hasSwallow) {
      pushUnique(result.interpretations,
        "Swallowing difficulty raises concern for mechanical or motility impairment of the esophagus/oropharynx and should not be attributed to simple dyspepsia alone.");
    }
  }

  if (hasPain && hasVomiting && hasOpt("abdominalPainAssociatedSymptoms", "Vomiting")) {
    pushUnique(result.interpretations,
      "Abdominal pain explicitly linked with vomiting strengthens a primary gastrointestinal generator for the emesis rather than an unrelated isolated nausea episode.");
  }

  // ---------- Next Steps / Suggested Tests ----------
  if (hasVomiting) {
    pushUnique(result.nextSteps,
      "Map vomiting against meals, medications, bowel pattern, headache/dizziness and fever over the next 24–48 hours because timing distinguishes gastrointestinal, inflammatory, medication-related and neurological mechanisms.");
    pushUnique(result.nextSteps,
      "Check hydration status (fluid intake, urine output, dizziness on standing) and electrolytes because ongoing vomiting can rapidly create fluid and electrolyte imbalance.");
    pushUnique(result.suggestedTests, "Basic metabolic panel (electrolytes, kidney function) — because vomiting threatens sodium/potassium and volume status.");
    pushUnique(result.suggestedTests, "Orthostatic pulse/blood pressure or clinical hydration assessment — because volume depletion may accompany persistent vomiting.");
  }

  if (giRefluxPattern && (hasVomiting || hasHeartburn || hasIndigestion)) {
    pushUnique(result.nextSteps,
      "Correlate reflux/dyspepsia triggers (spicy/fatty foods, lying flat, post-meal timing) with symptom peaks because a meal-linked pattern supports upper-gut irritation over obstructive or neurological vomiting.");
    if (heartburnFreq === "Frequently" || heartburnFreq === "Constantly" || heartburnSev === "Severe" || hasSwallow) {
      pushUnique(result.suggestedTests, "Upper endoscopy consideration — because frequent/severe reflux, indigestion, or dysphagia may need structural evaluation.");
    }
  }

  if (inflammatoryInfectiousPattern) {
    pushUnique(result.nextSteps,
      "Track stool frequency, consistency, mucus/blood and fever daily because progression of inflammatory diarrhea changes urgency and the need for stool testing.");
    pushUnique(result.suggestedTests, "Stool studies (culture / PCR / ova and parasites as clinically appropriate) — because diarrhea with inflammatory features can reflect infection.");
    if (diarrheaCons === "Mucous-like" || yes(bloodStoolDi) || yes(bloodInStool) ||
        hasOpt("diarrheaAssociatedSymptoms", "Fever")) {
      pushUnique(result.suggestedTests, "Inflammatory stool markers (e.g. fecal calprotectin) when available — because mucus, blood or fever raises inflammatory bowel concern.");
    }
  }

  if (obstructionPattern) {
    pushUnique(result.nextSteps,
      "Document stool frequency, straining, bloating and any progressive abdominal distension because worsening transit-delay features raise obstruction-type concern.");
    if (hasVomiting && hasConstipation) {
      pushUnique(result.nextSteps,
        "Seek urgent clinical review if vomiting continues with marked constipation, severe pain, or inability to pass stool/gas because this pattern can reflect bowel obstruction.");
      result.status = _raiseStatus(result.status, "abnormal");
    }
    if (hasSwallow) {
      pushUnique(result.suggestedTests, "Swallow evaluation (barium swallow or upper endoscopy) — because solid-food dysphagia can indicate mechanical obstruction.");
    }
  }

  if (medicationToxicPattern) {
    pushUnique(result.nextSteps,
      "List current medications/dose timing against nausea and vomiting episodes because a reproducible post-dose pattern supports a medication-related mechanism.");
    pushUnique(result.suggestedTests, "Medication review with clinician/pharmacist — because drug-related nausea/vomiting is reversible when the culprit is identified.");
  }

  if (neurologicalPattern) {
    pushUnique(result.nextSteps,
      "Note headache, dizziness, photophobia/phonophobia and motion sensitivity with each nausea episode because neurological patterning redirects evaluation away from primary gut infection.");
    if (hasOpt("nauseaAssociatedSymptoms", "Headache") || hasOpt("nauseaAssociatedSymptoms", "Dizziness")) {
      pushUnique(result.suggestedTests, "Neurological / vestibular clinical assessment if headache or dizziness dominates with vomiting — because central or vestibular drivers remain plausible.");
    }
  }

  if (metabolicSystemicPattern) {
    pushUnique(result.nextSteps,
      "Track weight trend, appetite and energy alongside vomiting because progressive appetite loss with emesis can signal metabolic or systemic illness beyond local gastritis.");
    pushUnique(result.suggestedTests, "Glucose / metabolic panel — because systemic metabolic disturbance can present with nausea, vomiting and appetite change.");
  }

  if (hasBlood) {
    pushUnique(result.nextSteps,
      "Seek medical evaluation for gastrointestinal bleeding without delay because stool blood can indicate mucosal injury, inflammation or higher-risk sources.");
    if (bloodColor === "Dark Red" || bloodColor === "Black or Tarry") {
      pushUnique(result.suggestedTests, "Urgent upper endoscopy consideration — because dark/tarry stool suggests possible upper GI bleeding.");
    } else if (bloodColor === "Bright Red") {
      pushUnique(result.suggestedTests, "Colonoscopy / lower GI evaluation — because bright red blood more often reflects a lower GI source.");
    } else {
      pushUnique(result.suggestedTests, "GI bleeding evaluation (upper and/or lower endoscopy as guided clinically) — because stool blood requires source localisation.");
    }
    result.status = "abnormal";
  }

  if (hasConstipation && !hasVomiting) {
    pushUnique(result.nextSteps,
      "Increase fibre and fluid trial while tracking bowel frequency for several days because simple constipation often responds before imaging is required.");
    if (yes(constipStrain) || bowelFreq === "Once a Week or Less") {
      pushUnique(result.suggestedTests, "Review for constipation contributors (medications, low fibre, low activity) — because straining or very infrequent stools often have reversible drivers.");
    }
  }

  if (hasBloating && hasOpt("bloatingTriggers", "After Eating") && !hasVomiting) {
    pushUnique(result.nextSteps,
      "Trial a short food-symptom diary for meal-triggered bloating because post-prandial bloating can reflect intolerance, fermentation, or delayed gastric emptying patterns.");
  }

  // Local analytical synthesis for OSIRIS DIAGNOSIS (not a findings dump).
  {
    const localMechanisms = [];
    if (giRefluxPattern) localMechanisms.push("reflux/dyspeptic");
    if (inflammatoryInfectiousPattern) localMechanisms.push("infectious/inflammatory");
    if (obstructionPattern) localMechanisms.push("transit/obstructive");
    if (medicationToxicPattern) localMechanisms.push("medication-related");
    if (neurologicalPattern) localMechanisms.push("neurological/vestibular");
    if (metabolicSystemicPattern) localMechanisms.push("metabolic/systemic");
    if (stressFunctionalPattern) localMechanisms.push("functional/stress-related");
    if (localMechanisms.length &&
        (result.status === "borderline" || result.status === "abnormal")) {
      pushUnique(result.interpretations,
        "OSIRIS local GI conclusion: current answers favour " + localMechanisms.join(", ") +
        " mechanism(s). Evidence is the questionnaire pattern plus any correlated measurements already in the patient profile; uncertainty remains wherever competing pathways lack distinguishing tests.");
      if (result.suggestedTests && result.suggestedTests.length) {
        pushUnique(result.interpretations,
          "Proposed tests are hypothesis-linked: each is intended to confirm, refute or differentiate the mechanism(s) above rather than to screen GI generically.");
      }
    }
  }

  // Generic persistence step when symptoms active but no specific pathway tests yet
  if (result.status === "borderline" && !result.suggestedTests.length) {
    pushUnique(result.suggestedTests,
      "Basic metabolic panel and stool studies if symptoms persist — because ongoing GI symptom clusters need objective fluid/electrolyte and stool context.");
  }

  if (!result.findings.length) {
    result.missing.push("No gastrointestinal symptoms reported.");
  }

  _contributeCluster(["inflammatoryLoad", "detoxLoad"], result.status, result.findings.length);
  _applyMedImpact(result, "gastrointestinal", context && context.medicationImpact);
  return result;
}

/* ---------- PSYCHOLOGICAL EVALUATION ---------- */
function interpretPsychologicalEvaluation(context) {
  const result = {
    category: "psychological_evaluation",
    status: "normal",
    findings: [],
    interpretations: [],
    nextSteps: [],
    suggestedTests: [],
    medicationNotes: [],
    warnings: [],
    missing: []
  };

  const get  = (typeof getRadioValue === "function") ? getRadioValue : () => "";
  const getN = (typeof getRadioValueAll === "function") ? getRadioValueAll : (n) => { const v = get(n); return v ? [v] : []; };
  const ms   = (typeof getMultiSelectOptions === "function") ? getMultiSelectOptions : () => [];

  // iter-24: cumulative-weight model so the global summary actually
  // changes when multiple coexisting findings are present.
  let weight = 0;
  const bump = (w, raiseTo) => {
    weight += w;
    if (raiseTo) result.status = _raiseStatus(result.status, raiseTo);
    if (weight >= 6) result.status = _raiseStatus(result.status, "abnormal");
    else if (weight >= 3) result.status = _raiseStatus(result.status, "borderline");
  };

  // -------- Multi-select symptom lists --------
  const depList     = ms('depressionSymptoms');
  const anxList     = ms('anxietySymptoms');
  const stressSym   = ms('stressSymptoms');
  const stressEmo   = ms('stressEmotions');
  const stressTrig  = ms('stressTriggers');
  const moodSyms    = ms('moodSymptoms');
  const substances  = ms('substanceType');

  if (depList.length) {
    result.findings.push(`Depression symptoms (${depList.length}): ${depList.join(', ')}.`);
    bump(depList.length);
    if (depList.some(s => /hopeless|worthless/i.test(s))) {
      result.findings.push("Hopelessness / worthlessness reported.");
      bump(3, "borderline");
    }
    if (depList.length >= 3) {
      result.interpretations.push("Multiple coexisting depressive symptoms — consistent with a depressive-spectrum cluster.");
      result.nextSteps.push("Apply PHQ-9 depression screening and a clinical mental-health review.");
    }
  }
  if (anxList.length) {
    result.findings.push(`Anxiety symptoms (${anxList.length}): ${anxList.join(', ')}.`);
    bump(anxList.length);
    if (anxList.some(s => /panic/i.test(s))) {
      result.findings.push("Panic attacks reported.");
      bump(4, "abnormal");
      result.interpretations.push("Panic-attack pattern detected — panic-spectrum evaluation indicated.");
      result.nextSteps.push("Apply GAD-7 and panic-disorder screening; clinical review within 2 weeks.");
    }
    if (anxList.some(s => /persistent worry/i.test(s))) bump(2);
    if (anxList.length >= 3) {
      result.interpretations.push("Multiple coexisting anxiety symptoms — consistent with an anxiety-spectrum cluster.");
    }
  }
  if (stressSym.length || stressEmo.length || stressTrig.length) {
    if (stressSym.length)  result.findings.push(`Stress symptoms (${stressSym.length}): ${stressSym.join(', ')}.`);
    if (stressEmo.length)  result.findings.push(`Stress emotions (${stressEmo.length}): ${stressEmo.join(', ')}.`);
    if (stressTrig.length) result.findings.push(`Stress triggers (${stressTrig.length}): ${stressTrig.join(', ')}.`);
    bump(Math.min(stressSym.length + stressEmo.length + stressTrig.length, 4));
  }
  if (moodSyms.length) {
    result.findings.push(`Mood symptoms (${moodSyms.length}): ${moodSyms.join(', ')}.`);
    if (moodSyms.some(s => /self.?harm|suicid/i.test(s))) {
      result.findings.push("SELF-HARM / SUICIDE THOUGHTS REPORTED.");
      result.status = "abnormal"; weight += 20;
      result.interpretations.push("Crisis flag — immediate mental-health support indicated.");
      result.nextSteps.push("Contact mental-health crisis support immediately (988 in the US, Samaritans 116 123 in the UK).");
    } else {
      bump(moodSyms.length);
    }
  }
  if (substances.length) {
    result.findings.push(`Substance use reported (${substances.length}): ${substances.join(', ')}.`);
    bump(1);
    const hiRisk = ['Opioids', 'Stimulants (e.g., cocaine, meth)', 'Prescription drugs (non-prescribed)'];
    const hiHits = substances.filter(s => hiRisk.indexOf(s) !== -1);
    if (hiHits.length) {
      result.findings.push(`High-risk substance(s): ${hiHits.join(', ')}.`);
      bump(3, "borderline");
      result.nextSteps.push("Addiction-medicine referral or specialist substance-use review.");
    }
    if (substances.length >= 3) {
      result.findings.push(`Polysubstance use (${substances.length} categories).`);
      bump(3, "borderline");
      result.nextSteps.push("Comprehensive substance-use assessment covering all reported categories.");
    }
    const substFreqs = getN('substanceFrequency');
    if (substFreqs.some(f => /multiple times per day|many times per day/i.test(f))) {
      result.findings.push("Many-times-per-day substance use pattern.");
      bump(4, "abnormal");
    } else if (substFreqs.some(f => /^daily$/i.test(f))) {
      result.findings.push("Daily substance use pattern.");
      bump(2);
    }
    const substImpact = get('substanceImpact');
    if (substImpact === "Yes") {
      result.findings.push("Substance use is affecting daily life or relationships.");
      bump(3, "abnormal");
    }
  }

  // -------- Scales / single-value answers --------
  const mood          = get('generalMood');
  const stressFreq    = get('stressFrequency');
  const stressInt     = get('stressIntensity');
  const sleepHours    = get('sleepHours') || get('sleepDuration');
  const sleepQuality  = get('sleepQualityPsych') || get('sleepQuality');
  const fallAsleep    = get('fallAsleep') || get('fallingAsleepDifficulty');
  const wakeOften     = get('wakeOften') || get('wakingUpNight');

  if (mood && mood !== "Good" && mood !== "Happy" && mood !== "Neutral" && mood !== "") {
    result.findings.push(`General mood: ${mood}.`);
    if (/Sad|Anxious|Angry|Poor/i.test(mood)) bump(2);
  }
  if (stressFreq === "Frequently" || stressInt === "Severe" || stressInt === "Overwhelming" || stressInt === "High") {
    result.findings.push(`Stress pattern: frequency=${stressFreq || "-"}, intensity=${stressInt || "-"}.`);
    bump(3, "borderline");
  }
  if (sleepHours === "Less than 4 hours" || sleepHours === "4-6 hours" ||
      sleepHours === "Less than 5" || sleepHours === "5-6") {
    result.findings.push(`Short sleep duration: ${sleepHours}.`);
    bump(2);
  }
  if (sleepQuality === "Poor" || sleepQuality === "Very Poor") {
    result.findings.push("Poor sleep quality reported.");
    bump(2);
  }
  if (fallAsleep === "Often" || fallAsleep === "Difficult") {
    result.findings.push("Difficulty falling asleep (insomnia pattern).");
    bump(1);
  }
  if (wakeOften === "Yes") {
    result.findings.push("Frequent night-time awakenings.");
    bump(1);
  }

  // -------- Cognitive / social / occupational (existing Psychology fields) --------
  const shortTermMemory = get('shortTermMemoryIssues');
  const concentration   = get('concentrationDifficulty') || get('concentrationIssues');
  const cognitiveFog    = get('cognitiveFog');
  const moodSocialImpact = get('moodSocialImpact');
  const socialImpact    = get('socialImpact');
  const workImpact      = get('workImpact');
  const feelSupported   = get('feelSupported') || get('supportSystem');

  if (shortTermMemory === "Yes, frequently" || shortTermMemory === "Yes, occasionally") {
    result.findings.push("Short-term memory issues: " + shortTermMemory + ".");
    bump(shortTermMemory === "Yes, frequently" ? 2 : 1);
  }
  if (concentration === "Yes, frequently" || concentration === "Yes, occasionally") {
    result.findings.push("Concentration / focus difficulties: " + concentration + ".");
    bump(concentration === "Yes, frequently" ? 2 : 1);
  }
  if (cognitiveFog === "Yes, frequently" || cognitiveFog === "Yes, occasionally") {
    result.findings.push("Cognitive fog / brain fog: " + cognitiveFog + ".");
    bump(cognitiveFog === "Yes, frequently" ? 2 : 1);
  }
  if (/significantly/i.test(String(moodSocialImpact || "")) || socialImpact === "Significantly") {
    result.findings.push("Significant social / relationship impact from mood or symptoms.");
    bump(2, "borderline");
  } else if (/occasionally/i.test(String(moodSocialImpact || "")) || socialImpact === "Occasionally") {
    result.findings.push("Occasional social impact from mood or symptoms.");
    bump(1);
  }
  if (/significantly/i.test(String(workImpact || ""))) {
    result.findings.push("Significant work / school impact reported.");
    bump(2, "borderline");
  } else if (/occasionally/i.test(String(workImpact || ""))) {
    result.findings.push("Occasional work / school impact reported.");
    bump(1);
  }
  if (feelSupported === "Not supported" || feelSupported === "No") {
    result.findings.push("Limited social support reported.");
    bump(1);
  }

  // -------- Multi-domain cluster / pattern processing --------
  // Reuse the same domain model as the broader Psychology assessment:
  // individual findings first, then pairwise + multi-domain integration
  // so interpretation and Next Steps reflect the COMBINED pattern.
  const domains = {
    depression: depList.length > 0 ||
                (mood && /Sad|Poor|Depressed/i.test(mood)),
    anxiety:    anxList.length > 0 || /Anxious/i.test(String(mood || "")),
    stress:     stressSym.length + stressEmo.length + stressTrig.length > 0 ||
                stressFreq === "Frequently" ||
                stressInt === "Severe" || stressInt === "Overwhelming" || stressInt === "High",
    mood:       moodSyms.length > 0 ||
                (mood && mood !== "Good" && mood !== "Happy" && mood !== "Neutral" && mood !== ""),
    substance:  substances.length > 0,
    sleep:      sleepQuality === "Poor" || sleepQuality === "Very Poor" ||
                sleepHours === "Less than 4 hours" || sleepHours === "Less than 5" ||
                sleepHours === "4-6 hours" || sleepHours === "5-6" ||
                fallAsleep === "Often" || fallAsleep === "Difficult" || wakeOften === "Yes",
    cognitive:  shortTermMemory === "Yes, frequently" || shortTermMemory === "Yes, occasionally" ||
                concentration === "Yes, frequently" || concentration === "Yes, occasionally" ||
                cognitiveFog === "Yes, frequently" || cognitiveFog === "Yes, occasionally",
    social:     /significantly/i.test(String(moodSocialImpact || "")) ||
                socialImpact === "Significantly" ||
                /significantly/i.test(String(workImpact || ""))
  };
  const active = Object.keys(domains).filter(k => domains[k]);
  const has = function (k) { return !!domains[k]; };

  // Pairwise / compound patterns — only when both domains are actually present.
  const pairNotes = [];
  if (has("stress") && has("anxiety")) {
    pairNotes.push("stress + anxiety");
    result.interpretations.push(
      "Stress and anxiety are co-active — a common reinforcing pattern that amplifies arousal, worry, and functional strain; evaluate together rather than as separate complaints."
    );
  }
  if (has("stress") && has("sleep")) {
    pairNotes.push("stress + sleep disturbance");
    result.interpretations.push(
      "Stress coexists with sleep disturbance — bidirectional strain (poor sleep worsens stress reactivity; stress sustains insomnia)."
    );
  }
  if (has("stress") && has("mood")) {
    pairNotes.push("stress + mood changes");
    result.interpretations.push(
      "Stress is interacting with mood changes — emotional dysregulation under load is part of the same psychological pattern."
    );
  }
  if (has("depression") && has("anxiety")) {
    pairNotes.push("depression + anxiety");
    result.interpretations.push(
      "Depressive and anxiety symptoms are simultaneously positive — mixed affective burden raises clinical weighting and should guide a combined mood/anxiety review."
    );
  }
  if (has("mood") && has("social")) {
    pairNotes.push("mood + social/occupational impairment");
    result.interpretations.push(
      "Mood symptoms are accompanied by social or occupational impairment — functional impact elevates clinical significance beyond symptom count alone."
    );
  }
  if (has("substance") && has("stress")) {
    pairNotes.push("substance use + stress");
    result.interpretations.push(
      "Substance use coexists with elevated stress — substance use may be coping-driven and also amplifying stress physiology; both arms need concurrent attention."
    );
  }
  if (has("substance") && (has("mood") || has("anxiety") || has("depression"))) {
    pairNotes.push("substance use + mood/anxiety");
    result.interpretations.push(
      "Substance use is co-occurring with mood and/or anxiety findings — dual-process pattern; neither substance use nor affective symptoms should be interpreted in isolation."
    );
  }
  if (has("substance") && substances.length >= 3 && active.length >= 2) {
    pairNotes.push("polysubstance use + psychological symptoms");
    result.interpretations.push(
      "Polysubstance use sits inside a broader multi-domain psychological pattern — addiction-focused steps alone are insufficient without addressing coexisting mental-health domains."
    );
  }
  if (has("cognitive") && active.length >= 2) {
    pairNotes.push("cognitive symptoms + other psychological domains");
    result.interpretations.push(
      "Cognitive symptoms (memory / concentration / fog) are present alongside other psychological domains — consider shared drivers (sleep, mood, stress, substance use) rather than isolated cognitive decline."
    );
  }
  if (has("anxiety") && has("sleep")) {
    pairNotes.push("anxiety + sleep disturbance");
    result.interpretations.push(
      "Anxiety and sleep disturbance are co-active — night-time arousal and daytime anxiety often form one loop; sleep-focused and anxiety-focused steps should run together."
    );
  }
  if (has("depression") && has("sleep")) {
    pairNotes.push("depression + sleep disturbance");
    result.interpretations.push(
      "Depressive symptoms and sleep disturbance are co-active — sleep disruption is a core amplifier of depressive burden and belongs in the same treatment plan."
    );
  }

  // Dominant / secondary pattern ranking from active domains.
  if (active.length >= 2) {
    const domainWeight = {
      depression: depList.length + (has("depression") ? 2 : 0),
      anxiety:    anxList.length + (has("anxiety") ? 2 : 0),
      stress:     stressSym.length + stressEmo.length + stressTrig.length +
                  (stressInt === "Severe" || stressInt === "Overwhelming" ? 3 : (has("stress") ? 1 : 0)),
      mood:       moodSyms.length + (has("mood") ? 1 : 0),
      substance:  substances.length * 2 + (has("substance") ? 1 : 0),
      sleep:      has("sleep") ? 2 : 0,
      cognitive:  has("cognitive") ? 2 : 0,
      social:     has("social") ? 2 : 0
    };
    const ranked = active.slice().sort(function (a, b) {
      return (domainWeight[b] || 0) - (domainWeight[a] || 0);
    });
    const dominant = ranked[0];
    const secondary = ranked.slice(1, 3);
    result.findings.push(
      "Psychology pattern cluster: " + active.join(" + ") +
      (pairNotes.length ? " (linked: " + pairNotes.join("; ") + ")" : "") + "."
    );
    result.interpretations.push(
      "Integrated Psychology pattern — dominant domain: " + dominant +
      (secondary.length ? "; secondary: " + secondary.join(", ") : "") +
      ". Overall status reflects interacting domains, not any single finding in isolation."
    );
    bump(active.length >= 3 ? 3 : 2, active.length >= 3 ? "abnormal" : "borderline");

    // Why status is concerning — only when elevated.
    if (result.status === "abnormal" || result.status === "borderline") {
      result.interpretations.push(
        "Overall Psychology status is " + result.status +
        " because multiple coexisting domains (" + active.join(", ") +
        ") raise combined clinical-risk weighting beyond what any isolated symptom would justify."
      );
    }
  } else if (active.length === 1) {
    result.interpretations.push(
      "Single-domain Psychology signal (" + active[0] +
      ") — monitor for emerging co-domains; current interpretation remains focused on this domain."
    );
  }

  // -------- Next Steps from the WHOLE active pattern --------
  // Preserve substance-use recommendations already pushed above; add
  // domain-relevant steps for every other active Psychology domain.
  if (has("stress")) {
    result.nextSteps.push(
      "Stress-focused review: structured stress assessment, coping skills, and short-term psychological support."
    );
  }
  if (has("anxiety")) {
    var _gadForStep = (typeof OSIRIS_psychologyScreenRecord === "function")
      ? OSIRIS_psychologyScreenRecord("gad7") : null;
    if (_gadForStep) {
      result.nextSteps.push(
        "Anxiety pathway: recorded GAD-7 " + _gadForStep.total + "/21 is available for clinical mental-health review; panic screen if panic symptoms are present."
      );
    } else {
      result.nextSteps.push(
        "Anxiety pathway: GAD-7 (and panic screen if panic symptoms present); clinical mental-health review."
      );
    }
  }
  if (has("depression") || (has("mood") && /Sad|Poor|Depressed/i.test(String(mood || "")))) {
    result.nextSteps.push(
      "Depression / mood pathway: complete or review PHQ-9 and arrange clinical mental-health follow-up."
    );
  }
  if (has("sleep")) {
    result.nextSteps.push(
      "Sleep pathway: sleep-hygiene plan, screen for insomnia pattern, and revisit mood/anxiety once sleep is addressed."
    );
  }
  if (has("cognitive")) {
    result.nextSteps.push(
      "Cognitive pathway: review sleep, mood, stress, and substance use as reversible contributors; consider thyroid / B12 if fog persists."
    );
  }
  if (has("social")) {
    result.nextSteps.push(
      "Functional impact: address social/occupational impairment in the care plan; consider workplace or support-network interventions."
    );
  }
  if (has("substance") && (has("stress") || has("mood") || has("anxiety") || has("depression") || has("sleep"))) {
    result.nextSteps.push(
      "Integrated dual-focus plan: substance-use support AND concurrent mental-health care for coexisting stress/mood/anxiety/sleep domains."
    );
  }
  if (active.length >= 3) {
    result.nextSteps.push(
      "Coordinated mental-health review covering the full multi-domain pattern (psychology + GP" +
      (has("substance") ? ", with substance-use specialist" : "") + ")."
    );
  }

  // Deduplicate next steps / interpretations while preserving order.
  function _uniqKeep(arr) {
    var seen = {};
    var out = [];
    (arr || []).forEach(function (s) {
      var k = String(s || "").trim().toLowerCase();
      if (!k || seen[k]) return;
      seen[k] = 1;
      out.push(s);
    });
    return out;
  }
  result.nextSteps = _uniqKeep(result.nextSteps);
  result.interpretations = _uniqKeep(result.interpretations);

  // Cluster boost for the existing OSIRIS cluster object (neurologicalLoad /
  // neuroendocrineStrain) so CLUSTER SUMMARY reflects Psychology pattern size.
  result._psychClusterBoost = {
    neurologicalLoad: Math.min(2 + active.length + (has("cognitive") ? 2 : 0) + (has("anxiety") ? 1 : 0), 10),
    neuroendocrineStrain: Math.min(2 + active.length + (has("stress") ? 2 : 0) + (has("sleep") ? 2 : 0) + (has("substance") ? 1 : 0), 10)
  };
  result._psychActiveDomains = active.slice();

  if (!result.findings.length) {
    result.missing.push("No psychological signals reported.");
  }

  // Recorded psychological assessments only — do not invent a test that was
  // not completed. PHQ-9 belongs in FINDINGS when Analyse actually stored it.
  try {
    var _psyProf = (typeof userProfile !== "undefined" && userProfile) ? userProfile : null;
    var _phq9rec = _psyProf && _psyProf.diagnostics && _psyProf.diagnostics.psychology
      && _psyProf.diagnostics.psychology.phq9;
    if (_phq9rec && _phq9rec.total != null &&
        !(Array.isArray(_phq9rec.missingQuestions) && _phq9rec.missingQuestions.length)) {
      var _phqSev = _phq9rec.severity ? String(_phq9rec.severity).replace(/_/g, " ") : "";
      var _phqLine = "PHQ-9 Depression Screening: " + _phq9rec.total + "/27" +
        (_phqSev ? " — " + _phqSev : "") + " (completed assessment).";
      if (_phq9rec.q9 != null) {
        _phqLine += " Question 9 score: " + _phq9rec.q9 + "/3.";
      }
      var _hasPhqFinding = result.findings.some(function (s) {
        return /\bphq-?\s*9\b/i.test(String(s || ""));
      });
      if (!_hasPhqFinding) result.findings.unshift(_phqLine);
    }
  } catch (ePhqFind) {}

  try {
    var _gad7rec = (typeof OSIRIS_psychologyScreenRecord === "function")
      ? OSIRIS_psychologyScreenRecord("gad7") : null;
    if (_gad7rec) {
      var _gadSev = _gad7rec.severity ? String(_gad7rec.severity).replace(/_/g, " ") : "";
      var _gadLine = "GAD-7 total " + _gad7rec.total + "/21" +
        (_gadSev ? " — " + _gadSev + " anxiety symptom burden" : "") +
        " (completed assessment).";
      var _hasGadFinding = result.findings.some(function (s) {
        return /\bgad-?\s*7\b/i.test(String(s || ""));
      });
      if (!_hasGadFinding) result.findings.unshift(_gadLine);
      if (_gad7rec.total >= 15) bump(2, "abnormal");
      else if (_gad7rec.total >= 10) bump(1, "borderline");
      if (_gad7rec.total >= 10 && result._psychClusterBoost &&
          (result._psychActiveDomains || []).indexOf("anxiety") === -1) {
        result._psychClusterBoost.neurologicalLoad = Math.min(
          10, (Number(result._psychClusterBoost.neurologicalLoad) || 0) + 1
        );
      }
      var _phqForPair = (typeof OSIRIS_psychologyScreenRecord === "function")
        ? OSIRIS_psychologyScreenRecord("phq9") : null;
      if (_phqForPair && _phqForPair.total >= 5 && _gad7rec.total >= 5) {
        result.interpretations.unshift(
          "PHQ-9 " + _phqForPair.total + "/27 (depressive symptom burden) and GAD-7 " +
          _gad7rec.total + "/21 (anxiety symptom burden) are both recorded. The scores are independent and may coexist; neither explains objective abnormalities."
        );
      } else if (_gad7rec.total >= 10) {
        result.interpretations.unshift(
          "GAD-7 " + _gad7rec.total + "/21 — " + (_gadSev || "elevated") +
          " anxiety symptom burden. This is a screening measurement and does not account for objective abnormalities."
        );
      } else if (_gad7rec.total >= 5) {
        result.interpretations.unshift(
          "GAD-7 " + _gad7rec.total + "/21 — mild anxiety symptom burden."
        );
      }
    }
  } catch (eGadFind) {}

  result._riskScore = weight;
  _contributeCluster(["neurologicalLoad","neuroendocrineStrain"], result.status, result.findings.length);
  _applyMedImpact(result, "psychological_evaluation", context && context.medicationImpact);
  return result;
}

/* ---------- PSYCHIATRIC EVALUATION ---------- */
function interpretPsychiatricEvaluation(context) {
  const result = {
    category: "psychiatric_evaluation",
    status: "normal",
    findings: [],
    interpretations: [],
    nextSteps: [],
    suggestedTests: [],
    medicationNotes: [],
    warnings: [],
    missing: []
  };

  const get = (typeof getRadioValue === "function") ? getRadioValue : () => "";

  const prolongedSadness = get('moodPersistence');
  const emotionControl   = get('emotionControl');
  const moodIntensity    = get('moodIntensity');
  const excessiveAnxiety = get('excessiveAnxiety');
  const anxietyFreq      = get('anxietyFrequency');
  const anxietyPhys      = get('anxietyPhysicalSymptoms');
  const anxietyAvoid     = get('anxietyTriggers');
  const traumaHistory    = get('traumaHistory');
  const flashbacks       = get('traumaFlashbacks');
  const traumaAvoidance  = get('traumaAvoidance');
  const traumaImpact     = get('traumaImpact');
  const unusualBeliefs   = get('distortedBeliefs');
  const unusualPercept   = get('unusualPerceptions');
  const impulseControl   = get('impulseControlDifficulty');
  const riskyBehavior    = get('riskyBehaviors');

  if (prolongedSadness === "Frequently" || prolongedSadness === "Persistent") {
    result.findings.push("Prolonged periods of sadness, anxiety, or irritability.");
    result.status = _raiseStatus(result.status, "borderline");
  }
  if (emotionControl === "Frequently") {
    result.findings.push("Difficulty controlling emotions.");
    result.status = _raiseStatus(result.status, "borderline");
  }
  if (moodIntensity === "High") {
    result.findings.push("High mood intensity reported.");
  }

  if (excessiveAnxiety === "Yes" || anxietyFreq === "Frequently") {
    result.findings.push("Excessive or frequent anxiety reported.");
    if (anxietyPhys === "Yes") result.findings.push("Accompanied by physical symptoms.");
    if (anxietyAvoid && anxietyAvoid !== "") result.findings.push("Avoidance behavior reported.");
    result.interpretations.push("Pattern consistent with clinically significant anxiety.");
    result.status = _raiseStatus(result.status, "borderline");
  }

  if (traumaHistory === "Yes") {
    result.findings.push("Trauma history reported.");
    if (/^Yes/i.test(String(flashbacks || "")) || traumaAvoidance === "Yes") {
      result.interpretations.push("Re-experiencing or avoidance patterns suggest trauma-related impact.");
      result.status = _raiseStatus(result.status, "borderline");
    }
    if (traumaImpact === "Severe" || traumaImpact === "Yes, significantly") {
      result.status = _raiseStatus(result.status, "abnormal");
    }
  }

  if (unusualBeliefs === "Yes" || unusualPercept === "Yes") {
    result.findings.push("Unusual beliefs or perceptions reported.");
    result.interpretations.push("Reality-testing changes suggest a psychotic-spectrum signal that requires structured psychiatric assessment (MSE, content vs. process of thought, insight, safety).");
    result.status = _raiseStatus(result.status, "abnormal");
    result.nextSteps.push("Structured psychiatric review within 2 weeks — including risk-of-harm assessment and review of any prescribed dopamine-active or steroid medications.");
  }

  if (impulseControl === "Frequently" || impulseControl === "Yes" || riskyBehavior === "Yes") {
    result.findings.push("Impulsive or risky behavior reported.");
    result.status = _raiseStatus(result.status, "borderline");
  }

  // Self-Harm — live Psychiatric questionnaire fields (not obsolete
  // selfHarmHistory / selfHarmFreq). One safety domain alongside the
  // other psychiatric axes; does not replace the broader assessment.
  const selfHarm = get('selfHarm') || get('selfHarmHistory');
  const selfHarmFreq = get('selfHarmFrequency') || get('selfHarmFreq');
  const suicidalThoughts = get('suicidalThoughts');
  const suicidalPlan = get('suicidalPlan');
  const selfHarmImpact = get('selfHarmImpact');
  const needSupportSelfHarm = get('needSupportForSelfHarm');

  if (selfHarm === "Yes") {
    result.findings.push(
      "History of self-harming behaviours reported" +
      (selfHarmFreq ? " (frequency: " + selfHarmFreq + ")" : "") + "."
    );
    result.status = _raiseStatus(result.status, "abnormal");
    result.interpretations.push(
      "Self-harm history is a safety-relevant psychiatric finding requiring structured risk assessment."
    );
    result.nextSteps.push("Mental-health safety assessment and support planning.");
  }
  if (/^Yes/i.test(String(suicidalThoughts || ""))) {
    result.findings.push(
      "CURRENT thoughts of self-harm or suicide reported (" + suicidalThoughts + ")."
    );
    result.status = _raiseStatus(result.status, "abnormal");
    result.interpretations.push(
      "Active suicidal ideation screen positive — urgent same-day mental-health assessment indicated."
    );
    result.nextSteps.unshift(
      "Urgent mental-health crisis assessment; if immediate danger, emergency services."
    );
    if (suicidalPlan === "Yes") {
      result.findings.push("Specific suicidal plan reported.");
      result.warnings.push("Specific plan reported — treat as psychiatric emergency.");
      result.nextSteps.unshift(
        "Emergency psychiatric evaluation / emergency department if plan and intent present."
      );
    }
  }
  if (selfHarmImpact) {
    result.findings.push("Self-harm impact on mental health: " + selfHarmImpact + ".");
  }
  if (needSupportSelfHarm === "Yes" || needSupportSelfHarm === "Not sure") {
    result.findings.push(
      "Additional support requested for self-harm urges: " + needSupportSelfHarm + "."
    );
    result.nextSteps.push(
      "Offer crisis resources and mental-health follow-up for self-harm management."
    );
  }

  // Concrete psychiatric cluster summary. Counts core axes (including
  // Self-Harm safety) and emits a clinical-grade summary.
  const _psyAxes = {
    moodAxis:    (prolongedSadness === "Frequently" || prolongedSadness === "Persistent" ||
                  emotionControl === "Frequently" || moodIntensity === "High" || moodIntensity === "Severe"),
    anxietyAxis: (excessiveAnxiety === "Yes" || anxietyFreq === "Frequently"),
    traumaAxis:  (traumaHistory === "Yes"),
    psychoticAxis: (unusualBeliefs === "Yes" || unusualPercept === "Yes"),
    impulseAxis: (impulseControl === "Frequently" || impulseControl === "Yes" || riskyBehavior === "Yes"),
    safetyAxis:  (selfHarm === "Yes" || /^Yes/i.test(String(suicidalThoughts || "")) ||
                  suicidalPlan === "Yes")
  };
  const _activePsy = Object.keys(_psyAxes).filter(k => _psyAxes[k]);
  if (_activePsy.length >= 2) {
    const _axisDesc = _activePsy.map(function (k) {
      return ({
        moodAxis:      "prolonged sadness / irritability with reduced emotional regulation",
        anxietyAxis:   "clinically significant anxiety",
        traumaAxis:    "trauma history" + (/^Yes/i.test(String(flashbacks || "")) || traumaAvoidance === "Yes" ? " with re-experiencing or avoidance" : ""),
        psychoticAxis: "unusual beliefs or perceptions (reality-testing changes)",
        impulseAxis:   "impulsive or risky behaviour",
        safetyAxis:    "self-harm / suicidal ideation safety signal"
      })[k];
    }).filter(Boolean);
    result.findings.push("Psychiatric symptom cluster detected: " + _axisDesc.join("; ") + ".");
    result.interpretations.push(
      "Multiple psychiatric axes are simultaneously positive (" + _activePsy.length + "/6). " +
      "This raises global psychological-risk weighting and should be integrated into the overall diagnostic summary rather than treated as isolated findings."
    );
    if (_psyAxes.psychoticAxis || _psyAxes.impulseAxis || _psyAxes.safetyAxis) {
      result.status = _raiseStatus(result.status, "abnormal");
      result.nextSteps.push("Concrete next steps: (1) mental-state examination including risk-of-harm screen, (2) review of all prescribed medications for psychotropic / steroid / dopaminergic effects, (3) baseline labs — TSH, calcium, vitamin B12, fasting glucose, urine drug screen if substance use was reported, (4) coordinated psychiatry + GP follow-up within 2 weeks.");
    } else {
      result.nextSteps.push("Concrete next steps: (1) PHQ-9 + GAD-7 screening, (2) sleep + alcohol intake review, (3) coordinated mental-health + GP follow-up within 4 weeks.");
    }
  }

  if (!result.findings.length) {
    result.missing.push("No psychiatric signals reported.");
  }

  _contributeCluster(["neurologicalLoad","neuroendocrineStrain"], result.status, result.findings.length);
  _applyMedImpact(result, "psychiatric_evaluation", context && context.medicationImpact);
  return result;
}

/* ---------- MUSCULOSKELETAL EVALUATION ---------- */
function interpretMusculoskeletalEvaluation(context) {
  const result = {
    category: "musculoskeletal_evaluation",
    status: "normal",
    findings: [],
    interpretations: [],
    nextSteps: [],
    suggestedTests: [],
    medicationNotes: [],
    warnings: [],
    missing: []
  };

  const get = (typeof getRadioValue === "function") ? getRadioValue : () => "";
  const getIn = (typeof getInputValue === "function") ? getInputValue : () => "";

  const hasJointPain     = get('jointPain');
  const jointPainScale   = parseInt(getIn('jointPainScale'));
  const jointPainDuration= get('jointPainDuration');
  const jointPainFreq    = get('jointPainFrequency');
  const jointSwelling    = get('jointSwellingStiffness');
  const hasStiffness     = get('stiffness');
  const stiffnessTime    = get('stiffnessTimeOfDay');
  const stiffnessDur     = parseInt(getIn('stiffnessDuration'));
  const hasSwelling      = get('swelling');
  const swellingSymptoms = get('additionalSwellingSymptoms');
  const swellingSeverity = parseInt(getIn('swellingSeverity'));
  const hasWeakness      = get('muscleWeakness');
  const weaknessFreq     = get('muscleWeaknessFrequency');
  const weaknessDuration = get('muscleWeaknessDuration');
  const weaknessSeverity = parseInt(getIn('muscleWeaknessSeverity'));

  if (hasJointPain === "Yes") {
    result.findings.push("Joint pain present.");
    if (!isNaN(jointPainScale)) {
      result.findings.push(`Pain intensity: ${jointPainScale}/10.`);
      if (jointPainScale >= 7) result.status = _raiseStatus(result.status, "abnormal");
      else if (jointPainScale >= 4) result.status = _raiseStatus(result.status, "borderline");
    }
    if (jointPainDuration) result.findings.push(`Duration: ${jointPainDuration}.`);
    if (jointPainFreq === "Frequently") result.status = _raiseStatus(result.status, "borderline");
    if (jointSwelling === "Yes") {
      result.findings.push("Joint swelling or stiffness reported.");
      result.interpretations.push("Swelling with joint pain can suggest inflammatory involvement.");
      result.suggestedTests.push("CRP, ESR, and rheumatology evaluation if persistent.");
      result.status = _raiseStatus(result.status, "borderline");
    }
  }

  if (hasStiffness === "Yes") {
    result.findings.push("Stiffness reported.");
    if (stiffnessTime === "Morning" && !isNaN(stiffnessDur) && stiffnessDur > 60) {
      result.interpretations.push("Prolonged morning stiffness (>60 min) suggests inflammatory pattern.");
      result.status = _raiseStatus(result.status, "abnormal");
    } else if (!isNaN(stiffnessDur) && stiffnessDur > 30) {
      result.status = _raiseStatus(result.status, "borderline");
    }
  }

  if (hasSwelling === "Yes") {
    result.findings.push("Swelling reported.");
    if (swellingSymptoms) result.findings.push(`Associated symptoms: ${swellingSymptoms}.`);
    if (!isNaN(swellingSeverity) && swellingSeverity >= 6) {
      result.status = _raiseStatus(result.status, "borderline");
    }
  }

  if (hasWeakness === "Yes") {
    result.findings.push("Muscle weakness reported.");
    if (weaknessFreq === "Frequently") result.status = _raiseStatus(result.status, "borderline");
    if (weaknessDuration) result.findings.push(`Duration: ${weaknessDuration}.`);
    if (!isNaN(weaknessSeverity) && weaknessSeverity >= 7) {
      result.interpretations.push("Severe weakness may warrant neuromuscular evaluation.");
      result.status = _raiseStatus(result.status, "abnormal");
    }
  }

  if (!result.findings.length) {
    result.missing.push("No musculoskeletal symptoms reported.");
  }

  _contributeCluster(["structuralStrain"], result.status, result.findings.length);
  _applyMedImpact(result, "musculoskeletal_evaluation", context && context.medicationImpact);
  return result;
}

/* ---------- HEMATOLOGY ---------- */
/* Combined Hematology ANALYSE reading.
 * Uses the ranges already used by the hematology analysers. Does not write
 * inputs, series points, or the canonical NLR. */
function OSIRIS_hematologyEsc(s) {
  return String(s == null ? "" : s)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function OSIRIS_hematologyReadInput(id) {
  if (typeof document === "undefined") return null;
  var el = document.getElementById(id);
  if (!el || el.value == null) return null;
  var raw = String(el.value).trim();
  if (!raw) return null;
  var n = parseFloat(raw);
  return { raw: raw, value: isFinite(n) ? n : null, invalid: !isFinite(n) };
}

function OSIRIS_hematologyFirstInput(ids) {
  var i, hit;
  for (i = 0; i < ids.length; i++) {
    hit = OSIRIS_hematologyReadInput(ids[i]);
    if (hit) return hit;
  }
  return null;
}

function OSIRIS_hematologyPatientContext() {
  var sex = "";
  var age = null;
  try {
    var pm = (typeof userProfile !== "undefined" && userProfile &&
      userProfile.patient_metrics) || null;
    if (pm) {
      sex = String(pm.sex || "").toLowerCase();
      if (isFinite(parseFloat(pm.age))) age = parseFloat(pm.age);
    }
  } catch (ePat) {}
  return { sex: sex, age: age };
}

function OSIRIS_hematologyPanelFromDom(source) {
  var baseline = source === "baseline";
  function pick(primary, secondary) {
    return OSIRIS_hematologyFirstInput(baseline ? secondary.concat(primary) : primary.concat(secondary));
  }
  return {
    patient: OSIRIS_hematologyPatientContext(),
    hemoglobin: pick(["hematologyHemoglobin"], ["baselineHemoglobin"]),
    hematocrit: pick(["hematologyHematocrit"], ["baselineHematocrit"]),
    rbc: OSIRIS_hematologyFirstInput(["baselineRedBloodCellCount"]),
    mcv: OSIRIS_hematologyFirstInput(["hematologyMeanCorpuscularVolume"]),
    mch: OSIRIS_hematologyFirstInput(["hematologyMeanCorpuscularHemoglobin"]),
    mchc: OSIRIS_hematologyFirstInput(["hematologyMeanCorpuscularHemoglobinConcentration"]),
    rdw: OSIRIS_hematologyFirstInput(["hematologyRedCellDistributionWidth"]),
    neutrophils: pick(["hematologyNeutrophils"], ["baselineNeutrophils"]),
    lymphocytes: pick(["hematologyLymphocytes"], ["baselineLymphocytes"]),
    eosinophils: pick(["hematologyEosinophils"], ["baselineEosinophils"]),
    monocytes: pick(["hematologyMonocytes"], ["baselineMonocytes"]),
    basophils: pick(["hematologyBasophils"], ["baselineBasophils"]),
    wbc: pick(
      ["inflammatoryMarkersWhiteBloodCellCount"],
      ["baselineWhiteBloodCellCount", "baselineTotalWhiteBloodCellCount"]
    ),
    platelets: pick(["clottingFactorsPlateletCount"], ["baselinePlateletCount"]),
    crp: pick(["inflammatoryMarkersCReactiveProtein"], ["baselineCReactiveProtein"]),
    hsCrp: OSIRIS_hematologyFirstInput(["inflammatoryMarkersHighSensitivityCReactiveProtein"]),
    esr: OSIRIS_hematologyFirstInput(["inflammatoryMarkersErythrocyteSedimentationRate"]),
    ferritin: pick(["inflammatoryMarkersFerritin"], ["baselineFerritin"]),
    pct: OSIRIS_hematologyFirstInput(["infectionMarkersProcalcitonin"]),
    b12: OSIRIS_hematologyFirstInput(["vitamin_b12"]),
    folate: OSIRIS_hematologyFirstInput(["folate_b9"]),
    mma: OSIRIS_hematologyFirstInput(["methylmalonic_acid"])
  };
}

function OSIRIS_assessHematologyPanel(panel) {
  panel = panel || {};
  var patient = panel.patient || {};
  var findings = [];
  var limitations = [];
  var lines = [];
  var status = "normal";
  var entered = 0;
  var differentialUnreliable = false;

  function raise(next) {
    if (next === "abnormal" || status === "abnormal") status = "abnormal";
    else if (next === "borderline" || status === "borderline") status = "borderline";
  }
  function num(key) {
    var slot = panel[key];
    if (slot == null || slot === "") return null;
    if (typeof slot === "number") return isFinite(slot) ? slot : null;
    if (slot.invalid) return null;
    var n = (slot.value != null) ? Number(slot.value) : NaN;
    return isFinite(n) ? n : null;
  }
  function present(key) {
    var slot = panel[key];
    return !!(slot && (slot.invalid || slot.raw || slot.value != null || typeof slot === "number"));
  }
  function fmt(n) {
    var r = Math.round(Number(n) * 100) / 100;
    return String(r);
  }
  function add(list, text) {
    if (!text) return;
    list.push(text);
  }
  function note(text, kind) {
    add(lines, text);
    if (kind === "limit") add(limitations, text);
    else add(findings, text);
  }

  var labels = {
    hemoglobin: "Hemoglobin", hematocrit: "Hematocrit", rbc: "RBC",
    mcv: "MCV", mch: "MCH", mchc: "MCHC", rdw: "RDW",
    neutrophils: "Neutrophils", lymphocytes: "Lymphocytes",
    eosinophils: "Eosinophils", monocytes: "Monocytes", basophils: "Basophils",
    wbc: "WBC", platelets: "Platelets", crp: "CRP", hsCrp: "hs-CRP",
    esr: "ESR", ferritin: "Ferritin", pct: "Procalcitonin",
    b12: "Vitamin B12", folate: "Folate", mma: "Methylmalonic acid"
  };
  Object.keys(labels).forEach(function (key) {
    if (!present(key)) return;
    entered++;
    var slot = panel[key];
    if (slot && slot.invalid) {
      raise("borderline");
      note(labels[key] + " (" + slot.raw + ") is not a usable number. The entered value was left unchanged.", "find");
    } else if (slot && slot.value != null && typeof slot.value !== "number" && !isFinite(Number(slot.value))) {
      raise("borderline");
      note(labels[key] + " (" + slot.value + ") is not a usable number. The entered value was left unchanged.", "find");
    }
  });

  function unitProblem(key, value) {
    if (value == null) return "";
    if (key === "hemoglobin" && value >= 30 && value <= 250) {
      return "Hemoglobin " + fmt(value) + " is in the range expected for g/L, while this field is read as g/dL. It was not converted.";
    }
    if (key === "hemoglobin" && (value < 3 || value > 25)) {
      return "Hemoglobin " + fmt(value) + " g/dL is outside a plausible g/dL result. It was not changed.";
    }
    if (key === "hematocrit" && value > 0 && value < 1) {
      return "Hematocrit " + fmt(value) + " looks like a fraction. This field is read as a percent, and the value was not converted.";
    }
    if (key === "hematocrit" && (value < 0 || value > 75)) {
      return "Hematocrit " + fmt(value) + "% is not a plausible percent. It was not changed.";
    }
    if (key === "rbc" && (value < 1 || value > 10)) {
      return "RBC " + fmt(value) + " is not plausible as ×10¹²/L. It was not rescaled.";
    }
    if (key === "wbc" && value >= 500) {
      return "WBC " + fmt(value) + " is not plausible as ×10⁹/L and may be an absolute count entered in the wrong unit. It was not rescaled.";
    }
    if (key === "platelets" && value >= 1000) {
      return "Platelets " + fmt(value) + " is not plausible as ×10⁹/L. An absolute count was not converted.";
    }
    if (key === "mcv" && (value < 40 || value > 160)) {
      return "MCV " + fmt(value) + " fL is not a plausible red-cell volume. It was not changed.";
    }
    if (key === "mch" && (value < 10 || value > 50)) {
      return "MCH " + fmt(value) + " pg is not plausible. It was not changed.";
    }
    if (key === "mchc" && (value < 20 || value > 45)) {
      return "MCHC " + fmt(value) + " g/dL is not plausible. It was not changed.";
    }
    if (key === "rdw" && (value < 5 || value > 40)) {
      return "RDW " + fmt(value) + "% is not plausible. It was not changed.";
    }
    if ((key === "neutrophils" || key === "lymphocytes" || key === "eosinophils" ||
         key === "monocytes" || key === "basophils") && (value < 0 || value > 100)) {
      return labels[key] + " " + fmt(value) + " is outside 0–100%. It was not changed.";
    }
    if (key === "crp" && value > 500) {
      return "CRP " + fmt(value) + " is not plausible as mg/L. It was not converted.";
    }
    if (key === "esr" && (value < 0 || value > 200)) {
      return "ESR " + fmt(value) + " mm/hr is not plausible. It was not changed.";
    }
    if (key === "pct" && (value < 0 || value > 100)) {
      return "Procalcitonin " + fmt(value) + " ng/mL is not plausible. It was not changed.";
    }
    if (key === "b12" && (value <= 0 || value > 5000)) {
      return "Vitamin B12 " + fmt(value) + " is not plausible as pg/mL. It was not converted.";
    }
    if (key === "folate" && (value <= 0 || value > 200)) {
      return "Folate " + fmt(value) + " is not plausible as ng/mL. It was not converted.";
    }
    if (key === "mma" && (value < 0 || value > 50)) {
      return "Methylmalonic acid " + fmt(value) + " is not plausible as µmol/L. It was not converted.";
    }
    if (key === "ferritin" && (value < 0 || value > 10000)) {
      return "Ferritin " + fmt(value) + " ng/mL is not plausible. It was not changed.";
    }
    return "";
  }

  var blocked = {};
  ["hemoglobin", "hematocrit", "rbc", "mcv", "mch", "mchc", "rdw", "wbc", "platelets",
   "neutrophils", "lymphocytes", "eosinophils", "monocytes", "basophils",
   "crp", "esr", "pct", "b12", "folate", "mma", "ferritin"].forEach(function (key) {
    var problem = unitProblem(key, num(key));
    if (!problem) return;
    blocked[key] = true;
    raise("borderline");
    note(problem, "find");
  });

  var diffKeys = ["neutrophils", "lymphocytes", "eosinophils", "monocytes", "basophils"];
  var diffParts = [];
  var diffSum = 0;
  var diffCount = 0;
  diffKeys.forEach(function (key) {
    if (!present(key)) return;
    var n = num(key);
    if (n == null || blocked[key]) return;
    diffCount++;
    diffSum += n;
    diffParts.push(labels[key] + " " + fmt(n) + "%");
  });
  diffSum = Math.round(diffSum * 100) / 100;
  var diffMissing = diffKeys.filter(function (key) { return !present(key); })
    .map(function (key) { return labels[key]; });
  if (diffCount >= 2 && (diffSum > 102 || (diffCount === 5 && diffSum < 98))) {
    differentialUnreliable = true;
    raise("borderline");
    note(
      "Differential percentages are inconsistent: " + diffParts.join(", ") +
      " total " + fmt(diffSum) + "%. These percentages should total about 100%, allowing for ordinary rounding. " +
      "Interpretation of the white-cell differential is unreliable until these entries are verified. The entered values were not changed.",
      "find"
    );
  } else if (diffCount > 0 && diffCount < 5) {
    note(
      "White-cell differential is incomplete. Not entered: " + diffMissing.join(", ") +
      ". Those lines are not treated as normal.",
      "limit"
    );
  }

  var age = patient.age;
  var sex = String(patient.sex || "").toLowerCase();
  var child = age != null && isFinite(age) && age < 18;
  var hbLow = 13.5, hbHigh = 17.5, hctLow = 38, hctHigh = 50;
  if (child) { hbLow = 11.5; hbHigh = 15.5; hctLow = 34; hctHigh = 45; }
  else if (sex === "female" || sex === "f") { hbLow = 12; hbHigh = 15.5; hctLow = 36; hctHigh = 46; }
  var who = child ? "under-18 range" : ((sex === "female" || sex === "f") ? "adult female range" : "adult range used when sex is not recorded");

  var hb = blocked.hemoglobin ? null : num("hemoglobin");
  var hct = blocked.hematocrit ? null : num("hematocrit");
  var rbc = blocked.rbc ? null : num("rbc");
  var mcv = blocked.mcv ? null : num("mcv");
  var mch = blocked.mch ? null : num("mch");
  var mchc = blocked.mchc ? null : num("mchc");
  var wbc = blocked.wbc ? null : num("wbc");
  var crp = blocked.crp ? null : num("crp");
  var esr = blocked.esr ? null : num("esr");
  var pct = blocked.pct ? null : num("pct");
  var ferritin = blocked.ferritin ? null : num("ferritin");
  var b12 = blocked.b12 ? null : num("b12");
  var folate = blocked.folate ? null : num("folate");
  var mma = blocked.mma ? null : num("mma");
  var hsCrp = num("hsCrp");
  var neut = blocked.neutrophils ? null : num("neutrophils");
  var lymph = blocked.lymphocytes ? null : num("lymphocytes");

  if (hb != null && hct != null) {
    var expectedHct = hb * 3;
    if (Math.abs(hct - expectedHct) > 8) {
      raise("borderline");
      note(
        "Hemoglobin (" + fmt(hb) + " g/dL) and hematocrit (" + fmt(hct) +
        "%) disagree. In these units hematocrit is often near three times hemoglobin (" +
        fmt(expectedHct) + "%). Both values were left as entered, so red-cell interpretation is limited until they are checked.",
        "find"
      );
    }
  }
  if (mcv != null && mch != null && mchc != null && mcv > 0) {
    var expectedMchc = (mch / mcv) * 100;
    if (Math.abs(mchc - expectedMchc) > 4) {
      raise("borderline");
      note(
        "MCH (" + fmt(mch) + " pg), MCV (" + fmt(mcv) + " fL) and MCHC (" + fmt(mchc) +
        " g/dL) do not agree. MCHC calculated from MCH and MCV would be about " +
        fmt(expectedMchc) + " g/dL. None of the entries was overwritten.",
        "find"
      );
    }
  }
  if (rbc != null && mcv != null && hct != null) {
    var expectedFromRbc = (rbc * mcv) / 10;
    if (Math.abs(hct - expectedFromRbc) > 6) {
      raise("borderline");
      note(
        "RBC (" + fmt(rbc) + " ×10¹²/L), MCV (" + fmt(mcv) + " fL) and hematocrit (" +
        fmt(hct) + "%) do not agree. Hematocrit estimated from RBC and MCV would be about " +
        fmt(expectedFromRbc) + "%. The entries were not changed.",
        "find"
      );
    }
  }

  if (hb != null && hb < hbLow) {
    raise(hb < 10 ? "abnormal" : "borderline");
    if (mcv != null && mcv < 80) {
      var micro = "Hemoglobin " + fmt(hb) + " g/dL is below the " + who + " (" + hbLow + "–" + hbHigh +
        " g/dL), with MCV " + fmt(mcv) + " fL. Together these support a microcytic anemia pattern, not a confirmed cause.";
      if (mch != null && mch < 27) micro += " MCH " + fmt(mch) + " pg is also low.";
      if (mchc != null && mchc < 32) micro += " MCHC " + fmt(mchc) + " g/dL is also low.";
      if (ferritin != null && ferritin < 30) {
        micro += " Ferritin " + fmt(ferritin) + " ng/mL is low and supports depleted iron stores, without proving the mechanism.";
      } else if (ferritin == null) {
        micro += " Ferritin is not recorded, so iron deficiency is not established and is not excluded.";
      } else if (crp != null && crp > 5) {
        micro += " Ferritin " + fmt(ferritin) + " ng/mL is not low, and CRP is " + fmt(crp) +
          " mg/L, so inflammation may be raising ferritin. Iron deficiency is neither confirmed nor excluded.";
      } else {
        micro += " Ferritin " + fmt(ferritin) + " ng/mL is not low, so this pattern alone does not establish iron deficiency.";
      }
      note(micro, "find");
    } else if (mcv != null && mcv > 100) {
      var macro = "Hemoglobin " + fmt(hb) + " g/dL is below the " + who + " (" + hbLow + "–" + hbHigh + " g/dL), with MCV " + fmt(mcv) +
        " fL. Together these support a macrocytic anemia pattern, not a confirmed nutritional diagnosis.";
      if (b12 != null && b12 < 300) macro += " Vitamin B12 " + fmt(b12) + " pg/mL is below 300 and is consistent with a B12 contribution.";
      else if (b12 == null) macro += " Vitamin B12 is not recorded.";
      if (folate != null && folate < 6) macro += " Folate " + fmt(folate) + " ng/mL is below 6 and is consistent with a folate contribution.";
      else if (folate == null) macro += " Folate is not recorded.";
      if (mma != null && mma > 0.56) macro += " Methylmalonic acid " + fmt(mma) + " µmol/L is above 0.56 and supports functional B12 deficiency as a possibility, not a confirmed diagnosis.";
      else if (mma == null) macro += " Methylmalonic acid is not recorded, so functional B12 deficiency cannot be assessed.";
      note(macro, "find");
    } else if (mcv != null) {
      note(
        "Hemoglobin " + fmt(hb) + " g/dL is below the " + who + " (" + hbLow + "–" + hbHigh + " g/dL), while MCV " + fmt(mcv) +
        " fL is between 80 and 100. This is a normocytic picture. The cause is not identified from these measurements.",
        "find"
      );
    } else {
      note(
        "Hemoglobin " + fmt(hb) + " g/dL is below the " + who + " (" + hbLow + "–" + hbHigh + " g/dL). MCV is not recorded, so red-cell size cannot be classified, and the missing MCV is not treated as normal.",
        "find"
      );
    }
  } else if (hb != null && hb > hbHigh) {
    raise("borderline");
    note(
      "Hemoglobin " + fmt(hb) + " g/dL is above the " + who + " (" + hbLow + "–" + hbHigh + " g/dL)" +
      (hct != null && hct > hctHigh ? (", and hematocrit " + fmt(hct) + "% is also high. The two results agree on a high red-cell mass or hemoconcentration pattern, without identifying the cause.") : ". Hematocrit is not available to check whether the red-cell mass agrees."),
      "find"
    );
  }

  var inflam = [];
  if (crp != null && crp > 5) {
    raise("borderline");
    inflam.push("CRP " + fmt(crp) + " mg/L");
  }
  if (esr != null && esr > 20) {
    raise("borderline");
    inflam.push("ESR " + fmt(esr) + " mm/hr");
  }
  if (pct != null && pct >= 0.5) {
    raise("borderline");
    inflam.push("procalcitonin " + fmt(pct) + " ng/mL");
  }
  if (inflam.length) {
    note(
      "Inflammatory activity is suggested by " + inflam.join(", ") +
      ". This combination does not confirm infection or a specific inflammatory disease.",
      "find"
    );
  }
  if (pct != null && pct < 0.5 && crp != null && crp > 10) {
    note(
      "Procalcitonin " + fmt(pct) + " ng/mL is below 0.5 while CRP is " + fmt(crp) +
      " mg/L. CRP shows inflammatory activity. Procalcitonin does not add support for a strong bacterial pattern. Neither result excludes infection.",
      "find"
    );
  }
  if (hsCrp != null && hsCrp > 3 && (crp == null || crp <= 5)) {
    raise("borderline");
    note(
      "hs-CRP " + fmt(hsCrp) + " mg/L is above 3. That supports low-grade inflammatory activity and does not establish a diagnosis.",
      "find"
    );
  }
  if (wbc != null && wbc > 11) {
    raise("borderline");
    if (differentialUnreliable) {
      note(
        "WBC " + fmt(wbc) + " ×10⁹/L is above 11. The differential percentages are inconsistent, so they cannot show which white-cell line accounts for the elevation.",
        "find"
      );
    } else if (neut != null && neut > 70) {
      note(
        "WBC " + fmt(wbc) + " ×10⁹/L is above 11 and neutrophils are " + fmt(neut) +
        "%. Together this is a neutrophil-predominant white-cell pattern, not a confirmed bacterial infection.",
        "find"
      );
    }
  }
  if (!differentialUnreliable && neut != null && lymph != null && neut > 0 && lymph > 0 &&
      typeof OSIRIS_calculateNLR === "function") {
    var nlr = OSIRIS_calculateNLR(neut, lymph);
    if (nlr != null && nlr >= 3 && (crp == null || crp > 5 || (wbc != null && wbc > 11))) {
      note(
        "The neutrophil/lymphocyte ratio from the entered percentages is " + fmt(nlr) +
        ". It is the same canonical ratio (neutrophils divided by lymphocytes) and is reported only as a white-cell balance, not as a diagnosis.",
        "limit"
      );
    }
  } else if (differentialUnreliable && neut != null && lymph != null && lymph > 0 &&
      typeof OSIRIS_calculateNLR === "function") {
    var badNlr = OSIRIS_calculateNLR(neut, lymph);
    if (badNlr != null) {
      note(
        "A neutrophil/lymphocyte ratio calculated from these entries would be " + fmt(badNlr) +
        ". It is not stored, because the differential percentages are inconsistent.",
        "limit"
      );
    }
  }

  var eos = blocked.eosinophils ? null : num("eosinophils");
  var mono = blocked.monocytes ? null : num("monocytes");
  var baso = blocked.basophils ? null : num("basophils");
  var rdw = blocked.rdw ? null : num("rdw");
  var componentOutOfRange = (neut != null && (neut > 70 || neut < 40)) ||
    (lymph != null && (child ? (lymph < 20 || lymph > 60) : (lymph < 20 || lymph > 40))) ||
    (eos != null && (eos > 6 || eos < 1)) ||
    (mono != null && (mono > 10 || mono < 2)) ||
    (baso != null && (baso < 0.5 || baso > 1)) ||
    (mch != null && (mch < 27 || mch > 33)) ||
    (mchc != null && (mchc < 32 || mchc > 36)) ||
    (mcv != null && (mcv < 80 || mcv > 100)) ||
    (rdw != null && rdw > 14.5) ||
    (hb != null && (hb < hbLow || hb > hbHigh)) ||
    (hct != null && (hct < hctLow || hct > hctHigh)) ||
    (wbc != null && (wbc < 4 || wbc > 11)) ||
    (crp != null && crp > 5) ||
    (esr != null && esr > 20) ||
    (pct != null && pct >= 0.5);
  if (status === "normal" && entered > 0 && !findings.length && !componentOutOfRange) {
    note(
      "No out-of-range pattern or internal disagreement was identified in the hematology measurements that were entered. Values in the usual ranges are not evidence that anaemia, inflammation, or a nutritional deficiency is absent.",
      "limit"
    );
  }
  if (entered > 0 && (hb == null || mcv == null || neut == null)) {
    var absent = [];
    if (hb == null && !present("hemoglobin")) absent.push("hemoglobin");
    if (mcv == null && !present("mcv")) absent.push("MCV");
    if (neut == null && !present("neutrophils")) absent.push("neutrophils");
    if (absent.length && findings.length) {
      note("Not recorded, and not treated as normal: " + absent.join(", ") + ".", "limit");
    }
  }

  return {
    status: status,
    findings: findings,
    limitations: limitations,
    lines: lines,
    entered: entered,
    differentialUnreliable: differentialUnreliable
  };
}

function OSIRIS_attachHematologyCombined(el, source, asText) {
  if (!el) return;
  var panel;
  try {
    panel = OSIRIS_assessHematologyPanel(OSIRIS_hematologyPanelFromDom(source));
  } catch (ePanel) { return; }
  if (!panel || !panel.lines || !panel.lines.length) return;
  if (asText) {
    var curText = el.innerText || "";
    if (curText.indexOf("Differential percentages are inconsistent") !== -1) return;
    var blockText = panel.lines.join("\n");
    el.innerText = panel.differentialUnreliable
      ? (blockText + "\n\n" + curText)
      : (curText ? (curText + "\n\n" + blockText) : blockText);
    return;
  }
  if ((el.innerHTML || "").indexOf("Differential percentages are inconsistent") !== -1) return;
  var html = panel.lines.map(OSIRIS_hematologyEsc).join("<br>");
  el.innerHTML = panel.differentialUnreliable
    ? (html + "<br><br>" + (el.innerHTML || ""))
    : ((el.innerHTML || "") + (el.innerHTML ? "<br><br>" : "") + html);
}

if (typeof window !== "undefined") {
  window.OSIRIS_assessHematologyPanel = OSIRIS_assessHematologyPanel;
  window.OSIRIS_hematologyPanelFromDom = OSIRIS_hematologyPanelFromDom;
}

function interpretHematology(context) {
  const result = {
    category: "hematology",
    status: "normal",
    findings: [],
    interpretations: [],
    nextSteps: [],
    suggestedTests: [],
    medicationNotes: [],
    warnings: [],
    missing: []
  };

  const readNum = (id) => {
    const el = document.getElementById(id);
    if (!el || el.value === undefined || el.value === null) return NaN;
    const v = String(el.value).trim();
    return v === "" ? NaN : parseFloat(v);
  };

  const hemoglobin = readNum('hematologyHemoglobin');
  const hematocrit = readNum('hematologyHematocrit');
  const mcv        = readNum('hematologyMeanCorpuscularVolume');
  const rdw        = readNum('hematologyRedCellDistributionWidth');
  const neutrophils= readNum('hematologyNeutrophils');
  const lymphocytes= readNum('hematologyLymphocytes');
  const eosinophils= readNum('hematologyEosinophils');
  const monocytes  = readNum('hematologyMonocytes');
  const contextNlr = context && context.labs ? Number(context.labs.nlr) : NaN;
  const canonicalNlr = isFinite(contextNlr) && contextNlr > 0
    ? Number(contextNlr.toFixed(2)) : null;
  if (canonicalNlr != null) result.nlr = canonicalNlr;

  var hemePanel = null;
  try {
    hemePanel = OSIRIS_assessHematologyPanel(OSIRIS_hematologyPanelFromDom("hematology"));
  } catch (eHemePanel) { hemePanel = null; }
  const anyEntered = [hemoglobin, hematocrit, mcv, rdw, neutrophils, lymphocytes,
                      eosinophils, monocytes].some(v => !isNaN(v)) ||
                      !!(hemePanel && hemePanel.entered);
  if (!anyEntered) {
    result.missing.push("Enter at least one hematology value.");
    _applyMedImpact(result, "hematology", context && context.medicationImpact);
    return result;
  }

  if (!isNaN(hemoglobin)) {
    if (hemoglobin < 13.5) {
      result.findings.push(`Low hemoglobin: ${hemoglobin}.`);
      result.interpretations.push("Low hemoglobin may reflect anemia, blood loss, or reduced red cell production.");
      result.suggestedTests.push("Iron studies, B12, folate, reticulocyte count.");
      result.status = _raiseStatus(result.status, hemoglobin < 10 ? "abnormal" : "borderline");
    } else if (hemoglobin > 17.5) {
      result.findings.push(`High hemoglobin: ${hemoglobin}.`);
      result.interpretations.push("Elevated hemoglobin may reflect dehydration or chronic hypoxia.");
      result.status = _raiseStatus(result.status, "borderline");
    }
  }

  if (!isNaN(hematocrit) && (hematocrit < 38 || hematocrit > 50)) {
    result.findings.push(`Hematocrit out of range: ${hematocrit}%.`);
    result.status = _raiseStatus(result.status, "borderline");
  }

  if (!isNaN(mcv)) {
    if (mcv < 80) {
      result.findings.push(`Microcytosis (MCV ${mcv}).`);
      result.interpretations.push("Small red cells often reflect iron deficiency or thalassemia trait.");
      result.status = _raiseStatus(result.status, "borderline");
    } else if (mcv > 100) {
      result.findings.push(`Macrocytosis (MCV ${mcv}).`);
      result.interpretations.push("Large red cells may reflect B12/folate deficiency, liver, or thyroid issues.");
      result.status = _raiseStatus(result.status, "borderline");
    }
  }

  if (!isNaN(rdw) && rdw > 14.5) {
    result.findings.push(`Elevated RDW: ${rdw}.`);
    result.interpretations.push("Variable red cell size supports evolving or mixed anemia pattern.");
    result.status = _raiseStatus(result.status, "borderline");
  }

  if (!isNaN(neutrophils)) {
    if (neutrophils > 70) {
      result.findings.push(`High neutrophils: ${neutrophils}%.`);
      result.interpretations.push("Neutrophilia often reflects acute infection or inflammatory stress.");
      result.status = _raiseStatus(result.status, "borderline");
    } else if (neutrophils < 40) {
      result.findings.push(`Low neutrophils: ${neutrophils}%.`);
      result.status = _raiseStatus(result.status, "borderline");
    }
  }

  if (!isNaN(lymphocytes)) {
    if (lymphocytes > 45) {
      result.findings.push(`High lymphocytes: ${lymphocytes}%.`);
      result.interpretations.push("Lymphocytosis often reflects viral activity.");
      result.status = _raiseStatus(result.status, "borderline");
    } else if (lymphocytes < 20) {
      result.findings.push(`Low lymphocytes: ${lymphocytes}%.`);
      result.status = _raiseStatus(result.status, "borderline");
    }
  }

  if (!isNaN(eosinophils) && eosinophils > 6) {
    result.findings.push(`Elevated eosinophils: ${eosinophils}%.`);
    result.interpretations.push("Eosinophilia may reflect allergic or parasitic involvement.");
    result.status = _raiseStatus(result.status, "borderline");
  }

  if (!isNaN(monocytes) && monocytes > 10) {
    result.findings.push(`Elevated monocytes: ${monocytes}%.`);
    result.status = _raiseStatus(result.status, "borderline");
  }

  if (hemePanel) {
    if (hemePanel.differentialUnreliable) delete result.nlr;
    hemePanel.findings.forEach(function (line) {
      if (result.findings.indexOf(line) === -1) result.findings.push(line);
    });
    hemePanel.limitations.forEach(function (line) {
      if (result.interpretations.indexOf(line) === -1) result.interpretations.push(line);
    });
    result.status = _raiseStatus(result.status, hemePanel.status);
  }

  _contributeCluster(["oxygenTransportStress","immuneDysregulation"], result.status, result.findings.length);
  _applyMedImpact(result, "hematology", context && context.medicationImpact);
  return result;
}

  
function getNumericInputs() {
  return {
    temperature: (function () {
      var raw = document.getElementById("temperatureInput")?.value || null;
      if (raw == null || String(raw).trim() === "") return null;
      if (typeof OSIRIS_asEnteredBodyTemp === "function" &&
          OSIRIS_asEnteredBodyTemp(raw) == null) return null;
      return raw;
    })(),
    systolic: document.getElementById("systolic")?.value || null,
    diastolic: document.getElementById("diastolic")?.value || null,
    pulse: document.getElementById("pulse")?.value || null
  };
}
  
  
  
  

  

function buildDiagnosticContext() {
  if (typeof OSIRIS_refreshCanonicalNLR === "function") {
    try {
      OSIRIS_refreshCanonicalNLR({ clearInvalid: true, persist: false });
    } catch (eNlrContext) {}
  }
  const baseline = getPatientBaseline();

  var context = {
    baseline,
    patient: {
      age: baseline.age,
      sex: baseline.sex,
      heightCm: baseline.height,
      weightKg: baseline.weight
    },
    derived: {
      bmi: baseline.bmi,
      bmr: baseline.bmr
    },
    answers: getDiagnosticAnswers(),
    numbers: getNumericInputs(),
    medicationImpact: getMedicationImpact(baseline.medications)
  };
  // Known-metric consumption: sync patient_metrics, mirror into empty
  // sibling inputs, fold labs/vitals into context — not display-only prune.
  if (typeof OSIRIS_prepareKnownMetricsForDiagnostics === "function") {
    try {
      context = OSIRIS_prepareKnownMetricsForDiagnostics(context);
    } catch (ePrep) {}
  }
  return context;
}

