/* iter-28 — Free-text marker prune. Used by the Cluster Summary action
 * line and any other comma/conjunction-separated marker list that the
 * codebase emits as a single string (e.g. "Repeat CRP in 48–72h to
 * confirm trend; check ESR and WBC differential"). Splits on commas /
 * semicolons / " and " (preserving content inside parens), drops every
 * token whose body matches a known-metric pattern whose value is
 * currently set, then rebuilds. Returns "" if no tokens survive. */
function OSIRIS_pruneMarkersInString(s) {
  if (!s || typeof s !== "string") return s || "";
  if (typeof OSIRIS_KNOWN_METRICS === "undefined") return s;

  // Snapshot of patterns gated by "is this currently known".
  var knownPatterns = [];
  Object.keys(OSIRIS_KNOWN_METRICS).forEach(function (k) {
    var v = OSIRIS_getKnownMetric(k);
    if (v == null || v === "") return;
    (OSIRIS_KNOWN_METRICS[k].patterns || []).forEach(function (p) { knownPatterns.push(p); });
  });
  if (!knownPatterns.length) return s;

  // Verb prefixes the cluster strings start with — keep these even if all
  // following items get pruned (we drop the whole sentence in that case).
  var VERB_RE = /^(check|recheck|focus\s+on|prioriti[sz]e|repeat|document|review|confirm)\b/i;

  // Walk every "sentence/clause" (split on ';'). For each, isolate the verb
  // prefix, then split the remainder on ',' or ' and ' OUTSIDE of parens.
  var clauses = s.split(/\s*;\s*/);
  var keptClauses = [];
  clauses.forEach(function (clause) {
    var verb = "";
    var body = clause.trim();
    var vm = body.match(VERB_RE);
    if (vm) {
      verb = vm[0];
      body = body.slice(vm[0].length).trim();
    }
    // Tokenise on commas and " and " that are NOT inside parens.
    var tokens = body.split(/(?:\s*,\s*|\s+and\s+)(?![^()]*\))/i);
    var keptTokens = tokens.filter(function (tok) {
      var t = String(tok || "").trim();
      if (!t) return false;
      // Drop this token if any "currently-known" pattern matches it.
      for (var i = 0; i < knownPatterns.length; i++) {
        if (knownPatterns[i].test(t)) return false;
      }
      return true;
    });
    if (!keptTokens.length) return;       // entire clause dies
    var rebuilt = keptTokens.join(", ");
    keptClauses.push(verb ? (verb + " " + rebuilt) : rebuilt);
  });
  return keptClauses.join("; ");
}
