  /* ------------------------------------------------------------------
   * Render all metric graphs for a subsystem into a target container.
   * ------------------------------------------------------------------ */
  function _renderSubsystemGraphs(targetEl, subsystem, opts) {
    if (!targetEl) return 0;
    var wrap = document.createElement("div");
    wrap.className = "osiris-eqr-graphs";
    wrap.setAttribute("data-subsystem", subsystem);
    var ecgOnly = !!(opts && opts.ecgOnly);

    var rendered = 0;

    var keys = (!ecgOnly && SUBSYSTEM_METRICS[subsystem]) ? SUBSYSTEM_METRICS[subsystem] : [];
    if (keys && keys.length) {
      for (var i = 0; i < keys.length; i++) {
        var slot = document.createElement("div");
        slot.className = "osiris-eqr-graph";
        slot.setAttribute("data-metric", keys[i]);
        wrap.appendChild(slot);
        var res = _renderMetricGraph(slot, keys[i]);
        if (res.status === "rendered" || res.status === "empty") rendered++;
        if (res.status === "skipped") wrap.removeChild(slot);
      }
    }

    if (subsystem === "cardio") {
      var ecgSec = document.createElement("div");
      ecgSec.className = "osiris-eqr-ecg-subcard";
      ecgSec.setAttribute("data-eqr-ecg-section", "1");
      ecgSec.setAttribute("data-testid", "osiris-eqr-ecg-subcard");
      var ecgTitle = document.createElement("div");
      ecgTitle.className = "osiris-eqr-ecg-subcard-title";
      ecgTitle.textContent = "ECG";
      ecgTitle.setAttribute("aria-label", "ECG subsystem of Cardio");
      ecgSec.appendChild(ecgTitle);
      var ecgSlot = document.createElement("div");
      ecgSlot.className = "osiris-eqr-graph";
      ecgSlot.setAttribute("data-metric", "ecg-bundle");
      ecgSec.appendChild(ecgSlot);
      var ecgRes = _renderEcgBundleGraph(ecgSlot);
      if (ecgRes.status === "rendered" || ecgRes.status === "empty") rendered++;
      if (ecgRes.status === "skipped") {
        ecgSlot.innerHTML = "";
        var ecgEmpty = document.createElement("div");
        ecgEmpty.className = "osiris-eqr-graph-empty";
        ecgEmpty.textContent = "No ECG progression recorded yet.";
        ecgSlot.appendChild(ecgEmpty);
      }
      try { _renderEcgImageArchive(ecgSec); } catch (eImg) {}
      wrap.appendChild(ecgSec);
    }

    if (!wrap.children.length) return 0;
    // Append after any leading OSIRIS DIAGNOSIS chrome / assessment content.
    // insertBefore(firstChild) buried the diagnosis button under metrics
    // (Endocrine / Psychology). GI is the reference: diagnosis stays top-right.
    targetEl.appendChild(wrap);
    return rendered;
  }
