    var body = document.getElementById("osirisEqrBody");
    if (!body) return;
    var box = body.querySelector("[data-eqr-accessible-diag]");
    if (!box) return;
    var sectionId = box.getAttribute("data-eqr-accessible-diag");
    var html = _eqrRebuildLiveAccessibleHtml(sectionId);
