      + "  #welcome-box #osiris-doctor-pane .da-accept-btn,"
      + "  #welcome-box #osiris-doctor-pane .da-reject-btn{"
      + "    width:100%;max-width:100%;flex:none;margin:0;min-height:0;padding:4px 15px;}"
      + "  #welcome-box #osiris-doctor-pane .da-revoke-btn{"
      + "    width:40%;max-width:40%;flex:0 0 40%;margin:0;min-height:0;height:auto;"
      + "    padding:2px 8px;font-size:12px;border-radius:5px;text-transform:lowercase;"
      + "    white-space:nowrap;word-break:normal;overflow-wrap:normal;}"
      /* Keep tile REVOKE horizontal on mobile (40% of card, no letter stacking). */
      + "  #welcome-box #osiris-doctor-pane .da-tile .da-revoke-btn{"
      + "    width:40%;max-width:40%;padding:2px 8px;font-size:12px;"
      + "    border-radius:5px;text-transform:lowercase;"
      + "    white-space:nowrap;word-break:normal;overflow-wrap:normal;}"
      + "  #osiris-doctor-pane .da-action-row{flex-wrap:wrap;flex-direction:column;gap:8px;}"
      + "  #osiris-doctor-pane .da-detail-wrap{flex-direction:column;flex-wrap:nowrap;}"
      /* OPEN (1) → patient data (2) → CLOSE (3); display:contents already on actions. */
      + "  #osiris-doctor-pane .da-detail-actions{"
